window.ATLAS_BUNDLES=window.ATLAS_BUNDLES||{};window.ATLAS_BUNDLES["annotations-046"]={"UBR4":{"hgnc":"HGNC:30313","symbol":"UBR4","accessions":["Q5T4S7"],"name":"E3 ubiquitin-protein ligase UBR4","length":"5183","function":"E3 ubiquitin-protein ligase involved in different protein quality control pathways in the cytoplasm (PubMed:25582440, PubMed:29033132, PubMed:34893540, PubMed:37891180, PubMed:38030679, PubMed:38182926, PubMed:38297121). Component of the N-end rule pathway: ubiquitinates proteins bearing specific N-terminal residues that are destabilizing according to the N-end rule, leading to their degradation (PubMed:34893540, PubMed:37891180, PubMed:38030679). Recognizes both type-1 and type-2 N-degrons, containing positively charged amino acids (Arg, Lys and His) and bulky and hydrophobic amino acids, respectively (PubMed:38030679). Does not ubiquitinate proteins that are acetylated at the N-terminus (PubMed:37891180). Together with UBR5, part of a cytoplasm protein quality control pathway that prevents protein aggregation by catalyzing assembly of heterotypic 'Lys-11'-/'Lys-48'-linked branched ubiquitin chains on aggregated proteins, leading to substrate recognition by the segregase p97/VCP and degradation by the proteasome: UBR4 probably synthesizes mixed chains containing multiple linkages, while UBR5 is likely branching multiple 'Lys-48'-linked chains of substrates initially modified (PubMed:29033132). Together with KCMF1, part of a protein quality control pathway that catalyzes ubiquitination and degradation of proteins that have been oxidized in response to reactive oxygen species (ROS): recognizes proteins with an Arg-CysO3(H) degron at the N-terminus, and mediates assembly of heterotypic 'Lys-63'-/'Lys-27'-linked branched ubiquitin chains on oxidized proteins, leading to their degradation by autophagy (PubMed:34893540). Catalytic component of the silencing factor of the integrated stress response (SIFI) complex, a multiprotein complex that turns off the mitochondrial stress response after a specific stress event has been resolved (PubMed:38297121, PubMed:40328314, PubMed:40875847). The SIFI complex ubiquitinates and degrades (1) components of the HRI-mediated signaling of the integrated stress response, such as DELE1 and EIF2AK1/HRI, as well as (2) unimported mitochondrial precursors such as ABHD10 (PubMed:38297121, PubMed:40328314). Within the SIFI complex, UBR4 initiates ubiquitin chains that are further elongated or branched by KCMF1 (PubMed:38297121, PubMed:40328314, PubMed:40875847). Mediates ubiquitination of ACLY, leading to its subsequent degradation (PubMed:23932781). Together with clathrin, forms meshwork structures involved in membrane morphogenesis and cytoskeletal organization (PubMed:16214886)","subunit":"Component of the SIFI complex, which is a dimer of 2 heterotrimers, comprising two copies each of UBR4, KCMF1 and calmodulin (CALM1, CALM2 or CALM3) (PubMed:16214886, PubMed:25582440, PubMed:38297121, PubMed:40328314, PubMed:40875847). Interacts with E2 conjugating enzymes UBE2A and UBE2B; this interaction is important for ubiquitin chain elongation (PubMed:25582440, PubMed:38182926, PubMed:38297121, PubMed:40328314, PubMed:40875847). Interacts with RB1 (PubMed:16214886)\n(Microbial infection) Interacts with protein E7 from papilloma virus HPV-16, HPV-6B and HPV-11\n(Microbial infection) Interacts with Rift valley fever virus glycoprotein N; this interaction is important for viral RNA production","family":"Belongs to the UBR4 family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["16214886","23932781","25582440","29033132","34893540","37891180","38030679","38182926","38297121","40328314","40875847"],"location":"Cytoplasm；Cytoplasm, cytoskeleton；Endosome；Nucleus","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"泛素化/蛋白稳态；细胞骨架/纤毛；线粒体/代谢；注释原文：E3 ubiquitin-protein ligase involved in different protein quality control pathways in the cytoplasm (PubMed:25582440, PubMed:29033132, PubMed:34893540, PubMed:37891180, PubMed:38030679, PubMed:38182926, PubMed:38297121).","function_evidence":"含实验支持条目；ECO:0000269","categories":"泛素化/蛋白稳态；细胞骨架/纤毛；线粒体/代谢"},"UBR7":{"hgnc":"HGNC:20344","symbol":"UBR7","accessions":["Q8N806"],"name":"Putative E3 ubiquitin-protein ligase UBR7","length":"425","function":"E3 ubiquitin-protein ligase which is a component of the N-end rule pathway. Recognizes and binds to proteins bearing specific N-terminal residues that are destabilizing according to the N-end rule, leading to their ubiquitination and subsequent degradation","subunit":"无可用SUBUNIT段","family":"","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":[],"location":"当前记录无定位注释","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"泛素化/蛋白稳态；注释原文：E3 ubiquitin-protein ligase which is a component of the N-end rule pathway.","function_evidence":"含同源推断，不能当该成员实测；ECO:0000250","categories":"泛素化/蛋白稳态"},"UBTF":{"hgnc":"HGNC:12511","symbol":"UBTF","accessions":["P17480"],"name":"Nucleolar transcription factor 1","length":"764","function":"Recognizes the ribosomal RNA gene promoter and activates transcription mediated by RNA polymerase I (Pol I) through cooperative interactions with the transcription factor SL1/TIF-IB complex. It binds specifically to the upstream control element and can activate Pol I promoter escape","subunit":"Homodimer (By similarity). Part of Pol I pre-initiation complex (PIC), in which Pol I core assembles with RRN3 and promoter-bound UTBF and SL1/TIF-IB complex (PubMed:11250903, PubMed:11283244, PubMed:36271492). Interacts with TOP2A in the context of Pol I complex (PubMed:36271492). Interacts with TBP (PubMed:7982918). Interacts with TAF1A (PubMed:7491500). Interacts with RASL11A (By similarity). Binds to IRS1 and PIK3CA (By similarity). Interacts with DHX33 (PubMed:21930779). Interacts with PHF6 (PubMed:23229552). Interacts with CEBPA (isoform 1 and isoform 4) (PubMed:20075868). Interacts with DDX11 (PubMed:26089203). Interacts with NOP53 (PubMed:27729611). Interacts with ALKBH2","family":"","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["11250903","11283244","16858408","28777933","7982918"],"location":"Nucleus, nucleolus","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"染色质/转录调控；翻译/核糖体；注释原文：Recognizes the ribosomal RNA gene promoter and activates transcription mediated by RNA polymerase I (Pol I) through cooperative interactions with the transcription factor SL1/TIF-IB complex.","function_evidence":"含实验支持条目；ECO:0000269","categories":"染色质/转录调控；翻译/核糖体"},"UBTFL1":{"symbol":"UBTFL1","accessions":["P0CB47"],"name":"Upstream-binding factor 1-like protein 1","length":393,"function":"Essential for proliferation of the inner cell mass and trophectodermal cells in peri-implantation development","subunit":"无可用SUBUNIT段","domains":"InterPro: IPR009071 HMG_box_dom\nInterPro: IPR036910 HMG_box_dom_sf\nInterPro: IPR051762 UBF1\nPfam: PF00505 HMG_box","brief":"发育/分化；注释原文：Essential for proliferation of the inner cell mass and trophectodermal cells in peri-implantation development","function_evidence":"含同源推断，不能当该成员实测；ECO:0000250","categories":"发育/分化","location":"Cytoplasm；Nucleus","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020"},"UBTFL6":{"hgnc":"HGNC:35406","symbol":"UBTFL6","accessions":["P0CB48"],"name":"Putative upstream-binding factor 1-like protein 6","length":"400","function":"未获得FUNCTION段；不等于没有已发表研究","subunit":"无可用SUBUNIT段","family":"","domains":"DNA binding 107-175: HMG box 1 [ECO:0000255/PROSITE-ProRule/PRU00267]\nDNA binding 229-295: HMG box 2 [ECO:0000255/PROSITE-ProRule/PRU00267]","function_pmids":[],"location":"Nucleus","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"本次数据库无可用FUNCTION；只可据蛋白名称/结构域提出方向，不据此称全新功能。","function_evidence":"本次数据库无FUNCTION段；不等于无研究/无功能","categories":"未归类"},"UBXN1":{"hgnc":"HGNC:18402","symbol":"UBXN1","accessions":["Q04323"],"name":"UBX domain-containing protein 1","length":"297","function":"Ubiquitin-binding protein that plays a role in the modulation of innate immune response. Blocks both the RIG-I-like receptors (RLR) and NF-kappa-B pathways. Following viral infection, UBXN1 is induced and recruited to the RLR component MAVS. In turn, interferes with MAVS oligomerization, and disrupts the MAVS/TRAF3/TRAF6 signalosome. This function probably serves as a brake to prevent excessive RLR signaling (PubMed:23545497). Interferes with the TNFalpha-triggered NF-kappa-B pathway by interacting with cellular inhibitors of apoptosis proteins (cIAPs) and thereby inhibiting their recruitment to TNFR1 (PubMed:25681446). Also prevents the activation of NF-kappa-B by associating with CUL1 and thus inhibiting NF-kappa-B inhibitor alpha/NFKBIA degradation that remains bound to NF-kappa-B (PubMed:28152074). Interacts with the BRCA1-BARD1 heterodimer and regulates its activity. Specifically binds 'Lys-6'-linked polyubiquitin chains. Interaction with autoubiquitinated BRCA1 leads to the inhibition of the E3 ubiquitin-protein ligase activity of the BRCA1-BARD1 heterodimer (PubMed:20351172). Component of a complex required to couple deglycosylation and proteasome-mediated degradation of misfolded proteins in the endoplasmic reticulum that are retrotranslocated in the cytosol","subunit":"Interacts with MAVS; this interaction prevents MAVS oligomerization and thus disrupts the RLR signaling pathway (PubMed:23545497). Interacts with CUL1; this interaction inhibits CUL1-mediated degradation of NF-kappa-B inhibitors (PubMed:28152074). Interacts with BIRC2/c-IAP1; this interaction prevents TNFalpha-stimulated RIP1 ubiquitination and subsequent NF-kappa-B activation (PubMed:25681446). Component of a complex required to couple retrotranslocation, ubiquitination and deglycosylation composed of NGLY1, SAKS1, AMFR, VCP and RAD23B. Interacts with HOMER2 (By similarity). Interacts directly with VCP. Interacts with BRCA1 and BARD1; interaction takes place when BRCA1 is not autoubiquitinated but is strongly enhanced in the presence of autoubiquitinated BRCA1\n(Microbial infection) Interacts (via C-terminal UBX domain) with nipah virus protein V","family":"","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["20351172","23545497","25681446","28152074"],"location":"Cytoplasm","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"泛素化/蛋白稳态；免疫/炎症/细胞死亡；黏附/受体/细胞表面；注释原文：Ubiquitin-binding protein that plays a role in the modulation of innate immune response.","function_evidence":"含实验支持条目；ECO:0000269","categories":"泛素化/蛋白稳态；免疫/炎症/细胞死亡；黏附/受体/细胞表面"},"UBXN2B":{"hgnc":"HGNC:27035","symbol":"UBXN2B","accessions":["Q14CS0"],"name":"UBX domain-containing protein 2B","length":"331","function":"Adapter protein required for Golgi and endoplasmic reticulum biogenesis (PubMed:17141156). Involved in Golgi and endoplasmic reticulum maintenance during interphase and in their reassembly at the end of mitosis (PubMed:17141156). The complex formed with VCP has membrane fusion activity; membrane fusion activity requires USO1-GOLGA2 tethering and BET1L (PubMed:17141156). VCPIP1 is also required, but not its deubiquitinating activity (PubMed:17141156). Together with NSFL1C/p47, regulates the centrosomal levels of kinase AURKA/Aurora A during mitotic progression by promoting AURKA removal from centrosomes in prophase (PubMed:23649807). Also, regulates spindle orientation during mitosis (PubMed:23649807)","subunit":"Interacts with VCP. Does not bind ubiquitin","family":"Belongs to the NSFL1C family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["17141156","23649807"],"location":"Nucleus；Cytoplasm, cytosol；Endoplasmic reticulum；Golgi apparatus；Cytoplasm, cytoskeleton, microtubule organizing center, centrosome","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"泛素化/蛋白稳态；细胞周期/分裂；激酶/磷酸化信号；膜运输/高尔基/内吞；细胞骨架/纤毛；注释原文：Adapter protein required for Golgi and endoplasmic reticulum biogenesis (PubMed:17141156).","function_evidence":"含实验支持条目；ECO:0000269","categories":"泛素化/蛋白稳态；细胞周期/分裂；激酶/磷酸化信号；膜运输/高尔基/内吞；细胞骨架/纤毛"},"UBXN4":{"hgnc":"HGNC:14860","symbol":"UBXN4","accessions":["Q92575"],"name":"UBX domain-containing protein 4","length":"508","function":"Involved in endoplasmic reticulum-associated protein degradation (ERAD). Acts as a platform to recruit both UBQLN1 and VCP to the ER during ERAD (PubMed:19822669)","subunit":"Directly interacts with VCP. Interacts with UBQLN1. Forms a complex with VCP and UBQLN1","family":"","domains":[],"function_pmids":["16968747","19822669"],"location":"Endoplasmic reticulum membrane; Nucleus envelope","shared_sequence_gene_count":"1","source_snapshot":"project UniProt records20261017/18","brief":"Involved in endoplasmic reticulum-associated protein degradation (ERAD). Acts as a platform to recruit both UBQLN1 and VCP to the ER during ERAD (PubMed:19822669)"},"UBXN6":{"hgnc":"HGNC:14928","symbol":"UBXN6","accessions":["Q9BZV1"],"name":"UBX domain-containing protein 6","length":"441","function":"May negatively regulate the ATPase activity of VCP, an ATP-driven segregase that associates with different cofactors to control a wide variety of cellular processes (PubMed:26475856). As a cofactor of VCP, it may play a role in the transport of CAV1 to lysosomes for degradation (PubMed:21822278, PubMed:23335559). It may also play a role in endoplasmic reticulum-associated degradation (ERAD) of misfolded proteins (PubMed:19275885). Together with VCP and other cofactors, it may play a role in macroautophagy, regulating for instance the clearance of damaged lysosomes (PubMed:27753622)","subunit":"Interacts with VCP through the PUB domain (via C-terminus) and VIM motif (via N-terminus); the interaction is direct (PubMed:18656546, PubMed:19174149, PubMed:21822278, PubMed:21896481, PubMed:26475856). Forms a ternary complex with CAV1 and VCP (PubMed:21822278). Interacts with SYVN1 (PubMed:18656546). Interacts with HERPUD1 (PubMed:18656546). Interacts with VCPKMT (PubMed:23349634). May interact with DERL1 (PubMed:19275885). Interacts with PLAA, VCP and YOD1; may form a complex involved in macroautophagy (PubMed:27753622). Interacts with LMAN1 (PubMed:22337587)","family":"","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["19275885","21822278","23335559","26475856","27753622"],"location":"Cytoplasm；Cytoplasm, cytosol；Membrane；Peripheral membrane protein；Nucleus；Cytoplasm, cytoskeleton, microtubule organizing center, centrosome；Early endosome membrane；Late endosome membrane；Lysosome membrane","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"；注释原文：May negatively regulate the ATPase activity of VCP, an ATP-driven segregase that associates with different cofactors to control a wide variety of cellular processes (PubMed:26475856).","function_evidence":"含实验支持条目；ECO:0000269","categories":"未归类"},"UBXN7":{"hgnc":"HGNC:29119","symbol":"UBXN7","accessions":["O94888"],"name":"UBX domain-containing protein 7","length":"489","function":"Ubiquitin-binding adapter that links a subset of NEDD8-associated cullin ring ligases (CRLs) to the segregase VCP/p97, to regulate turnover of their ubiquitination substrates","subunit":"Interacts with neddylated CUL2, ubiquitinated HIF1A, and VCP/p97","family":"","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["22537386"],"location":"Nucleus","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"泛素化/蛋白稳态；注释原文：Ubiquitin-binding adapter that links a subset of NEDD8-associated cullin ring ligases (CRLs) to the segregase VCP/p97, to regulate turnover of their ubiquitination substrates","function_evidence":"含实验支持条目；ECO:0000269","categories":"泛素化/蛋白稳态"},"UBXN8":{"hgnc":"HGNC:30307","symbol":"UBXN8","accessions":["O00124"],"name":"UBX domain-containing protein 8","length":"270","function":"Involved in endoplasmic reticulum-associated degradation (ERAD) for misfolded lumenal proteins, possibly by tethering VCP to the endoplasmic reticulum membrane. May play a role in reproduction","subunit":"Interacts with SYVN1 and VCP","family":"","domains":[],"function_pmids":["21949850"],"location":"Endoplasmic reticulum membrane","shared_sequence_gene_count":"1","source_snapshot":"project UniProt records20261017/18","brief":"Involved in endoplasmic reticulum-associated degradation (ERAD) for misfolded lumenal proteins, possibly by tethering VCP to the endoplasmic reticulum membrane. May play a role in reproduction"},"UCHL1":{"hgnc":"HGNC:12513","symbol":"UCHL1","accessions":["P09936"],"name":"Ubiquitin carboxyl-terminal hydrolase isozyme L1","length":"223","function":"Deubiquitinase that plays a role in the regulation of several processes such as maintenance of synaptic function, cardiac function, inflammatory response or osteoclastogenesis (PubMed:22212137, PubMed:23359680). Abrogates the ubiquitination of multiple proteins including WWTR1/TAZ, EGFR, HIF1A and beta-site amyloid precursor protein cleaving enzyme 1/BACE1 (PubMed:22212137, PubMed:25615526). In addition, recognizes and hydrolyzes a peptide bond at the C-terminal glycine of ubiquitin to maintain a stable pool of monoubiquitin that is a key requirement for the ubiquitin-proteasome and the autophagy-lysosome pathways (PubMed:12408865, PubMed:8639624, PubMed:9774100). Regulates amyloid precursor protein/APP processing by promoting BACE1 degradation resulting in decreased amyloid beta production (PubMed:22212137). Plays a role in the immune response by regulating the ability of MHC I molecules to reach cross-presentation compartments competent for generating Ag-MHC I complexes (By similarity). Mediates the 'Lys-48'-linked deubiquitination of the transcriptional coactivator WWTR1/TAZ leading to its stabilization and inhibition of osteoclastogenesis (By similarity). Deubiquitinates and stabilizes epidermal growth factor receptor EGFR to prevent its degradation and to activate its downstream mediators (By similarity). Modulates oxidative activity in skeletal muscle by regulating key mitochondrial oxidative proteins (By similarity). Enhances the activity of hypoxia-inducible factor 1-alpha/HIF1A by abrogateing its VHL E3 ligase-mediated ubiquitination and consequently inhibiting its degradation (PubMed:25615526)","subunit":"Monomer. Homodimer. Interacts with SNCA (By similarity). Interacts with COPS5","family":"Belongs to the peptidase C12 family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["12408865","22212137","23359680","25615526","8639624","9774100"],"location":"Cytoplasm；Endoplasmic reticulum membrane；Lipid-anchor","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"泛素化/蛋白稳态；染色质/转录调控；免疫/炎症/细胞死亡；线粒体/代谢；黏附/受体/细胞表面；注释原文：Deubiquitinase that plays a role in the regulation of several processes such as maintenance of synaptic function, cardiac function, inflammatory response or osteoclastogenesis (PubMed:22212137, PubMed:23359680).","function_evidence":"含实验支持条目；含同源推断，不能当该成员实测；ECO:0000250,ECO:0000269","categories":"泛素化/蛋白稳态；染色质/转录调控；免疫/炎症/细胞死亡；线粒体/代谢；黏附/受体/细胞表面"},"UCHL3":{"hgnc":"HGNC:12515","symbol":"UCHL3","accessions":["P15374"],"name":"Ubiquitin carboxyl-terminal hydrolase isozyme L3","length":"230","function":"Deubiquitinating enzyme (DUB) that controls levels of cellular ubiquitin through processing of ubiquitin precursors and ubiquitinated proteins (PubMed:19154770, PubMed:21762696, PubMed:22689415, PubMed:2530630). Thiol protease that recognizes and hydrolyzes a peptide bond at the C-terminal glycine of either ubiquitin or NEDD8 (PubMed:19154770, PubMed:21762696, PubMed:22689415, PubMed:2530630, PubMed:9790970). Has a 10-fold preference for Arg and Lys at position P3'', and exhibits a preference towards 'Lys-48'-linked ubiquitin chains (PubMed:19154770, PubMed:21762696, PubMed:22689415, PubMed:2530630). Can hydrolyze UBB(+1), a mutated form of ubiquitin which is not effectively degraded by the proteasome and is associated with neurodegenerative disorders (By similarity). Involved in DNA repair via homologous recombination (HR) by mediating deubiquitination of RAD51 in response to DNA damage, promoting interaction between RAD51 and BRCA2 (PubMed:27941124). Deubiquitinates ENAC in apical compartments, thereby regulating apical membrane recycling (By similarity). Indirectly increases the phosphorylation of IGFIR, AKT and FOXO1 and promotes insulin-signaling and insulin-induced adipogenesis (By similarity). Required for stress-response retinal, skeletal muscle and germ cell maintenance (By similarity). May be involved in working memory (By similarity)","subunit":"Preferentially binds diubiquitin; the interaction does not hydrolyze diubiquitin but, in vitro, inhibits the hydrolyzing activity on other substrates","family":"Belongs to the peptidase C12 family","domains":[],"function_pmids":["19154770","21762696","22689415","2530630","27941124","9790970"],"location":"Cytoplasm","shared_sequence_gene_count":"1","source_snapshot":"project UniProt records20261017/18","brief":"Deubiquitinating enzyme (DUB) that controls levels of cellular ubiquitin through processing of ubiquitin precursors and ubiquitinated proteins (PubMed:19154770, PubMed:21762696, PubMed:22689415, PubMed:2530630). Thiol protease that recognizes and hydrolyzes a peptide bond at the C-terminal glycine of either ubiquitin or NEDD8 (PubMed:19154770, PubMed:21762696, PubMed:22689415, PubMed:2530630, PubMed:9790970). Has a 10-fold preference for Arg and Lys at position P3'', and exhibits a preference towards 'Lys-48'-linked ubiquitin chains (PubMed:19154770, PubMed:21762696, PubMed:22689415, PubMed:2530630). Can hydrolyze UBB(+1), a mutated form of ubiquitin which is not effectively degraded by the proteasome and is associated with neurodegenerative disorders (By similarity). Involved in DNA repair via homologous recombination (HR) by mediating deubiquitination of RAD51 in response to DNA damage, promoting interaction between RAD51 and BRCA2 (PubMed:27941124). Deubiquitinates ENAC in apical compartments, thereby regulating apical membrane recycling (By similarity). Indirectly increases the phosphorylation of IGFIR, AKT and FOXO1 and promotes insulin-signaling and insulin-induced adipogenesis (By similarity). Required for stress-response retinal, skeletal muscle and germ cell maintenance (By similarity). May be involved in working memory (By similarity)"},"UCHL5":{"hgnc":"HGNC:19678","symbol":"UCHL5","accessions":["Q9Y5K5"],"name":"Ubiquitin carboxyl-terminal hydrolase isozyme L5","length":"329","function":"Protease that specifically cleaves 'Lys-48'-linked polyubiquitin chains. Deubiquitinating enzyme associated with the 19S regulatory subunit of the 26S proteasome. Putative regulatory component of the INO80 complex; however is inactive in the INO80 complex and is activated by a transient interaction of the INO80 complex with the proteasome via ADRM1","subunit":"Component of the 19S (PA700) regulatory complex of the 26S proteasome. Interacts with ADRM1 and NFRKB; in vitro ADRM1 and NFRKB compete for interaction with UCHL5. Component of the INO80 complex; specifically part of a complex module associated with N-terminus of INO80","family":"Belongs to the peptidase C12 family","domains":[],"function_pmids":["16906146","18922472"],"location":"Cytoplasm; Nucleus","shared_sequence_gene_count":"1","source_snapshot":"project UniProt records20261017/18","brief":"Protease that specifically cleaves 'Lys-48'-linked polyubiquitin chains. Deubiquitinating enzyme associated with the 19S regulatory subunit of the 26S proteasome. Putative regulatory component of the INO80 complex; however is inactive in the INO80 complex and is activated by a transient interaction of the INO80 complex with the proteasome via ADRM1"},"UCK2":{"hgnc":"HGNC:12562","symbol":"UCK2","accessions":["Q9BZX2"],"name":"Uridine-cytidine kinase 2","length":"261","function":"Phosphorylates uridine and cytidine to uridine monophosphate and cytidine monophosphate (PubMed:11306702, PubMed:11494055, PubMed:35583288). Does not phosphorylate deoxyribonucleosides or purine ribonucleosides (PubMed:11306702). Can use ATP or GTP as a phosphate donor (PubMed:11306702). Can also phosphorylate cytidine and uridine nucleoside analogs such as 6-azauridine, 5-fluorouridine, 4-thiouridine, 5-bromouridine, N(4)-acetylcytidine, N(4)-benzoylcytidine, 5-fluorocytidine, 2-thiocytidine, 5-methylcytidine, and N(4)-anisoylcytidine (PubMed:11306702)","subunit":"Homotetramer","family":"Belongs to the uridine kinase family","domains":[],"function_pmids":["11306702","11494055","35583288"],"location":"","shared_sequence_gene_count":"1","source_snapshot":"project UniProt records20261017/18","brief":"Phosphorylates uridine and cytidine to uridine monophosphate and cytidine monophosphate (PubMed:11306702, PubMed:11494055, PubMed:35583288). Does not phosphorylate deoxyribonucleosides or purine ribonucleosides (PubMed:11306702). Can use ATP or GTP as a phosphate donor (PubMed:11306702). Can also phosphorylate cytidine and uridine nucleoside analogs such as 6-azauridine, 5-fluorouridine, 4-thiouridine, 5-bromouridine, N(4)-acetylcytidine, N(4)-benzoylcytidine, 5-fluorocytidine, 2-thiocytidine, 5-methylcytidine, and N(4)-anisoylcytidine (PubMed:11306702)"},"UCKL1":{"hgnc":"HGNC:15938","symbol":"UCKL1","accessions":["Q9NWZ5"],"name":"Uridine-cytidine kinase-like 1","length":"548","function":"Phosphorylates uridine and cytidine to uridine monophosphate and cytidine monophosphate","subunit":"Interacts with RNF19B\n(Microbial infection) Interacts with Epstein-Barr virus/EBV EBNA3","family":"Belongs to the uridine kinase family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["35583288"],"location":"Cytoplasm；Nucleus","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"激酶/磷酸化信号；注释原文：Phosphorylates uridine and cytidine to uridine monophosphate and cytidine monophosphate","function_evidence":"含实验支持条目；ECO:0000269","categories":"激酶/磷酸化信号"},"UFC1":{"hgnc":"HGNC:26941","symbol":"UFC1","accessions":["Q9Y3C8"],"name":"Ubiquitin-fold modifier-conjugating enzyme 1","length":"167","function":"E2-like enzyme which specifically catalyzes the second step in ufmylation (PubMed:15071506, PubMed:29868776, PubMed:30626644, PubMed:34588452, PubMed:35394863, PubMed:36121123, PubMed:38383789). Accepts the ubiquitin-like modifier UFM1 from the E1 enzyme UBA5 and forms an intermediate with UFM1 via a thioester linkage (PubMed:15071506, PubMed:29868776, PubMed:34588452, PubMed:38383789). Ufmylation is involved in various processes, such as ribosome recycling, response to DNA damage, interferon response or reticulophagy (also called ER-phagy) (PubMed:27351204, PubMed:32160526, PubMed:35394863, PubMed:37036982, PubMed:38383789)","subunit":"Interacts with UBA5 (via C-terminus) (PubMed:17825256, PubMed:27653677, PubMed:29868776, PubMed:34588452). Interacts with UFL1 (PubMed:20018847, PubMed:30886146, PubMed:37988244, PubMed:38383789). Interacts with UFM1 (PubMed:29868776). Interacts with KIRREL3 (PubMed:25902260)","family":"Belongs to the ubiquitin-conjugating enzyme family. UFC1 subfamily","domains":[],"function_pmids":["15071506","27351204","29868776","30626644","32160526","34588452","35394863","36121123","37036982","38383789"],"location":"","shared_sequence_gene_count":"1","source_snapshot":"project UniProt records20261017/18","brief":"E2-like enzyme which specifically catalyzes the second step in ufmylation (PubMed:15071506, PubMed:29868776, PubMed:30626644, PubMed:34588452, PubMed:35394863, PubMed:36121123, PubMed:38383789). Accepts the ubiquitin-like modifier UFM1 from the E1 enzyme UBA5 and forms an intermediate with UFM1 via a thioester linkage (PubMed:15071506, PubMed:29868776, PubMed:34588452, PubMed:38383789). Ufmylation is involved in various processes, such as ribosome recycling, response to DNA damage, interferon response or reticulophagy (also called ER-phagy) (PubMed:27351204, PubMed:32160526, PubMed:35394863, PubMed:37036982, PubMed:38383789)"},"UFD1":{"hgnc":"HGNC:12520","symbol":"UFD1","accessions":["Q92890"],"name":"Ubiquitin recognition factor in ER-associated degradation protein 1","length":"307","function":"Essential component of the ubiquitin-dependent proteolytic pathway which degrades ubiquitin fusion proteins. The ternary complex containing UFD1, VCP and NPLOC4 binds ubiquitinated proteins and is necessary for the export of misfolded proteins from the ER to the cytoplasm, where they are degraded by the proteasome. The NPLOC4-UFD1-VCP complex regulates spindle disassembly at the end of mitosis and is necessary for the formation of a closed nuclear envelope. It may be involved in the development of some ectoderm-derived structures (By similarity). Acts as a negative regulator of type I interferon production via the complex formed with VCP and NPLOC4, which binds to RIGI and recruits RNF125 to promote ubiquitination and degradation of RIGI (PubMed:26471729)","subunit":"Heterodimer with NPLOC4, this heterodimer binds VCP and inhibits Golgi membrane fusion (PubMed:11574150, PubMed:26471729). Interacts with USP13 (PubMed:21571647). Interacts with ZFAND2B; probably through VCP (PubMed:24160817)","family":"Belongs to the UFD1 family","domains":[],"function_pmids":["26471729"],"location":"Nucleus; Cytoplasm, cytosol","shared_sequence_gene_count":"1","source_snapshot":"project UniProt records20261017/18","brief":"Essential component of the ubiquitin-dependent proteolytic pathway which degrades ubiquitin fusion proteins. The ternary complex containing UFD1, VCP and NPLOC4 binds ubiquitinated proteins and is necessary for the export of misfolded proteins from the ER to the cytoplasm, where they are degraded by the proteasome. The NPLOC4-UFD1-VCP complex regulates spindle disassembly at the end of mitosis and is necessary for the formation of a closed nuclear envelope. It may be involved in the development of some ectoderm-derived structures (By similarity). Acts as a negative regulator of type I interferon production via the complex formed with VCP and NPLOC4, which binds to RIGI and recruits RNF125 to promote ubiquitination and degradation of RIGI (PubMed:26471729)"},"UFL1":{"hgnc":"HGNC:23039","symbol":"UFL1","accessions":["O94874"],"name":"E3 UFM1-protein ligase 1","length":"794","function":"E3 protein ligase that mediates ufmylation, the covalent attachment of the ubiquitin-like modifier UFM1 to lysine residues on target proteins, and which plays a key role in various processes, such as ribosome recycling, response to DNA damage, interferon response or reticulophagy (also called ER-phagy) (PubMed:20018847, PubMed:20164180, PubMed:20228063, PubMed:25219498, PubMed:27351204, PubMed:30626644, PubMed:30783677, PubMed:32160526, PubMed:32807901, PubMed:35394863, PubMed:36121123, PubMed:36543799, PubMed:36893266, PubMed:37036982, PubMed:37311461, PubMed:37595036, PubMed:37795761, PubMed:38377992, PubMed:38383785, PubMed:38383789). Catalyzes ufmylation of many protein, such as CD274/PD-L1, CDK5RAP3, CYB5R3, DDRGK1, EIF6, histone H4, MRE11, P4HB, PDCD1/PD-1, TRIP4, RPN1, RPS20/uS10, RPL10/uL16, RPL26/uL24, SYVN1/HRD1 and TP53/p53 (PubMed:20018847, PubMed:20531390, PubMed:25219498, PubMed:30783677, PubMed:30886146, PubMed:32160526, PubMed:35753586, PubMed:36543799, PubMed:36893266, PubMed:37036982, PubMed:37595036, PubMed:37795761, PubMed:38383785, PubMed:38383789). As part of the UREL complex, plays a key role in ribosome recycling by catalyzing mono-ufmylation of RPL26/uL24 subunit of the 60S ribosome (PubMed:38383785, PubMed:38383789). Ufmylation of RPL26/uL24 occurs on free 60S ribosomes following ribosome dissociation: it weakens the junction between post-termination 60S subunits and SEC61 translocons, promoting release and recycling of the large ribosomal subunit from the endoplasmic reticulum membrane (PubMed:38383785, PubMed:38383789). Ufmylation of RPL26/uL24 and subsequent 60S ribosome recycling either take place after normal termination of translation or after ribosome stalling during cotranslational translocation at the endoplasmic reticulum (PubMed:37036982, PubMed:37595036, PubMed:38383785, PubMed:38383789). Involved in reticulophagy in response to endoplasmic reticulum stress by mediating ufmylation of proteins such as CYB5R3 and RPN1, thereby promoting lysosomal degradation of ufmylated proteins (PubMed:23152784, PubMed:32160526, PubMed:36543799). Ufmylation in response to endoplasmic reticulum stress is essential for processes such as hematopoiesis, blood vessel morphogenesis or inflammatory response (PubMed:32050156). Mediates ufmylation of DDRGK1 and CDK5RAP3; the role of these modifications is however unclear: as both DDRGK1 and CDK5RAP3 act as substrate adapters for ufmylation, it is uncertain whether ufmylation of these proteins is, a collateral effect or is required for ufmylation (PubMed:20018847, PubMed:20531390). Acts as a negative regulator of T-cell activation by mediating ufmylation and stabilization of PDCD1/PD-1 (PubMed:38377992). Also involved in the response to DNA damage: recruited to double-strand break sites following DNA damage and mediates monoufmylation of histone H4 and ufmylation of MRE11 (PubMed:30783677, PubMed:30886146). Mediates ufmylation of TP53/p53, promoting its stability (PubMed:32807901). Catalyzes ufmylation of TRIP4, thereby playing a role in nuclear receptor-mediated transcription (PubMed:25219498). Required for hematopoietic stem cell function and hematopoiesis (By similarity)","subunit":"Catalytic component of the UFM1 ribosome E3 ligase (UREL) complex, composed of UFL1, DDRGK1 and CDK5RAP3 (PubMed:20018847, PubMed:20164180, PubMed:20228063, PubMed:25219498, PubMed:32160526, PubMed:36121123, PubMed:36543799, PubMed:37595036, PubMed:38383785, PubMed:38383789). Interacts with E2-like enzyme UFC1 (PubMed:20018847, PubMed:30886146, PubMed:37988244, PubMed:38383789). Interacts with RELA (PubMed:20164180). Interacts with NBN; promoting recruitment to double-strand breaks following DNA damage (PubMed:30886146). Interacts (when phosphorylated) with YWHAG/14-3-3-gamma; sequestering UFL1 and preventing its association with PDCD1/PD-1 substrate (PubMed:38377992)\n(Microbial infection) Interacts with Epstein-Barr virus protein BILF1; this interaction mediates MAVS UFMylation and subsequent routing from mitochondria to lysosomes","family":"Belongs to the UFL1 family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["20018847","20164180","20228063","20531390","23152784","25219498","27351204","30626644","30783677","30886146","32050156","32160526","32807901","35394863","35753586","36121123","36543799","36893266","37036982","37311461","37595036","37795761","38377992","38383785","38383789"],"location":"Endoplasmic reticulum membrane；Cytoplasm, cytosol；Nucleus；Chromosome","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"泛素化/蛋白稳态；染色质/转录调控；DNA修复/复制；翻译/核糖体；免疫/炎症/细胞死亡；黏附/受体/细胞表面；注释原文：E3 protein ligase that mediates ufmylation, the covalent attachment of the ubiquitin-like modifier UFM1 to lysine residues on target proteins, and which plays a key role in various processes, such as ribosome recycling, response to DNA damage, interferon response or reticulophagy (also called ER-phagy) (PubMed:20018847, PubMed:20164180, PubMed:20228063, PubMed:25219498, PubMed:27351204, PubMed:30626644, PubMed:30783677, PubMed:32160526, PubMed:32807901, PubMed:35394863, PubMed:36121123, PubMed:36543799, PubMed:36893266, PubMed:37036982, PubMed:37311461, PubMed:37595036, PubMed:37795761, PubMed:38377992, PubMed:38383785, PubMed:38383789).","function_evidence":"含实验支持条目；含同源推断，不能当该成员实测；ECO:0000250,ECO:0000269","categories":"泛素化/蛋白稳态；染色质/转录调控；DNA修复/复制；翻译/核糖体；免疫/炎症/细胞死亡；黏附/受体/细胞表面"},"UFSP2":{"hgnc":"HGNC:25640","symbol":"UFSP2","accessions":["Q9NUQ7"],"name":"Ufm1-specific protease 2","length":"469","function":"Thiol-dependent isopeptidase that specifically cleaves UFM1, a ubiquitin-like modifier protein, from conjugated proteins, such as CD274/PD-L1, CYB5R3, DDRGK1, MRE11, RPL26/uL24, TRIP4 and RPL26/uL24 (PubMed:25219498, PubMed:27351204, PubMed:27926783, PubMed:30783677, PubMed:31595041, PubMed:32160526, PubMed:33473208, PubMed:35394863, PubMed:35926457, PubMed:36543799, PubMed:36893266, PubMed:37795761, PubMed:38383785). While it is also able to mediate the processing of UFM1 precursors, a prerequisite for conjugation reactions, UFSP2 mainly acts as a protein deUFMylase that mediates deconjugation of UFM1 from target proteins (PubMed:27926783). Mediates deUFMylation of RPL26/uL24, a critical step to release the UFM1 ribosome E3 ligase (UREL) complex during the recycling of 60S ribosome subunits from the endoplasmic reticulum (PubMed:38383785). Catalyzes deUFMylation of TRIP4, regulating intracellular nuclear receptors transactivation and thereby regulate cell proliferation and differentiation (PubMed:25219498)","subunit":"无可用SUBUNIT段","family":"Belongs to the peptidase C78 family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["25219498","27351204","27926783","30783677","31595041","32160526","33473208","35394863","35926457","36543799","36893266","37795761","38383785"],"location":"Endoplasmic reticulum；Cytoplasm；Nucleus","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"泛素化/蛋白稳态；翻译/核糖体；黏附/受体/细胞表面；发育/分化；注释原文：Thiol-dependent isopeptidase that specifically cleaves UFM1, a ubiquitin-like modifier protein, from conjugated proteins, such as CD274/PD-L1, CYB5R3, DDRGK1, MRE11, RPL26/uL24, TRIP4 and RPL26/uL24 (PubMed:25219498, PubMed:27351204, PubMed:27926783, PubMed:30783677, PubMed:31595041, PubMed:32160526, PubMed:33473208, PubMed:35394863, PubMed:35926457, PubMed:36543799, PubMed:36893266, PubMed:37795761, PubMed:38383785).","function_evidence":"含实验支持条目；ECO:0000269","categories":"泛素化/蛋白稳态；翻译/核糖体；黏附/受体/细胞表面；发育/分化"},"UGDH":{"hgnc":"HGNC:12525","symbol":"UGDH","accessions":["O60701"],"name":"UDP-glucose 6-dehydrogenase","length":"494","function":"Catalyzes the formation of UDP-alpha-D-glucuronate, a constituent of complex glycosaminoglycans (PubMed:21502315, PubMed:21961565, PubMed:22123821, PubMed:23106432, PubMed:25478983, PubMed:27966912, PubMed:30420606, PubMed:30457329). Required for the biosynthesis of chondroitin sulfate and heparan sulfate. Required for embryonic development via its role in the biosynthesis of glycosaminoglycans (By similarity). Required for proper brain and neuronal development (PubMed:32001716)","subunit":"Homohexamer","family":"Belongs to the UDP-glucose/GDP-mannose dehydrogenase family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["21502315","21961565","22123821","23106432","25478983","27966912","30420606","30457329","32001716"],"location":"当前记录无定位注释","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"发育/分化；注释原文：Catalyzes the formation of UDP-alpha-D-glucuronate, a constituent of complex glycosaminoglycans (PubMed:21502315, PubMed:21961565, PubMed:22123821, PubMed:23106432, PubMed:25478983, PubMed:27966912, PubMed:30420606, PubMed:30457329).","function_evidence":"含实验支持条目；含同源推断，不能当该成员实测；ECO:0000250,ECO:0000269","categories":"发育/分化"},"UHRF1":{"hgnc":"HGNC:12556","symbol":"UHRF1","accessions":["Q96T88"],"name":"E3 ubiquitin-protein ligase UHRF1","length":"793","function":"E3 ubiquitin-protein ligase that acts as a key epigenetic regulator by bridging DNA methylation and chromatin modification (PubMed:10646863, PubMed:15009091, PubMed:19056828, PubMed:23022729, PubMed:24013172, PubMed:27595565, PubMed:30104358, PubMed:30392929, PubMed:30392931, PubMed:39607687). Plays a key role in DNA methylation inheritance by promoting recruitment of DNMT1 to hemimethylated DNA and ensure faithful propagation of the DNA methylation patterns through DNA replication (PubMed:23022729, PubMed:24013172, PubMed:27595565, PubMed:30104358, PubMed:30392929, PubMed:30392931, PubMed:39607687). Acts both as a histone reader and writer: specifically recognizes and binds (1) hemimethylated DNA at replication forks and (2) histone H3 trimethylated at 'Lys-9' and unmethylated at 'Arg-2' (H3K9me3 and H3R2me0, respectively), thereby activating its E3 ubiquitin-protein ligase activity (PubMed:15361834, PubMed:17673620, PubMed:17967883, PubMed:18772889, PubMed:21745816, PubMed:21777816, PubMed:22100450, PubMed:22837395, PubMed:23022729, PubMed:27595565, PubMed:30104358). UHRF1 then mediates histone H3 'Lys-18' monoubiquitination (H3K18ub), a docking site for DNMT1, leading to DNMT1 recruitment and replication-coupled DNA methylation maintenance (PubMed:27595565). Also mediates histone H3 'Lys-14' and 'Lys-23' ubiquitination (H3K14ub and H3K23ub) at lower level (PubMed:24013172, PubMed:27595565). Histone ubiquitin ligase activity also stimulates the methyltransferase activity of SUV39H1 and/or SUV39H2, promoting accumulation of H3K9me3 histone mark to reinformce heterochromatin state (PubMed:39631394). Enriched in pericentric heterochromatin where it recruits different chromatin modifiers required for this chromatin replication. Also localizes to euchromatic regions where it negatively regulates transcription possibly by impacting DNA methylation and histone modifications (PubMed:21777816). Plays a role in DNA repair by cooperating with UHRF2 to ensure recruitment of FANCD2 to interstrand cross-links (ICLs) leading to FANCD2 activation (PubMed:30335751). Also ubiquitinates non-histone proteins, such as histone H3, KIF11 and PML (PubMed:22945642, PubMed:37728657). Acts as a critical player of proper spindle architecture by catalyzing the 'Lys-63'-linked ubiquitination of KIF11, thereby controlling KIF11 localization on the spindle (PubMed:37728657)","subunit":"Interacts with DNMT1; the interaction is direct (PubMed:17673620, PubMed:21745816). Interacts with DNMT3A and DNMT3B (By similarity). Interacts with HDAC1, but not with HDAC2 (PubMed:15361834). Interacts with BLTP3A (PubMed:15361834). Interacts with EHMT2 (PubMed:19056828). Interacts with ZNF263; recruited to the SIX3 promoter along with other proteins involved in chromatin modification and transcriptional corepression where it contributes to transcriptional repression (PubMed:32051553). Interacts with UHRF2 (PubMed:30335751). Interacts with FANCD2 (PubMed:30335751). Interacts with TET1 isoform 2; this interaction induces the recruitment of TET1 isoform 2 to replicating heterochromatin (By similarity)","family":"","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["10646863","15009091","15361834","17673620","17967883","18772889","19056828","21745816","21777816","22100450","22837395","22945642","23022729","24013172","27595565","30104358","30335751","30392929","30392931","37728657","39607687","39631394"],"location":"Nucleus；Chromosome","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"泛素化/蛋白稳态；染色质/转录调控；DNA修复/复制；细胞周期/分裂；注释原文：E3 ubiquitin-protein ligase that acts as a key epigenetic regulator by bridging DNA methylation and chromatin modification (PubMed:10646863, PubMed:15009091, PubMed:19056828, PubMed:23022729, PubMed:24013172, PubMed:27595565, PubMed:30104358, PubMed:30392929, PubMed:30392931, PubMed:39607687).","function_evidence":"含实验支持条目；ECO:0000269","categories":"泛素化/蛋白稳态；染色质/转录调控；DNA修复/复制；细胞周期/分裂"},"UIMC1":{"hgnc":"HGNC:30298","symbol":"UIMC1","accessions":["Q96RL1"],"name":"BRCA1-A complex subunit RAP80","length":"719","function":"Ubiquitin-binding protein (PubMed:24627472). Specifically recognizes and binds 'Lys-63'-linked ubiquitin (PubMed:19328070, Ref.38). Plays a central role in the BRCA1-A complex by specifically binding 'Lys-63'-linked ubiquitinated histones H2A and H2AX at DNA lesions sites, leading to target the BRCA1-BARD1 heterodimer to sites of DNA damage at double-strand breaks (DSBs). The BRCA1-A complex also possesses deubiquitinase activity that specifically removes 'Lys-63'-linked ubiquitin on histones H2A and H2AX. Also weakly binds monoubiquitin but with much less affinity than 'Lys-63'-linked ubiquitin. May interact with monoubiquitinated histones H2A and H2B; the relevance of such results is however unclear in vivo. Does not bind 'Lys-48'-linked ubiquitin. May indirectly act as a transcriptional repressor by inhibiting the interaction of NR6A1 with the corepressor NCOR1","subunit":"Component of the ARISC complex, at least composed of UIMC1/RAP80, ABRAXAS1, BRCC3/BRCC36, BABAM2 and BABAM1/NBA1 (PubMed:24075985). Component of the BRCA1-A complex, at least composed of the BRCA1, BARD1, UIMC1/RAP80, ABRAXAS1, BRCC3/BRCC36, BABAM2 and BABAM1/NBA1 (PubMed:17525341, PubMed:17525342, PubMed:19261746, PubMed:19261749). In the BRCA1-A complex, interacts directly with ABRAXAS1 (PubMed:17643121, PubMed:17643122, PubMed:18077395, PubMed:19261748, PubMed:19261749). Interacts with UBE2I (PubMed:17698038). Interacts with NR6A1 (PubMed:12080054). Interacts with ESR1 (PubMed:17311814). Interacts with TSP57 (By similarity). Interacts with TRAIP (PubMed:26781088)","family":"Belongs to the RAP80 family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["12080054","17525340","17525341","17525342","17621610","17643121","19015238","19202061","19261748","19328070","24627472"],"location":"Nucleus","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"泛素化/蛋白稳态；染色质/转录调控；DNA修复/复制；注释原文：Ubiquitin-binding protein (PubMed:24627472).","function_evidence":"含实验支持条目；ECO:0000269","categories":"泛素化/蛋白稳态；染色质/转录调控；DNA修复/复制"},"UMAD1":{"hgnc":"HGNC:48955","symbol":"UMAD1","accessions":["C9J7I0"],"name":"UBAP1-MVB12-associated (UMA)-domain containing protein 1","length":"137","function":"未获得FUNCTION段；不等于没有已发表研究","subunit":"无可用SUBUNIT段","family":"","domains":"Domain 86-134: UMA [ECO:0000255/PROSITE-ProRule/PRU00830]","function_pmids":[],"location":"当前记录无定位注释","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"本次数据库无可用FUNCTION；只可据蛋白名称/结构域提出方向，不据此称全新功能。","function_evidence":"本次数据库无FUNCTION段；不等于无研究/无功能","categories":"未归类"},"UMPS":{"hgnc":"HGNC:12563","symbol":"UMPS","accessions":["P11172"],"name":"Uridine 5'-monophosphate synthase","length":"480","function":"Bifunctional enzyme catalyzing the last two steps of de novo pyrimidine biosynthesis, orotate phosphoribosyltransferase (OPRT), which converts orotate to orotidine-5'-monophosphate (OMP), and orotidine-5'-monophosphate decarboxylase (ODC), the terminal enzymatic reaction that decarboxylates OMP to uridine monophosphate (UMP)","subunit":"Homodimer; dimerization is required for enzymatic activity","family":"In the N-terminal section; belongs to the purine/pyrimidine phosphoribosyltransferase family\nIn the C-terminal section; belongs to the OMP decarboxylase family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["18184586","9042911"],"location":"当前记录无定位注释","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"；注释原文：Bifunctional enzyme catalyzing the last two steps of de novo pyrimidine biosynthesis, orotate phosphoribosyltransferase (OPRT), which converts orotate to orotidine-5'-monophosphate (OMP), and orotidine-5'-monophosphate decarboxylase (ODC), the terminal enzymatic reaction that decarboxylates OMP to uridine monophosphate (UMP)","function_evidence":"含实验支持条目；ECO:0000269","categories":"未归类"},"UNC13B":{"hgnc":"HGNC:12566","symbol":"UNC13B","accessions":["O14795"],"name":"Protein unc-13 homolog B","length":"1591","function":"Plays a role in vesicle maturation during exocytosis as a target of the diacylglycerol second messenger pathway. Is involved in neurotransmitter release by acting in synaptic vesicle priming prior to vesicle fusion and participates in the activity-depending refilling of readily releasable vesicle pool (RRP) (By similarity). Essential for synaptic vesicle maturation in a subset of excitatory/glutamatergic but not inhibitory/GABA-mediated synapses (By similarity). In collaboration with UNC13A, facilitates neuronal dense core vesicles fusion as well as controls the location and efficiency of their synaptic release (By similarity)","subunit":"Interacts with RIMS1","family":"Belongs to the unc-13 family","domains":[],"function_pmids":[],"location":"Cytoplasm; Membrane; Cell membrane; Synapse","shared_sequence_gene_count":"1","source_snapshot":"project UniProt records20261017/18","brief":"Plays a role in vesicle maturation during exocytosis as a target of the diacylglycerol second messenger pathway. Is involved in neurotransmitter release by acting in synaptic vesicle priming prior to vesicle fusion and participates in the activity-depending refilling of readily releasable vesicle pool (RRP) (By similarity). Essential for synaptic vesicle maturation in a subset of excitatory/glutamatergic but not inhibitory/GABA-mediated synapses (By similarity). In collaboration with UNC13A, facilitates neuronal dense core vesicles fusion as well as controls the location and efficiency of their synaptic release (By similarity)"},"UNC45A":{"hgnc":"HGNC:30594","symbol":"UNC45A","accessions":["Q9H3U1"],"name":"Protein unc-45 homolog A","length":"944","function":"Acts as a co-chaperone for HSP90. Prevents the stimulation of HSP90AB1 ATPase activity by AHSA1. Positive factor in promoting PGR function in the cell. May be necessary for proper folding of myosin (Potential). Necessary for normal cell proliferation. Necessary for normal myotube formation and myosin accumulation during muscle cell development. May play a role in erythropoiesis in stroma cells in the spleen (By similarity)","subunit":"Interacts with PGR isoforms A and B as well as with NR3C1 in the absence of ligand, and with HSP90AB1. Binding to HSP90AB1 involves 2 UNC45A monomers per HSP90AB1 dimer","family":"","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["12119110","16478993"],"location":"Cytoplasm；Cytoplasm, perinuclear region；Nucleus","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"发育/分化；注释原文：Acts as a co-chaperone for HSP90.","function_evidence":"含实验支持条目；含同源推断，不能当该成员实测；ECO:0000250,ECO:0000269,ECO:0000305","categories":"发育/分化"},"UNC93B1":{"hgnc":"HGNC:13481","symbol":"UNC93B1","accessions":["Q9H1C4"],"name":"Protein unc-93 homolog B1","length":"597","function":"Plays an important role in innate and adaptive immunity by regulating nucleotide-sensing Toll-like receptor (TLR) signaling. Required for the transport of a subset of TLRs (including TLR3, TLR7 and TLR9) from the endoplasmic reticulum to endolysosomes where they can engage pathogen nucleotides and activate signaling cascades. May play a role in autoreactive B-cells removal","subunit":"Interacts with TLR3, TLR5, TLR7, and TLR9 (probably via transmembrane domain)","family":"Belongs to the unc-93 family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["19006693"],"location":"Endoplasmic reticulum membrane；Multi-pass membrane protein；Endosome；Lysosome；Cytoplasmic vesicle, phagosome","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"黏附/受体/细胞表面；注释原文：Plays an important role in innate and adaptive immunity by regulating nucleotide-sensing Toll-like receptor (TLR) signaling.","function_evidence":"含实验支持条目；ECO:0000269","categories":"黏附/受体/细胞表面"},"UNKL":{"hgnc":"HGNC:14184","symbol":"UNKL","accessions":["Q9H9P5"],"name":"Putative E3 ubiquitin-protein ligase UNKL","length":"680","function":"May participate in a protein complex showing an E3 ligase activity regulated by RAC1. Ubiquitination is directed towards itself and possibly other substrates, such as SMARCD2/BAF60b. Intrinsic E3 ligase activity has not been proven","subunit":"Isoform 4 (C-terminal) interacts with the GTP-bound form of RAC1. Isoform 4 (C-terminal) interacts with SMARCD2/BAF60b","family":"Belongs to the unkempt family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["20148946"],"location":"Cytoplasm；Nucleus","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"泛素化/蛋白稳态；注释原文：May participate in a protein complex showing an E3 ligase activity regulated by RAC1.","function_evidence":"含实验支持条目；ECO:0000269","categories":"泛素化/蛋白稳态"},"UPF1":{"hgnc":"HGNC:9962","symbol":"UPF1","accessions":["Q92900"],"name":"Regulator of nonsense transcripts 1","length":"1129","function":"RNA-dependent helicase required for nonsense-mediated decay (NMD) of aberrant mRNAs containing premature stop codons and which modulates the expression level of normal mRNAs (PubMed:11163187, PubMed:16086026, PubMed:18172165, PubMed:21145460, PubMed:21419344, PubMed:24726324). ATP-dependent 5'-3' helicase active on RNA:DNA substrates with a 5'-RNA extension (PubMed:18066079, PubMed:21419344, PubMed:23275559, PubMed:26138914). ATP-dependent 5'-3' helicase active on RNA:RNA substrates with a 5'-RNA extension (PubMed:26138914). ATP-dependent 5'-3' helicase active on DNA:DNA substrates with a 5'-DNA extension (PubMed:10999600, PubMed:26138914, PubMed:30218034). Is recruited to mRNAs upon translation termination and undergoes a cycle of phosphorylation and dephosphorylation; its phosphorylation appears to be a key step in NMD (PubMed:11544179, PubMed:25220460). Recruited by release factors to stalled ribosomes together with the SMG1C protein kinase complex to form the transient SURF (SMG1-UPF1-eRF1-eRF3) complex (PubMed:19417104). In EJC-dependent NMD, the SURF complex associates with the exon junction complex (EJC) (located 50-55 or more nucleotides downstream from the termination codon) through UPF2 and allows the formation of an UPF1-UPF2-UPF3 surveillance complex which is believed to activate NMD (PubMed:21419344). Phosphorylated UPF1 is recognized by EST1B/SMG5, SMG6 and SMG7 which are thought to provide a link to the mRNA degradation machinery involving exonucleolytic and endonucleolytic pathways, and to serve as adapters to protein phosphatase 2A (PP2A), thereby triggering UPF1 dephosphorylation and allowing the recycling of NMD factors (PubMed:12554878). UPF1 can also activate NMD without UPF2 or UPF3, and in the absence of the NMD-enhancing downstream EJC indicative for alternative NMD pathways (PubMed:18447585). Plays a role in replication-dependent histone mRNA degradation at the end of phase S; the function is independent of UPF2 (PubMed:16086026, PubMed:18172165). For the recognition of premature termination codons (PTC) and initiation of NMD a competitive interaction between UPF1 and PABPC1 with the ribosome-bound release factors is proposed (PubMed:18447585, PubMed:25220460). The ATPase activity of UPF1 is required for disassembly of mRNPs undergoing NMD (PubMed:21145460). Together with UPF2 and dependent on TDRD6, mediates the degradation of mRNA harboring long 3'UTR by inducing the NMD machinery (By similarity). Has ssDNA-stimulated ATPase activity (poly(dT) and poly(dA) are most stimulatory) (PubMed:10999600). Binds RNA; addition of ATP decreases RNA-binding (PubMed:10999600, PubMed:18066079, PubMed:21419344)","subunit":"Monomeric in solution (PubMed:10999600, PubMed:26138914). Forms a trimeric UPF complex where UPF2 bridges UPF1 and UPF3B; UPF2 contacts the N-terminal CH-rich domain of UPF1 and the N-terminus of UPF3B (PubMed:18066079). The trimeric UPF complex interacts with the EJC core complex (PubMed:18066079). Found in a post-splicing messenger ribonucleoprotein (mRNP) complex (PubMed:21419344). Associates with the exon junction complex (EJC) (PubMed:11546874, PubMed:16452507). Associates with the SGM1C complex; is phosphorylated by the complex kinase component SGM1 (PubMed:19417104). Part of a complex composed of SMG1, DHX34 and UPF1; within the complex DHX34 acts as a scaffolding protein to facilitate SMG1 phosphorylation of UPF1 (PubMed:26841701). Interacts with UPF2 via the CH-rich domain (PubMed:11073994, PubMed:11113196, PubMed:11163187, PubMed:19556969, PubMed:23275559). Interacts with UPF3A and UPF3B (PubMed:11163187). Interacts with EST1A (PubMed:12554878). Interacts with SLBP (PubMed:16086026). Interacts (when hyperphosphorylated) with PNRC2 (PubMed:19150429). Interacts with AGO1 and AGO2 (PubMed:17932509). Interacts with GSPT2 (PubMed:18447585). Interacts with isoform 1 and isoform 5 of ADAR/ADAR1 (PubMed:18362360). Interacts with SMG7 (PubMed:15721257). Interacts with ZC3H12A; this interaction occurs in a mRNA translationally active- and termination-dependent manner and is essential for ZC3H12A-mediated degradation of target mRNAs (PubMed:26000482). Interacts with CPSF6 (PubMed:19864460). Interacts with MOV10; the interaction is direct and RNA-dependent (PubMed:24726324). Interacts with SHFL; the interaction increases in the presence of RNA (PubMed:27974568). Interacts with UPF2 and DDX4; interactions are mediated by TDRD6 (PubMed:25220460). Interacts with DHX34 and PABPC1/PABP1; the interactions are RNA-independent (PubMed:25220460). Interacts with RBM46 (By similarity)\n(Microbial infection) Interacts with human T-cell leukemia virus 1/HTLV-1 protein Tax; this interaction inhibits the host nonsense-mediated mRNA decay (NMD)","family":"Belongs to the DNA2/NAM7 helicase family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["10999600","11163187","11544179","12554878","16086026","18066079","18172165","18447585","19417104","21145460","21419344","23275559","24726324","25220460","26138914","30218034"],"location":"Cytoplasm；Cytoplasm, P-body；Nucleus；Cytoplasm, perinuclear region","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"染色质/转录调控；激酶/磷酸化信号；翻译/核糖体；注释原文：RNA-dependent helicase required for nonsense-mediated decay (NMD) of aberrant mRNAs containing premature stop codons and which modulates the expression level of normal mRNAs (PubMed:11163187, PubMed:16086026, PubMed:18172165, PubMed:21145460, PubMed:21419344, PubMed:24726324).","function_evidence":"含实验支持条目；含同源推断，不能当该成员实测；ECO:0000250,ECO:0000269","categories":"染色质/转录调控；激酶/磷酸化信号；翻译/核糖体"},"UPF2":{"hgnc":"HGNC:17854","symbol":"UPF2","accessions":["Q9HAU5"],"name":"Regulator of nonsense transcripts 2","length":"1272","function":"Involved in nonsense-mediated decay (NMD) of mRNAs containing premature stop codons by associating with the nuclear exon junction complex (EJC). Recruited by UPF3B associated with the EJC core at the cytoplasmic side of the nuclear envelope and the subsequent formation of an UPF1-UPF2-UPF3 surveillance complex (including UPF1 bound to release factors at the stalled ribosome) is believed to activate NMD. In cooperation with UPF3B stimulates both ATPase and RNA helicase activities of UPF1. Binds spliced mRNA","subunit":"Forms a trimeric UPF complex where UPF2 bridges UPF1 and UPF3B; UPF2 contacts the N-terminal CH-rich domain of UPF1 and the N-terminus of UPF3B (PubMed:18066079). The trimeric UPF complex interacts with the EJC core complex (PubMed:18066079). Found in a post-splicing messenger ribonucleoprotein (mRNP) complex. Associates with the exon junction complex (EJC). Interacts with SMG1, EST1A, UPF1, UPF3A, UPF3B, EIF4A1 and EIF1","family":"","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["11163187","16209946","18066079"],"location":"Cytoplasm, perinuclear region；Cytoplasm","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"翻译/核糖体；注释原文：Involved in nonsense-mediated decay (NMD) of mRNAs containing premature stop codons by associating with the nuclear exon junction complex (EJC).","function_evidence":"含实验支持条目；ECO:0000269","categories":"翻译/核糖体"},"UPP1":{"hgnc":"HGNC:12576","symbol":"UPP1","accessions":["Q16831"],"name":"Uridine phosphorylase 1","length":"310","function":"Catalyzes the reversible phosphorylytic cleavage of uridine to uracil and ribose-1-phosphate which can then be utilized as carbon and energy sources or in the rescue of pyrimidine bases for nucleotide synthesis (PubMed:7488099). Shows broad substrate specificity and can also accept deoxyuridine and other analogous compounds (Probable)","subunit":"Homodimer","family":"Belongs to the PNP/UDP phosphorylase family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["13737038","7488099"],"location":"当前记录无定位注释","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"；注释原文：Catalyzes the reversible phosphorylytic cleavage of uridine to uracil and ribose-1-phosphate which can then be utilized as carbon and energy sources or in the rescue of pyrimidine bases for nucleotide synthesis (PubMed:7488099).","function_evidence":"含实验支持条目；ECO:0000269,ECO:0000305","categories":"未归类"},"UQCC1":{"hgnc":"HGNC:15891","symbol":"UQCC1","accessions":["Q9NVA1"],"name":"Ubiquinol-cytochrome c reductase complex assembly factor 1","length":"299","function":"Required for the assembly of the ubiquinol-cytochrome c reductase complex (mitochondrial respiratory chain complex III or cytochrome b-c1 complex). Involved in cytochrome b translation and/or stability","subunit":"Interacts with UQCC2 (PubMed:24385928). Interacts with UQCC3. Forms a complex, named COMB/coordinator of mitochondrial CYTB biogenesis, composed of UQCC1, UQCC2, UQCC4, UQCC5 and UQCC6; stabilizes nascent cytochrome b/MT-CYB and promotes its membrane insertion. Forms a complex, named COMB/coordinator of mitochondrial CYTB biogenesis, composed of UQCC1, UQCC2, UQCC4, UQCC5 and UQCC6; stabilizes nascent cytochrome b/MT-CYB and promotes its membrane insertion. Forms a complex, named COMA, composed of UQCC1, UQCC2 and UQCC4; activates MT-CYB translation. Forms a complex, named COMC, composed of UQCC1, UQCC2; UQCC3 and UQCC4; mediates MT-CYB hemylation and association with the first nuclear-encoded CIII subunit UQCRQ (By similarity)","family":"Belongs to the CBP3 family","domains":[],"function_pmids":["24385928"],"location":"Mitochondrion inner membrane; Cytoplasmic vesicle","shared_sequence_gene_count":"1","source_snapshot":"project UniProt records20261017/18","brief":"Required for the assembly of the ubiquinol-cytochrome c reductase complex (mitochondrial respiratory chain complex III or cytochrome b-c1 complex). Involved in cytochrome b translation and/or stability"},"URB1":{"hgnc":"HGNC:17344","symbol":"URB1","accessions":["O60287"],"name":"Nucleolar pre-ribosomal-associated protein 1","length":"2271","function":"未获得FUNCTION段；不等于没有已发表研究","subunit":"无可用SUBUNIT段","family":"","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":[],"location":"Nucleus, nucleolus","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"本次数据库无可用FUNCTION；只可据蛋白名称/结构域提出方向，不据此称全新功能。","function_evidence":"本次数据库无FUNCTION段；不等于无研究/无功能","categories":"翻译/核糖体"},"URB2":{"hgnc":"HGNC:28967","symbol":"URB2","accessions":["Q14146"],"name":"Unhealthy ribosome biogenesis protein 2 homolog","length":"1524","function":"Essential for hematopietic stem cell development through the regulation of p53/TP53 pathway","subunit":"无可用SUBUNIT段","family":"","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":[],"location":"Nucleus, nucleolus","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"翻译/核糖体；发育/分化；注释原文：Essential for hematopietic stem cell development through the regulation of p53/TP53 pathway","function_evidence":"含同源推断，不能当该成员实测；ECO:0000250","categories":"翻译/核糖体；发育/分化"},"URI1":{"hgnc":"HGNC:13236","symbol":"URI1","accessions":["O94763"],"name":"Unconventional prefoldin RPB5 interactor 1","length":"535","function":"Involved in gene transcription regulation. Acts as a transcriptional repressor in concert with the corepressor UXT to regulate androgen receptor (AR) transcription. May act as a tumor suppressor to repress AR-mediated gene transcription and to inhibit anchorage-independent growth in prostate cancer cells. Required for cell survival in ovarian cancer cells. Together with UXT, associates with chromatin to the NKX3-1 promoter region. Antagonizes transcriptional modulation via hepatitis B virus X protein\nPlays a central role in maintaining S6K1 signaling and BAD phosphorylation under normal growth conditions thereby protecting cells from potential deleterious effects of sustained S6K1 signaling. The URI1-PPP1CC complex acts as a central component of a negative feedback mechanism that counteracts excessive S6K1 survival signaling to BAD in response to growth factors. Mediates inhibition of PPP1CC phosphatase activity in mitochondria. Coordinates the regulation of nutrient-sensitive gene expression availability in a mTOR-dependent manner. Seems to be a scaffolding protein able to assemble a prefoldin-like complex that contains PFDs and proteins with roles in transcription and ubiquitination","subunit":"Homodimer. Component of the PAQosome complex which is responsible for the biogenesis of several protein complexes and which consists of R2TP complex members RUVBL1, RUVBL2, RPAP3 and PIH1D1, URI complex members PFDN2, PFDN6, PDRG1, UXT and URI1 as well as ASDURF, POLR2E and DNAAF10/WDR92 (PubMed:31738558). Interacts with POLR2E/RPB5, RUVBL2 and RUVBL1 (PubMed:14615539, PubMed:9819440). Interacts with PFDN2, PFDN4 and STAP1; the interactions are phosphorylation-dependent and occur in a growth-dependent manner in the mitochondrion (PubMed:14615539). Interacts with UXT (PubMed:21730289). Interacts with PPP1CC; the interaction is phosphorylation-dependent and occurs in a growth factor-dependent manner (PubMed:21397856). Interacts (via the middle C-terminal region) with GTF2F1 and GTF2F2 (PubMed:12737519). Interacts with DMAP1 (PubMed:15367675). Interacts with TSC1 and TSC2 (PubMed:28561026). Interacts with PRPF8 and EFTUD2 in a ZNHIT2-dependent manner (PubMed:28561026)","family":"Belongs to the RNA polymerase II subunit 5-mediating protein family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":[],"location":"Nucleus；Cytoplasm；Mitochondrion；Cell projection, dendrite","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"泛素化/蛋白稳态；染色质/转录调控；激酶/磷酸化信号；线粒体/代谢；黏附/受体/细胞表面；注释原文：Involved in gene transcription regulation.","function_evidence":"数据库整理/推断；按原文限定；","categories":"泛素化/蛋白稳态；染色质/转录调控；激酶/磷酸化信号；线粒体/代谢；黏附/受体/细胞表面"},"USB1":{"hgnc":"HGNC:25792","symbol":"USB1","accessions":["Q9BQ65"],"name":"U6 snRNA phosphodiesterase 1","length":"265","function":"3'-5' RNA exonuclease that trims the 3' end of oligo(U) and oligo(A) tracts of the pre-U6 small nuclear RNA (snRNA) molecule, leading to the formation of a mature U6 snRNA 3' end-terminated with a 2',3'-cyclic phosphate (PubMed:22899009, PubMed:23022480, PubMed:23190533, PubMed:26213367, PubMed:28887445, PubMed:30215753, PubMed:31832688). Participates in the U6 snRNA 3' end processing that prevents U6 snRNA degradation (PubMed:22899009, PubMed:23022480, PubMed:23190533, PubMed:26213367, PubMed:28887445, PubMed:30215753, PubMed:31832688). In addition also removes uridines from the 3' end of U6atac snRNA and possibly the vault RNA VTRNA1-1 (PubMed:26213367)","subunit":"Interacts with PLRG1, CDC5L and PRPF19","family":"Belongs to the 2H phosphoesterase superfamily. USB1 family","domains":[],"function_pmids":["22899009","23022480","23190533","26213367","28887445","30215753","31832688"],"location":"Nucleus","shared_sequence_gene_count":"1","source_snapshot":"project UniProt records20261017/18","brief":"3'-5' RNA exonuclease that trims the 3' end of oligo(U) and oligo(A) tracts of the pre-U6 small nuclear RNA (snRNA) molecule, leading to the formation of a mature U6 snRNA 3' end-terminated with a 2',3'-cyclic phosphate (PubMed:22899009, PubMed:23022480, PubMed:23190533, PubMed:26213367, PubMed:28887445, PubMed:30215753, PubMed:31832688). Participates in the U6 snRNA 3' end processing that prevents U6 snRNA degradation (PubMed:22899009, PubMed:23022480, PubMed:23190533, PubMed:26213367, PubMed:28887445, PubMed:30215753, PubMed:31832688). In addition also removes uridines from the 3' end of U6atac snRNA and possibly the vault RNA VTRNA1-1 (PubMed:26213367)"},"USH1G":{"hgnc":"HGNC:16356","symbol":"USH1G","accessions":["Q495M9"],"name":"pre-mRNA splicing regulator USH1G","length":"461","function":"Plays a role in pre-mRNA splicing by regulating the release and transfer of U4/U6.U5 tri-small nuclear ribonucleoprotein (tri-snRNP) complexes from their assembly site in Cajal bodies to nuclear speckles, thereby contributing to the assembly of the pre-catalytic spliceosome on target pre-mRNAs (PubMed:34023904). May also participate in recycling of snRNPs back to Cajal bodies during splicing (PubMed:34023904). Plays a role in regulating MAGI2-mediated endocytosis (PubMed:24608321). Anchoring/scaffolding protein that is a part of the functional network formed by USH1C, USH1G, CDH23 and MYO7A that mediates mechanotransduction in cochlear hair cells. Required for normal development and maintenance of cochlear hair cell bundles. Required for normal hearing","subunit":"Part of a complex composed of USH1C, USH1G and MYO7A (PubMed:21311020, PubMed:21709241). Interacts with USH1C (via the first PDZ domain) (PubMed:12588794, PubMed:20142502). Interacts with PDZD7 (PubMed:19028668). Interacts with CDH23 and PCDH15; these interactions may recruit USH1G to the plasma membrane (By similarity). Interacts with intraflagellar transport proteins IFT20, IFT52 and IFT57 (PubMed:31637240). Interacts with splicing factors SF3B1, PRPF6, PRPF31 and SON (PubMed:34023904). Interacts with the U4/U6.U5 tri-small nuclear ribonucleoprotein (tri-snRNP) complex in the presence of pre-mRNAs (PubMed:34023904). Interacts (via SAM domain) with MAGI2 (via PDZ 6 domain); the interaction is triggered by phosphorylation of USH1G by CK2 and negatively regulates MAGI2-mediated endocytosis (PubMed:24608321)","family":"","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["21709241","24608321","34023904"],"location":"Cytoplasm, cytosol；Cytoplasm, cytoskeleton；Cell membrane；Peripheral membrane protein；Cell projection, cilium；Nucleus speckle；Nucleus, Cajal body；Cytoplasm, cytoskeleton, microtubule organizing center, centrosome；Photoreceptor inner segment","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"RNA加工/剪接；膜运输/高尔基/内吞；发育/分化；注释原文：Plays a role in pre-mRNA splicing by regulating the release and transfer of U4/U6.U5 tri-small nuclear ribonucleoprotein (tri-snRNP) complexes from their assembly site in Cajal bodies to nuclear speckles, thereby contributing to the assembly of the pre-catalytic spliceosome on target pre-mRNAs (PubMed:34023904).","function_evidence":"含实验支持条目；ECO:0000269","categories":"RNA加工/剪接；膜运输/高尔基/内吞；发育/分化"},"USHBP1":{"hgnc":"HGNC:24058","symbol":"USHBP1","accessions":["Q8N6Y0"],"name":"Harmonin-binding protein USHBP1","length":"703","function":"未获得FUNCTION段；不等于没有已发表研究","subunit":"Interacts via its C-terminus with the first PDZ domain of USH1C","family":"Belongs to the MCC family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":[],"location":"当前记录无定位注释","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"本次数据库无可用FUNCTION；只可据蛋白名称/结构域提出方向，不据此称全新功能。","function_evidence":"本次数据库无FUNCTION段；不等于无研究/无功能","categories":"未归类"},"USO1":{"hgnc":"HGNC:30904","symbol":"USO1","accessions":["O60763"],"name":"General vesicular transport factor p115","length":"962","function":"General vesicular transport factor required for intercisternal transport in the Golgi stack; it is required for transcytotic fusion and/or subsequent binding of the vesicles to the target membrane. May well act as a vesicular anchor by interacting with the target membrane and holding the vesicular and target membranes in proximity","subunit":"Homodimer. Dimerizes by parallel association of the tails, resulting in an elongated structure with two globular head domains side by side, and a long rod-like tail structure (Probable). Interacts with MIF","family":"Belongs to the VDP/USO1/EDE1 family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":[],"location":"Cytoplasm, cytosol；Golgi apparatus membrane；Peripheral membrane protein","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"膜运输/高尔基/内吞；注释原文：General vesicular transport factor required for intercisternal transport in the Golgi stack; it is required for transcytotic fusion and/or subsequent binding of the vesicles to the target membrane.","function_evidence":"含同源推断，不能当该成员实测；ECO:0000250","categories":"膜运输/高尔基/内吞"},"USP1":{"hgnc":"HGNC:12607","symbol":"USP1","accessions":["O94782"],"name":"Ubiquitin carboxyl-terminal hydrolase 1","length":"785","function":"Negative regulator of DNA damage repair which specifically deubiquitinates monoubiquitinated FANCD2 (PubMed:15694335). Also involved in PCNA-mediated translesion synthesis (TLS) by deubiquitinating monoubiquitinated PCNA (PubMed:16531995, PubMed:20147293). Has almost no deubiquitinating activity by itself and requires the interaction with WDR48 to have a high activity (PubMed:18082604, PubMed:26388029)","subunit":"Interacts with FANCD2 and PCNA (PubMed:15694335, PubMed:16531995). Interacts with WDR48 (PubMed:18082604, PubMed:26388029). Interacts with ATAD5; the interaction regulates USP1-mediated PCNA deubiquitination (PubMed:20147293)","family":"Belongs to the peptidase C19 family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["15694335","16531995","18082604","20147293","26388029"],"location":"Nucleus","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"泛素化/蛋白稳态；DNA修复/复制；线粒体/代谢；注释原文：Negative regulator of DNA damage repair which specifically deubiquitinates monoubiquitinated FANCD2 (PubMed:15694335).","function_evidence":"含实验支持条目；ECO:0000269","categories":"泛素化/蛋白稳态；DNA修复/复制；线粒体/代谢"},"USP10":{"hgnc":"HGNC:12608","symbol":"USP10","accessions":["Q14694"],"name":"Ubiquitin carboxyl-terminal hydrolase 10","length":"798","function":"Hydrolase that can remove conjugated ubiquitin from target proteins such as p53/TP53, RPS2/us5, RPS3/us3, RPS10/eS10, BECN1, SNX3 and CFTR (PubMed:11439350, PubMed:18632802, PubMed:31981475). Acts as an essential regulator of p53/TP53 stability: in unstressed cells, specifically deubiquitinates p53/TP53 in the cytoplasm, leading to counteract MDM2 action and stabilize p53/TP53 (PubMed:20096447). Following DNA damage, translocates to the nucleus and deubiquitinates p53/TP53, leading to regulate the p53/TP53-dependent DNA damage response (PubMed:20096447). Component of a regulatory loop that controls autophagy and p53/TP53 levels: mediates deubiquitination of BECN1, a key regulator of autophagy, leading to stabilize the PIK3C3/VPS34-containing complexes (PubMed:21962518). In turn, PIK3C3/VPS34-containing complexes regulate USP10 stability, suggesting the existence of a regulatory system by which PIK3C3/VPS34-containing complexes regulate p53/TP53 protein levels via USP10 and USP13 (PubMed:21962518). Does not deubiquitinate MDM2 (PubMed:20096447). Plays a key role in 40S ribosome subunit recycling when a ribosome has stalled during translation: acts both by inhibiting formation of stress granules, which store stalled translation pre-initiation complexes, and mediating deubiquitination of 40S ribosome subunits (PubMed:27022092, PubMed:31981475, PubMed:34348161, PubMed:34469731). Acts as a negative regulator of stress granules formation by lowering G3BP1 and G3BP2 valence, thereby preventing G3BP1 and G3BP2 ability to undergo liquid-liquid phase separation (LLPS) and assembly of stress granules (PubMed:11439350, PubMed:27022092, PubMed:32302570). Promotes 40S ribosome subunit recycling following ribosome dissociation in response to ribosome stalling by mediating deubiquitination of 40S ribosomal proteins RPS2/us5, RPS3/us3 and RPS10/eS10, thereby preventing their degradation by the proteasome (PubMed:31981475, PubMed:34348161, PubMed:34469731). Part of a ribosome quality control that takes place when ribosomes have stalled during translation initiation (iRQC): USP10 acts by removing monoubiquitination of RPS2/us5 and RPS3/us3, promoting 40S ribosomal subunit recycling (PubMed:34469731). Deubiquitinates CFTR in early endosomes, enhancing its endocytic recycling (PubMed:19398555). Involved in a TANK-dependent negative feedback response to attenuate NF-kappa-B activation via deubiquitinating IKBKG or TRAF6 in response to interleukin-1-beta (IL1B) stimulation or upon DNA damage (PubMed:25861989). Deubiquitinates TBX21 leading to its stabilization (PubMed:24845384). Plays a negative role in the RLR signaling pathway upon RNA virus infection by blocking the RIGI-mediated MAVS activation. Mechanistically, removes the unanchored 'Lys-63'-linked polyubiquitin chains of MAVS to inhibit its aggregation, essential for its activation (PubMed:37582970)","subunit":"Found in a deubiquitination complex with TANK, USP10 and ZC3H12A; this complex inhibits genotoxic stress- or interleukin-1-beta (IL1B)-mediated NF-kappa-B activation by promoting IKBKG or TRAF6 deubiquitination (PubMed:25861989). Interacts with IKBKG; this interaction increases in response to DNA damage (PubMed:25861989). Interacts with TANK; this interaction increases in response to DNA damage (PubMed:25861989). Interacts with TRAF6; this interaction increases in response to DNA damage (PubMed:25861989). Interacts with ZC3H12A; this interaction increases in response to DNA damage (PubMed:25861989). Interacts with G3BP1 (via NTF2 domain) and G3BP2 (via NTF2 domain); inhibiting stress granule formation (PubMed:11439350, PubMed:23279204, PubMed:27022092, PubMed:31981475, PubMed:32302570, PubMed:36183834, PubMed:36279435)","family":"Belongs to the peptidase C19 family. USP10 subfamily","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["11439350","18632802","19398555","20096447","21962518","24845384","25861989","27022092","31981475","32302570","34348161","34469731","37582970"],"location":"Cytoplasm；Nucleus；Early endosome","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"泛素化/蛋白稳态；DNA修复/复制；膜运输/高尔基/内吞；翻译/核糖体；免疫/炎症/细胞死亡；线粒体/代谢；注释原文：Hydrolase that can remove conjugated ubiquitin from target proteins such as p53/TP53, RPS2/us5, RPS3/us3, RPS10/eS10, BECN1, SNX3 and CFTR (PubMed:11439350, PubMed:18632802, PubMed:31981475).","function_evidence":"含实验支持条目；ECO:0000269","categories":"泛素化/蛋白稳态；DNA修复/复制；膜运输/高尔基/内吞；翻译/核糖体；免疫/炎症/细胞死亡；线粒体/代谢"},"USP11":{"hgnc":"HGNC:12609","symbol":"USP11","accessions":["P51784"],"name":"Ubiquitin carboxyl-terminal hydrolase 11","length":"963","function":"Protease that can remove conjugated ubiquitin from target proteins and polyubiquitin chains (PubMed:12084015, PubMed:15314155, PubMed:17897950, PubMed:19874889, PubMed:20233726, PubMed:24724799, PubMed:28992046). Inhibits the degradation of target proteins by the proteasome (PubMed:12084015). Cleaves preferentially 'Lys-6' and 'Lys-63'-linked ubiquitin chains. Has lower activity with 'Lys-11' and 'Lys-33'-linked ubiquitin chains, and extremely low activity with 'Lys-27', 'Lys-29' and 'Lys-48'-linked ubiquitin chains (in vitro) (PubMed:24724799). Plays a role in the regulation of pathways leading to NF-kappa-B activation (PubMed:17897950, PubMed:19874889). Plays a role in the regulation of DNA repair after double-stranded DNA breaks (PubMed:15314155, PubMed:20233726). Acts as a chromatin regulator via its association with the Polycomb group (PcG) multiprotein PRC1-like complex; may act by deubiquitinating components of the PRC1-like complex (PubMed:20601937). Promotes cell proliferation by deubiquitinating phosphorylated E2F1 (PubMed:28992046)","subunit":"Monomer (PubMed:24724799). Associated component of the Polycomb group (PcG) multiprotein PRC1-like complex (PubMed:20601937). Interacts with RANBP9/RANBPM (PubMed:12084015). Interacts with BRCA2 (PubMed:15314155). Interacts with CHUK/IKKA (PubMed:17897950). Interacts with NFKBIA (PubMed:19874889). Interacts with SPRY3, RAE1, MYCBP2/PAM, and KCTD6 (PubMed:29293652)\n(Microbial infection) Interacts with papilloma virus protein 16E7 (PubMed:18408009)","family":"Belongs to the peptidase C19 family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["15314155","17897950","18408009","19874889","20233726","24724799","28992046"],"location":"Nucleus；Cytoplasm；Chromosome","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"泛素化/蛋白稳态；染色质/转录调控；DNA修复/复制；激酶/磷酸化信号；免疫/炎症/细胞死亡；线粒体/代谢；注释原文：Protease that can remove conjugated ubiquitin from target proteins and polyubiquitin chains (PubMed:12084015, PubMed:15314155, PubMed:17897950, PubMed:19874889, PubMed:20233726, PubMed:24724799, PubMed:28992046).","function_evidence":"含实验支持条目；ECO:0000269","categories":"泛素化/蛋白稳态；染色质/转录调控；DNA修复/复制；激酶/磷酸化信号；免疫/炎症/细胞死亡；线粒体/代谢"},"USP12":{"hgnc":"HGNC:20485","symbol":"USP12","accessions":["O75317"],"name":"Ubiquitin carboxyl-terminal hydrolase 12","length":"370","function":"Deubiquitinating enzyme that plays various roles in the regulation of the immune response and inflammation (PubMed:19075014, PubMed:27373336). During TCR engagement and activation, translocates into the cytoplasm and deubiquitinates its substrates LAT and TRAT1 and prevents their lysosome-dependent degradation to stabilize the TCR signaling complex at the plasma membrane (PubMed:26811477). Plays an essential role in the selective LPS-induced macrophage response through the activation of NF-kappa-B pathway (PubMed:28063927). In addition, promotes that antiviral immune response through targeting DNA sensor IFI16 to inhibit its proteasome-dependent degradation (PubMed:37410794). Participates in the interferon signaling pathway and antiviral response independently of its deubiquitinase activity by maintaining nuclear phosphorylated STAT1 levels via inhibition of its CREBBP-mediated acetylation and subsequent dephosphorylation (PubMed:31899788). Plays an intrinsic role in promoting the differentiation, activation and proliferation of CD4(+) T-cell by activating the NF-kappa-B signaling pathway through deubiquitinating and stabilizing B-cell lymphoma/leukemia 10/BCL10 (By similarity). In myeloid-derived suppressor cells promotes the activation of the NF-kappa-B via deubiquitination and stabilization of RELA (By similarity). Regulates the 'Lys-63'-linked polyubiquitin chains of BAX and thereby modulates the mitochondrial apoptotic process (PubMed:36361894). Negative regulator of NOTCH signaling that specifically deubiquitinates non-activated NOTCH receptors to target them for lysosomal degradation; deubiquitination of NOTCH stimulates its transport form late endosomes to lysosomes (PubMed:22778262). Protects neurons against HTT/huntingtin-induced polyglutamine expansion-dependent neurodegeneration through regulation of autophagic flux (PubMed:30266909). This function is independent of deubiquitinase activity or of other components of the USP12-WDR20-WDR48 deubiquitinating complex (By similarity). In complex with WDR48, acts as a potential tumor suppressor by positively regulating PHLPP1 stability (PubMed:24145035)\n(Microbial infection) Forms a complex with Epstein-Barr virus protein EBNA3 which is an active deubiquitinase activity that may select specific substrates to promote B-lymphocyte transformation","subunit":"Interacts with WDR48 (PubMed:19075014, PubMed:27373336, PubMed:27650958). Interacts with WDR20; this interaction promotes translocation of the USP12 complex to the plasma membrane (PubMed:20147737, PubMed:27373336, PubMed:30466959). Component of the USP12-WDR20-WDR48 deubiquitinating complex (PubMed:20147737, PubMed:27373336). Component of the USP12-DMWD-WDR48 deubiquitinating complex (PubMed:33844468). Interacts with PHLPP1 (PubMed:24145035). Interacts with RBPJ (PubMed:25855980). Interacts with CBP; this interaction blocks the acetyltransferase activity of CREBBP (PubMed:31899788). Interacts with ITCH; the interaction is more efficient when both USP12 and WDR48/UAF1 are involved and may mediate recruitment of the USP12 deubiquitinating complex to Notch (PubMed:22778262). Interacts with OPTN and SQSTM1/p62; the interaction is independent of deubiquitinase activity and may be involved in regulation of autophagic flux (PubMed:30266909)\n(Microbial infection) Interacts with Epstein-Barr virus protein EBNA3","family":"Belongs to the peptidase C19 family. USP12/USP46 subfamily","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["19075014","22778262","24145035","25855980","26811477","27373336","28063927","30266909","31899788","36361894","37410794"],"location":"Nucleus；Cytoplasm；Cell membrane","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"泛素化/蛋白稳态；激酶/磷酸化信号；膜运输/高尔基/内吞；免疫/炎症/细胞死亡；线粒体/代谢；黏附/受体/细胞表面；发育/分化；注释原文：Deubiquitinating enzyme that plays various roles in the regulation of the immune response and inflammation (PubMed:19075014, PubMed:27373336).","function_evidence":"含实验支持条目；含同源推断，不能当该成员实测；ECO:0000250,ECO:0000269","categories":"泛素化/蛋白稳态；激酶/磷酸化信号；膜运输/高尔基/内吞；免疫/炎症/细胞死亡；线粒体/代谢；黏附/受体/细胞表面；发育/分化"},"USP14":{"hgnc":"HGNC:12612","symbol":"USP14","accessions":["P54578"],"name":"Ubiquitin carboxyl-terminal hydrolase 14","length":"494","function":"Proteasome-associated deubiquitinase which releases ubiquitin from the proteasome targeted ubiquitinated proteins (PubMed:35145029). Ensures the regeneration of ubiquitin at the proteasome (PubMed:18162577, PubMed:28396413). Is a reversibly associated subunit of the proteasome and a large fraction of proteasome-free protein exists within the cell (PubMed:18162577). Required for the degradation of the chemokine receptor CXCR4 which is critical for CXCL12-induced cell chemotaxis (PubMed:19106094). Also serves as a physiological inhibitor of endoplasmic reticulum-associated degradation (ERAD) under the non-stressed condition by inhibiting the degradation of unfolded endoplasmic reticulum proteins via interaction with ERN1 (PubMed:19135427). Indispensable for synaptic development and function at neuromuscular junctions (NMJs) (By similarity). Plays a role in the innate immune defense against viruses by stabilizing the viral DNA sensor CGAS and thus inhibiting its autophagic degradation (PubMed:27666593). Inhibits OPTN-mediated selective autophagic degradation of KDM4D and thereby negatively regulates H3K9me2 and H3K9me3 (PubMed:35145029)","subunit":"Homodimer (Potential). Associates with the 26S proteasome. Interacts with FANCC, CXCR4 and ERN1. Interacts with TRIM14; this interaction recruits USP14 to cleave ubiquitin chains of CGAS and KDM4D (PubMed:27666593, PubMed:35145029)","family":"Belongs to the peptidase C19 family. USP14/UBP6 subfamily","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["18162577","19106094","19135427","27666593","28396413","35145029"],"location":"Cytoplasm；Cell membrane；Peripheral membrane protein","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"泛素化/蛋白稳态；免疫/炎症/细胞死亡；线粒体/代谢；黏附/受体/细胞表面；发育/分化；注释原文：Proteasome-associated deubiquitinase which releases ubiquitin from the proteasome targeted ubiquitinated proteins (PubMed:35145029).","function_evidence":"含实验支持条目；含同源推断，不能当该成员实测；ECO:0000250,ECO:0000269","categories":"泛素化/蛋白稳态；免疫/炎症/细胞死亡；线粒体/代谢；黏附/受体/细胞表面；发育/分化"},"USP15":{"hgnc":"HGNC:12613","symbol":"USP15","accessions":["Q9Y4E8"],"name":"Ubiquitin carboxyl-terminal hydrolase 15","length":"981","function":"Hydrolase that removes conjugated ubiquitin from target proteins and regulates various pathways such as the TGF-beta receptor signaling, NF-kappa-B and RNF41/NRDP1-PRKN pathways (PubMed:16005295, PubMed:17318178, PubMed:19576224, PubMed:19826004, PubMed:21947082, PubMed:22344298, PubMed:24852371). Acts as a key regulator of TGF-beta receptor signaling pathway, but the precise mechanism is still unclear: according to a report, acts by promoting deubiquitination of monoubiquitinated R-SMADs (SMAD1, SMAD2 and/or SMAD3), thereby alleviating inhibition of R-SMADs and promoting activation of TGF-beta target genes (PubMed:21947082). According to another reports, regulates the TGF-beta receptor signaling pathway by mediating deubiquitination and stabilization of TGFBR1, leading to an enhanced TGF-beta signal (PubMed:22344298). Able to mediate deubiquitination of monoubiquitinated substrates, 'Lys-27'-, 'Lys-48'- and 'Lys-63'-linked polyubiquitin chains (PubMed:33093067). May also regulate gene expression and/or DNA repair through the deubiquitination of histone H2B (PubMed:24526689). Acts as an inhibitor of mitophagy by counteracting the action of parkin (PRKN): hydrolyzes cleavage of 'Lys-48'- and 'Lys-63'-linked polyubiquitin chains attached by parkin on target proteins such as MFN2, thereby reducing parkin's ability to drive mitophagy (PubMed:24852371). Acts as an associated component of COP9 signalosome complex (CSN) and regulates different pathways via this association: regulates NF-kappa-B by mediating deubiquitination of NFKBIA and deubiquitinates substrates bound to VCP (PubMed:16005295, PubMed:17318178, PubMed:19576224, PubMed:19826004). Involved in endosome organization by mediating deubiquitination of SQSTM1: ubiquitinated SQSTM1 forms a molecular bridge that restrains cognate vesicles in the perinuclear region and its deubiquitination releases target vesicles for fast transport into the cell periphery (PubMed:27368102). Acts as a negative regulator of antifungal immunity by mediating 'Lys-27'-linked deubiquitination of CARD9, thereby inactivating CARD9 (PubMed:33093067)\n(Microbial infection) Protects APC and human papillomavirus type 16 protein E6 against degradation via the ubiquitin proteasome pathway","subunit":"A homodimer structure has been reported; however it is unclear whether the protein form a homodimer in vivo (PubMed:22001210). Identified in a complex with the COP9 signalosome complex (CSN) (PubMed:16005295). Interacts with SMAD1, SMAD2 and SMAD3; the interaction is direct (PubMed:21947082). Forms a complex with SMURF2 and SMAD7 (PubMed:22344298). Interacts with TGFBR1 (PubMed:22344298). Interacts with SART3; the interaction is direct (PubMed:24526689). May interact with RNF20 and RNF40 (PubMed:24526689). May interact with PRKN (PubMed:24852371). Interacts with INCA1 (PubMed:21750715)\n(Microbial infection) Interacts with human papillomavirus type 16 protein E6","family":"Belongs to the peptidase C19 family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["16005295","17318178","19553310","19576224","19826004","21947082","22344298","24526689","24852371","27368102","33093067"],"location":"Cytoplasm；Nucleus；Mitochondrion","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"泛素化/蛋白稳态；染色质/转录调控；DNA修复/复制；膜运输/高尔基/内吞；免疫/炎症/细胞死亡；线粒体/代谢；黏附/受体/细胞表面；注释原文：Hydrolase that removes conjugated ubiquitin from target proteins and regulates various pathways such as the TGF-beta receptor signaling, NF-kappa-B and RNF41/NRDP1-PRKN pathways (PubMed:16005295, PubMed:17318178, PubMed:19576224, PubMed:19826004, PubMed:21947082, PubMed:22344298, PubMed:24852371).","function_evidence":"含实验支持条目；ECO:0000269","categories":"泛素化/蛋白稳态；染色质/转录调控；DNA修复/复制；膜运输/高尔基/内吞；免疫/炎症/细胞死亡；线粒体/代谢；黏附/受体/细胞表面"},"USP17L17":{"symbol":"USP17L17","accessions":["D6RBQ6"],"name":"Ubiquitin carboxyl-terminal hydrolase 17-like protein 17","length":530,"function":"Deubiquitinating enzyme that removes conjugated ubiquitin from specific proteins to regulate different cellular processes that may include cell proliferation, progression through the cell cycle, apoptosis, cell migration, and the cellular r...","subunit":"无可用SUBUNIT段","domains":"Domain: USP [80–375]","brief":"泛素化/蛋白稳态；细胞周期/分裂；免疫/炎症/细胞死亡；线粒体/代谢；注释原文：Deubiquitinating enzyme that removes conjugated ubiquitin from specific proteins to regulate different cellular processes that may include cell proliferation, progression through the cell cycle, apoptosis, cell migration, and the cellular r...","function_evidence":"含同源推断，不能当该成员实测；ECO:0000250","categories":"泛素化/蛋白稳态；细胞周期/分裂；免疫/炎症/细胞死亡；线粒体/代谢","location":"Nucleus；Endoplasmic reticulum","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020"},"USP17L2":{"hgnc":"HGNC:34434","symbol":"USP17L2","accessions":["Q6R6M4"],"name":"Ubiquitin carboxyl-terminal hydrolase 17","length":"530","function":"Deubiquitinating enzyme that removes conjugated ubiquitin from specific proteins to regulate different cellular processes. Regulates cell proliferation by deubiquitinating and inhibiting RCE1 thereby controlling the small GTPases NRAS and HRAS localization and activation. In parallel, mediates deubiquitination of CDC25A, preventing CDC25A degradation by the proteasome during the G1/S and G2/M phases promoting cell-cycle progression. Also regulates cell proliferation and apoptosis through deubiquitination of SUDS3 a regulator of histone deacetylation. Through activation of the Rho family GTPases RAC1A, CDC42 and RHOA, regulates cell migration. Through the cleavage of 'Lys-48'- and 'Lys-63'-linked polyubiquitin chains of the cytoplasmic innate immune receptors RIGI and IFIH1 stimulates the cellular response to viral infection","subunit":"Interacts with SUDS3; the interaction is direct","family":"Belongs to the peptidase C19 family. USP17 subfamily","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["14699124","17109758","19188362","20147298","20228808","20368735","20388806","21239494","21448158"],"location":"Nucleus；Endoplasmic reticulum","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"泛素化/蛋白稳态；染色质/转录调控；免疫/炎症/细胞死亡；线粒体/代谢；黏附/受体/细胞表面；注释原文：Deubiquitinating enzyme that removes conjugated ubiquitin from specific proteins to regulate different cellular processes.","function_evidence":"含实验支持条目；ECO:0000269","categories":"泛素化/蛋白稳态；染色质/转录调控；免疫/炎症/细胞死亡；线粒体/代谢；黏附/受体/细胞表面"},"USP17L23":{"hgnc":"HGNC:44451","symbol":"USP17L23","accessions":["D6RBM5"],"name":"Ubiquitin carboxyl-terminal hydrolase 17-like protein 23","length":"183","function":"未获得FUNCTION段；不等于没有已发表研究","subunit":"无可用SUBUNIT段","family":"Belongs to the peptidase C19 family. USP17 subfamily","domains":"Domain 80-183: USP","function_pmids":[],"location":"Nucleus; Endoplasmic reticulum","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"本次数据库无可用FUNCTION；只可据蛋白名称/结构域提出方向，不据此称全新功能。","function_evidence":"本次数据库无FUNCTION段；不等于无研究/无功能","categories":"泛素化/蛋白稳态；线粒体/代谢"},"USP17L4":{"hgnc":"HGNC:37176","symbol":"USP17L4","accessions":["A6NCW7"],"name":"Inactive ubiquitin carboxyl-terminal hydrolase 17-like protein 4","length":"530","function":"未获得FUNCTION段；不等于没有已发表研究","subunit":"无可用SUBUNIT段","family":"Belongs to the peptidase C19 family. USP17 subfamily","domains":"Domain 80-375: USP","function_pmids":[],"location":"Nucleus; Endoplasmic reticulum","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"本次数据库无可用FUNCTION；只可据蛋白名称/结构域提出方向，不据此称全新功能。","function_evidence":"本次数据库无FUNCTION段；不等于无研究/无功能","categories":"泛素化/蛋白稳态；线粒体/代谢"},"USP17L7":{"hgnc":"HGNC:37180","symbol":"USP17L7","accessions":["P0C7H9"],"name":"Inactive ubiquitin carboxyl-terminal hydrolase 17-like protein 7","length":"530","function":"未获得FUNCTION段；不等于没有已发表研究","subunit":"无可用SUBUNIT段","family":"Belongs to the peptidase C19 family. USP17 subfamily","domains":"Domain 80-375: USP","function_pmids":[],"location":"Nucleus; Endoplasmic reticulum","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"本次数据库无可用FUNCTION；只可据蛋白名称/结构域提出方向，不据此称全新功能。","function_evidence":"本次数据库无FUNCTION段；不等于无研究/无功能","categories":"泛素化/蛋白稳态；线粒体/代谢"},"USP17L8":{"hgnc":"HGNC:37181","symbol":"USP17L8","accessions":["P0C7I0"],"name":"Inactive ubiquitin carboxyl-terminal hydrolase 17-like protein 8","length":"530","function":"未获得FUNCTION段；不等于没有已发表研究","subunit":"无可用SUBUNIT段","family":"Belongs to the peptidase C19 family. USP17 subfamily","domains":"Domain 80-375: USP","function_pmids":[],"location":"Nucleus; Endoplasmic reticulum","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"本次数据库无可用FUNCTION；只可据蛋白名称/结构域提出方向，不据此称全新功能。","function_evidence":"本次数据库无FUNCTION段；不等于无研究/无功能","categories":"泛素化/蛋白稳态；线粒体/代谢"},"USP2":{"hgnc":"HGNC:12618","symbol":"USP2","accessions":["O75604"],"name":"Ubiquitin carboxyl-terminal hydrolase 2","length":"605","function":"Hydrolase that deubiquitinates polyubiquitinated target proteins such as MDM2, MDM4 and CCND1 (PubMed:17290220, PubMed:19838211, PubMed:19917254). Isoform 1 and isoform 4 possess both ubiquitin-specific peptidase and isopeptidase activities (By similarity). Deubiquitinates MDM2 without reversing MDM2-mediated p53/TP53 ubiquitination and thus indirectly promotes p53/TP53 degradation and limits p53 activity (PubMed:17290220, PubMed:19838211). Has no deubiquitinase activity against p53/TP53 (PubMed:17290220). Prevents MDM2-mediated degradation of MDM4 (PubMed:17290220). Plays a role in the G1/S cell-cycle progression in normal and cancer cells (PubMed:19917254). Regulates the circadian clock by modulating its intrinsic circadian rhythm and its capacity to respond to external cues (By similarity). Associates with clock proteins and deubiquitinates core clock component PER1 but does not affect its overall stability (By similarity). Regulates the nucleocytoplasmic shuttling and nuclear retention of PER1 and its repressive role on the clock transcription factors CLOCK and BMAL1 (By similarity). Plays a role in the regulation of myogenic differentiation of embryonic muscle cells (By similarity)\nCircadian clock output effector that regulates Ca(2+) absorption in the small intestine. Probably functions by regulating protein levels of the membrane scaffold protein NHERF4 in a rhythmic manner, and is therefore likely to control Ca(2+) membrane permeability mediated by the Ca(2+) channel TRPV6 in the intestine","subunit":"Homooligomer (By similarity). Found in trimeric complex with MDM2 and MDM4 and USP2. Interacts with CCND1; the interaction is direct and promotes its stabilization by antagonizing ubiquitin-dependent degradation. Interacts (via N-terminus and C-terminus) with MDM2. Interacts with MDM4. Interacts with PER1 (By similarity). Interacts with KCNQ1; counteracts the NEDD4L-specific down-regulation of I(Ks) and restore plasma membrane localization of KCNQ1 (PubMed:22024150). Isoform 4: Interacts with NHERF4 and CLTC (By similarity)","family":"Belongs to the peptidase C19 family. USP2 subfamily","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["17290220","19838211","19917254"],"location":"Cytoplasm；Cytoplasm, perinuclear region；Nucleus；Membrane；Peripheral membrane protein","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"泛素化/蛋白稳态；核质运输；染色质/转录调控；线粒体/代谢；发育/分化；注释原文：Hydrolase that deubiquitinates polyubiquitinated target proteins such as MDM2, MDM4 and CCND1 (PubMed:17290220, PubMed:19838211, PubMed:19917254).","function_evidence":"含实验支持条目；含同源推断，不能当该成员实测；ECO:0000250,ECO:0000269","categories":"泛素化/蛋白稳态；核质运输；染色质/转录调控；线粒体/代谢；发育/分化"},"USP20":{"hgnc":"HGNC:12619","symbol":"USP20","accessions":["Q9Y2K6"],"name":"Ubiquitin carboxyl-terminal hydrolase 20","length":"914","function":"Deubiquitinating enzyme that plays a role in many cellular processes including autophagy, cellular antiviral response or membrane protein biogenesis (PubMed:27801882, PubMed:29487085). Attenuates TLR4-mediated NF-kappa-B signaling by cooperating with beta-arrestin-2/ARRB2 and inhibiting TRAF6 autoubiquitination (PubMed:26839314). Promotes cellular antiviral responses by deconjugating 'Lys-33' and 'Lys-48'-linked ubiquitination of STING1 leading to its stabilization (PubMed:27801882). Plays an essential role in autophagy induction by regulating the ULK1 stability through deubiquitination of ULK1 (PubMed:29487085). Acts as a positive regulator for NF-kappa-B activation by TNF through deubiquitinating 'Lys-48'-linked polyubiquitination of SQSTM1, leading to its increased stability (PubMed:32354117). Acts as a regulator of G protein-coupled receptor (GPCR) signaling by mediating the deubiquitination beta-2 adrenergic receptor (ADRB2) (PubMed:19424180). Plays a central role in ADRB2 recycling and resensitization after prolonged agonist stimulation by constitutively binding ADRB2, mediating deubiquitination of ADRB2 and inhibiting lysosomal trafficking of ADRB2. Upon dissociation, it is probably transferred to the translocated beta-arrestins, possibly leading to beta-arrestins deubiquitination and disengagement from ADRB2 (PubMed:19424180). This suggests the existence of a dynamic exchange between the ADRB2 and beta-arrestins. Deubiquitinates DIO2, thereby regulating thyroid hormone regulation. Deubiquitinates HIF1A, leading to stabilize HIF1A and enhance HIF1A-mediated activity (PubMed:15776016). Deubiquitinates MCL1, a pivotal member of the anti-apoptotic Bcl-2 protein family to regulate its stability (PubMed:35063767). Within the endoplasmic reticulum, participates with USP33 in the rescue of post-translationally targeted membrane proteins that are inappropriately ubiquitinated by the cytosolic protein quality control in the cytosol (PubMed:33792613)","subunit":"Interacts with VHL, leading to its ubiquitination and subsequent degradation (PubMed:12056827). Interacts with CCP110 (PubMed:23486064). Interacts with DIO2 (PubMed:12865408). Interacts with HIF1A (PubMed:15776016). Interacts with ADRB2 (PubMed:19424180, PubMed:23166351). Interacts with USP18 (PubMed:27801882)","family":"Belongs to the peptidase C19 family. USP20/USP33 subfamily","domains":[],"function_pmids":["12056827","12865408","15776016","19424180","26839314","27801882","29487085","32354117","33792613","35063767"],"location":"Cytoplasm; Endoplasmic reticulum; Cytoplasm, perinuclear region; Cytoplasm, cytoskeleton, microtubule organizing center, centrosome","shared_sequence_gene_count":"1","source_snapshot":"project UniProt records20261017/18","brief":"Deubiquitinating enzyme that plays a role in many cellular processes including autophagy, cellular antiviral response or membrane protein biogenesis (PubMed:27801882, PubMed:29487085). Attenuates TLR4-mediated NF-kappa-B signaling by cooperating with beta-arrestin-2/ARRB2 and inhibiting TRAF6 autoubiquitination (PubMed:26839314). Promotes cellular antiviral responses by deconjugating 'Lys-33' and 'Lys-48'-linked ubiquitination of STING1 leading to its stabilization (PubMed:27801882). Plays an essential role in autophagy induction by regulating the ULK1 stability through deubiquitination of ULK1 (PubMed:29487085). Acts as a positive regulator for NF-kappa-B activation by TNF through deubiquitinating 'Lys-48'-linked polyubiquitination of SQSTM1, leading to its increased stability (PubMed:32354117). Acts as a regulator of G protein-coupled receptor (GPCR) signaling by mediating the deubiquitination beta-2 adrenergic receptor (ADRB2) (PubMed:19424180). Plays a central role in ADRB2 recycling and resensitization after prolonged agonist stimulation by constitutively binding ADRB2, mediating deubiquitination of ADRB2 and inhibiting lysosomal trafficking of ADRB2. Upon dissociation, it is probably transferred to the translocated beta-arrestins, possibly leading to beta-arrestins deubiquitination and disengagement from ADRB2 (PubMed:19424180). This suggests the existence of a dynamic exchange between the ADRB2 and beta-arrestins. Deubiquitinates DIO2, thereby regulating thyroid hormone regulation. Deubiquitinates HIF1A, leading to stabilize HIF1A and enhance HIF1A-mediated activity (PubMed:15776016). Deubiquitinates MCL1, a pivotal member of the anti-apoptotic Bcl-2 protein family to regulate its stability (PubMed:35063767). Within the endoplasmic reticulum, participates with USP33 in the rescue of post-translationally targeted membrane proteins that are inappropriately ubiquitinated by the cytosolic protein quality control in the cytosol (PubMed:33792613)"},"USP21":{"hgnc":"HGNC:12620","symbol":"USP21","accessions":["Q9UK80"],"name":"Ubiquitin carboxyl-terminal hydrolase 21","length":"565","function":"Deubiquitinates histone H2A, a specific tag for epigenetic transcriptional repression, thereby acting as a coactivator (By similarity). Deubiquitination of histone H2A releaves the repression of di- and trimethylation of histone H3 at 'Lys-4', resulting in regulation of transcriptional initiation (By similarity). Regulates gene expression via histone H2A deubiquitination (By similarity). Deubiquitinates BAZ2A/TIP5 leading to its stabilization (PubMed:26100909). Also capable of removing NEDD8 from NEDD8 conjugates but has no effect on Sentrin-1 conjugates (PubMed:10799498). Also acts as a negative regulator of the ribosome quality control (RQC) by mediating deubiquitination of 40S ribosomal proteins RPS10/eS10 and RPS20/uS10, thereby antagonizing ZNF598-mediated 40S ubiquitination (PubMed:32011234)","subunit":"Interacts with BEND3","family":"Belongs to the peptidase C19 family. USP21 subfamily","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["10799498","26100909","32011234"],"location":"Cytoplasm；Nucleus","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"泛素化/蛋白稳态；染色质/转录调控；翻译/核糖体；线粒体/代谢；注释原文：Deubiquitinates histone H2A, a specific tag for epigenetic transcriptional repression, thereby acting as a coactivator (By similarity).","function_evidence":"含实验支持条目；含同源推断，不能当该成员实测；ECO:0000250,ECO:0000269","categories":"泛素化/蛋白稳态；染色质/转录调控；翻译/核糖体；线粒体/代谢"},"USP22":{"hgnc":"HGNC:12621","symbol":"USP22","accessions":["Q9UPT9"],"name":"Ubiquitin carboxyl-terminal hydrolase 22","length":"525","function":"Deubiquitinase that plays a role in several cellular processes including transcriptional regulation, cell cycle progression or innate immunity. As part of the transcription regulatory histone acetylation (HAT) complex SAGA, catalyzes the deubiquitination of both histones H2A and H2B, thereby acting as a transcriptional coactivator (PubMed:18206972, PubMed:18206973, PubMed:18469533). Recruited to specific gene promoters by activators such as MYC, where it is required for transcription. Facilitates cell-cycle progression by stabilizing CCNB1 and antagonizing its proteasome-mediated degradation in a cell cycle-specific manner (PubMed:27030811). Modulates cell cycle progression and apoptosis also by antagonizing TP53 transcriptional activation through deacetylase SIRT1 stabilization (PubMed:22542455). Plays multiple roles in immunity and inflammation. Participates in antiviral response by deubiquitinating the importin KPNA2, leading to IRF3 nuclear translocation and subsequent type I interferon production (PubMed:32130408). Acts as a central regulator of type III IFN signaling by negatively regulating STING1 activation and ubiquitination (PubMed:35933402). Inhibits NLRP3 inflammasome activation by promoting NLRP3 degradation through ATG5-dependent autophagy (By similarity). Deubiquitinates CD274 to induce its stabilization and thereby participates in maintenance of immune tolerance to self (PubMed:31399419). Controls necroptotic cell death by regulating RIPK3 phosphorylation and ubiquitination (PubMed:33369872). During bacterial infection, promotes pro-inflammatory response by targeting TRAF6 and removing its 'Lys-48'-linked polyubiquitination (By similarity)","subunit":"Component of some SAGA transcription coactivator-HAT complexes, at least composed of ATXN7, ATXN7L3, ENY2, GCN5L2, SUPT3H, TAF10, TRRAP and USP22. Within the SAGA complex, ATXN7L3, ENY2 and USP22 form a subcomplex required for histone deubiquitination (PubMed:18206972, PubMed:27601583). Interacts directly with ATXN7L3; leading to its recruitment to the SAGA complex (PubMed:18206972). Interacts with ATXN7L3 and weakly with ATXN7L3B (PubMed:27601583). Interacts with MED1 (By similarity)","family":"Belongs to the peptidase C19 family. UBP8 subfamily","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["18206972","18206973","18469533","22542455","27030811","31399419","32130408","33369872","35933402"],"location":"Nucleus；Cytoplasm","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"泛素化/蛋白稳态；核质运输；染色质/转录调控；细胞周期/分裂；激酶/磷酸化信号；免疫/炎症/细胞死亡；线粒体/代谢；注释原文：Deubiquitinase that plays a role in several cellular processes including transcriptional regulation, cell cycle progression or innate immunity.","function_evidence":"含实验支持条目；含同源推断，不能当该成员实测；ECO:0000250,ECO:0000269","categories":"泛素化/蛋白稳态；核质运输；染色质/转录调控；细胞周期/分裂；激酶/磷酸化信号；免疫/炎症/细胞死亡；线粒体/代谢"},"USP26":{"hgnc":"HGNC:13485","symbol":"USP26","accessions":["Q9BXU7"],"name":"Ubiquitin carboxyl-terminal hydrolase 26","length":"913","function":"Deubiquitinase regulating several biological processes through the deubiquitination of components of these processes (PubMed:20501646, PubMed:28839133). Involved in somatic cell reprogramming through the 'Lys-48'-linked deubiquitination and stabilization of CBX4 and CBX6, two components of the polycomb-repressive complex 1 (PRC1) (PubMed:28839133). Also deubiquitinates and probably stabilizes the androgen receptor (AR), regulating the androgen receptor signaling pathway (PubMed:20501646). May play a role in spermatogenesis (PubMed:34202084)","subunit":"Interacts with RING1","family":"Belongs to the peptidase C19 family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["20501646","28839133","34202084"],"location":"Nucleus；Cytoplasm, cytoskeleton, flagellum axoneme","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"泛素化/蛋白稳态；线粒体/代谢；黏附/受体/细胞表面；发育/分化；注释原文：Deubiquitinase regulating several biological processes through the deubiquitination of components of these processes (PubMed:20501646, PubMed:28839133).","function_evidence":"含实验支持条目；ECO:0000269","categories":"泛素化/蛋白稳态；线粒体/代谢；黏附/受体/细胞表面；发育/分化"},"USP27X":{"hgnc":"HGNC:13486","symbol":"USP27X","accessions":["A6NNY8"],"name":"Ubiquitin carboxyl-terminal hydrolase 27","length":"438","function":"Deubiquitinase involved in innate antiviral immunity by mediating deubiquitination of CGAS and RIGI (PubMed:31534008, PubMed:32027733). Negatively regulates RIGI by mediating 'Lys-63'-linked deubiquitination of RIGI, inhibiting type I interferon signaling (PubMed:32027733). Also regulates 'Lys-63'-linked ubiquitination level of MDA5/IFIH1 (PubMed:32027733). Acts as a positive regulator of the cGAS-STING pathway by catalyzing 'Lys-48'-linked deubiquitination of CGAS, thereby promoting its stabilization (PubMed:31534008). Can reduce the levels of BCL2L11/BIM ubiquitination and stabilize BCL2L11 in response to the RAF-MAPK-degradation signal (By similarity). By acting on BCL2L11 levels, may counteract the anti-apoptotic effects of MAPK activity (By similarity)","subunit":"Interacts with phosphorylated BCL2L11 isoform BIMEL; this interaction leads to BCL2L11 deubiquitination and stabilization","family":"Belongs to the peptidase C19 family","domains":[],"function_pmids":["31534008","32027733"],"location":"Cytoplasm, cytosol; Nucleus","shared_sequence_gene_count":"1","source_snapshot":"project UniProt records20261017/18","brief":"Deubiquitinase involved in innate antiviral immunity by mediating deubiquitination of CGAS and RIGI (PubMed:31534008, PubMed:32027733). Negatively regulates RIGI by mediating 'Lys-63'-linked deubiquitination of RIGI, inhibiting type I interferon signaling (PubMed:32027733). Also regulates 'Lys-63'-linked ubiquitination level of MDA5/IFIH1 (PubMed:32027733). Acts as a positive regulator of the cGAS-STING pathway by catalyzing 'Lys-48'-linked deubiquitination of CGAS, thereby promoting its stabilization (PubMed:31534008). Can reduce the levels of BCL2L11/BIM ubiquitination and stabilize BCL2L11 in response to the RAF-MAPK-degradation signal (By similarity). By acting on BCL2L11 levels, may counteract the anti-apoptotic effects of MAPK activity (By similarity)"},"USP28":{"hgnc":"HGNC:12625","symbol":"USP28","accessions":["Q96RU2"],"name":"Ubiquitin carboxyl-terminal hydrolase 28","length":"1077","function":"Deubiquitinase involved in DNA damage response checkpoint and MYC proto-oncogene stability. Involved in DNA damage induced apoptosis by specifically deubiquitinating proteins of the DNA damage pathway such as CLSPN. Also involved in G2 DNA damage checkpoint, by deubiquitinating CLSPN, and preventing its degradation by the anaphase promoting complex/cyclosome (APC/C). In contrast, it does not deubiquitinate PLK1. Specifically deubiquitinates MYC in the nucleoplasm, leading to prevent MYC degradation by the proteasome: acts by specifically interacting with isoform 1 of FBXW7 (FBW7alpha) in the nucleoplasm and counteracting ubiquitination of MYC by the SCF(FBW7) complex. In contrast, it does not interact with isoform 4 of FBXW7 (FBW7gamma) in the nucleolus, allowing MYC degradation and explaining the selective MYC degradation in the nucleolus. Deubiquitinates ZNF304, hence preventing ZNF304 degradation by the proteasome and leading to the activated KRAS-mediated promoter hypermethylation and transcriptional silencing of tumor suppressor genes (TSGs) in a subset of colorectal cancers (CRC) cells (PubMed:24623306)","subunit":"Interacts with ZNF304 (PubMed:24623306). Interacts with PRKD1 (PubMed:24623306). Interacts with TP53BP1 (PubMed:16901786). Interacts with isoform 1 of FBXW7; following DNA damage, dissociates from FBXW7 leading to degradation of MYC (PubMed:17558397, PubMed:17873522)","family":"Belongs to the peptidase C19 family. USP28 subfamily","domains":[],"function_pmids":["16901786","17558397","17873522","18662541","24623306"],"location":"Nucleus, nucleoplasm","shared_sequence_gene_count":"1","source_snapshot":"project UniProt records20261017/18","brief":"Deubiquitinase involved in DNA damage response checkpoint and MYC proto-oncogene stability. Involved in DNA damage induced apoptosis by specifically deubiquitinating proteins of the DNA damage pathway such as CLSPN. Also involved in G2 DNA damage checkpoint, by deubiquitinating CLSPN, and preventing its degradation by the anaphase promoting complex/cyclosome (APC/C). In contrast, it does not deubiquitinate PLK1. Specifically deubiquitinates MYC in the nucleoplasm, leading to prevent MYC degradation by the proteasome: acts by specifically interacting with isoform 1 of FBXW7 (FBW7alpha) in the nucleoplasm and counteracting ubiquitination of MYC by the SCF(FBW7) complex. In contrast, it does not interact with isoform 4 of FBXW7 (FBW7gamma) in the nucleolus, allowing MYC degradation and explaining the selective MYC degradation in the nucleolus. Deubiquitinates ZNF304, hence preventing ZNF304 degradation by the proteasome and leading to the activated KRAS-mediated promoter hypermethylation and transcriptional silencing of tumor suppressor genes (TSGs) in a subset of colorectal cancers (CRC) cells (PubMed:24623306)"},"USP30":{"hgnc":"HGNC:20065","symbol":"USP30","accessions":["Q70CQ3"],"name":"Ubiquitin carboxyl-terminal hydrolase 30","length":"517","function":"Deubiquitinating enzyme tethered to the mitochondrial outer membrane that acts as a key inhibitor of mitophagy by counteracting the action of parkin (PRKN): hydrolyzes ubiquitin attached by parkin on target proteins, such as RHOT1/MIRO1 and TOMM20, thereby blocking parkin's ability to drive mitophagy (PubMed:18287522, PubMed:24896179, PubMed:25527291, PubMed:25621951). Preferentially cleaves 'Lys-6'- and 'Lys-11'-linked polyubiquitin chains, 2 types of linkage that participate in mitophagic signaling (PubMed:25621951). Does not cleave efficiently polyubiquitin phosphorylated at 'Ser-65' (PubMed:25527291). Acts as a negative regulator of mitochondrial fusion by mediating deubiquitination of MFN1 and MFN2 (By similarity)","subunit":"无可用SUBUNIT段","family":"Belongs to the peptidase C19 family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["18287522","24896179","25527291","25621951"],"location":"Mitochondrion outer membrane","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"泛素化/蛋白稳态；激酶/磷酸化信号；线粒体/代谢；注释原文：Deubiquitinating enzyme tethered to the mitochondrial outer membrane that acts as a key inhibitor of mitophagy by counteracting the action of parkin (PRKN): hydrolyzes ubiquitin attached by parkin on target proteins, such as RHOT1/MIRO1 and TOMM20, thereby blocking parkin's ability to drive mitophagy (PubMed:18287522, PubMed:24896179, PubMed:25527291, PubMed:25621951).","function_evidence":"含实验支持条目；含同源推断，不能当该成员实测；ECO:0000250,ECO:0000269","categories":"泛素化/蛋白稳态；激酶/磷酸化信号；线粒体/代谢"},"USP34":{"hgnc":"HGNC:20066","symbol":"USP34","accessions":["Q70CQ2"],"name":"Ubiquitin carboxyl-terminal hydrolase 34","length":"3546","function":"Ubiquitin hydrolase that can remove conjugated ubiquitin from AXIN1 and AXIN2, thereby acting as a regulator of Wnt signaling pathway. Acts as an activator of the Wnt signaling pathway downstream of the beta-catenin destruction complex by deubiquitinating and stabilizing AXIN1 and AXIN2, leading to promote nuclear accumulation of AXIN1 and AXIN2 and positively regulate beta-catenin (CTNBB1)-mediated transcription. Recognizes and hydrolyzes the peptide bond at the C-terminal Gly of ubiquitin. Involved in the processing of poly-ubiquitin precursors as well as that of ubiquitinated proteins","subunit":"Interacts with AXIN1 and AXIN2","family":"Belongs to the peptidase C19 family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["21383061"],"location":"当前记录无定位注释","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"泛素化/蛋白稳态；染色质/转录调控；线粒体/代谢；注释原文：Ubiquitin hydrolase that can remove conjugated ubiquitin from AXIN1 and AXIN2, thereby acting as a regulator of Wnt signaling pathway.","function_evidence":"含实验支持条目；ECO:0000269","categories":"泛素化/蛋白稳态；染色质/转录调控；线粒体/代谢"},"USP36":{"hgnc":"HGNC:20062","symbol":"USP36","accessions":["Q9P275"],"name":"Ubiquitin carboxyl-terminal hydrolase 36","length":"1123","function":"Deubiquitinase essential for the regulation of nucleolar structure and function (PubMed:19208757, PubMed:22902402, PubMed:29273634). Required for cell and organism viability (PubMed:19208757, PubMed:22902402, PubMed:29273634). Plays an important role in ribosomal RNA processing and protein synthesis, which is mediated, at least in part, through deubiquitination of DHX33, NPM1 and FBL, regulating their protein stability (PubMed:19208757, PubMed:22902402, PubMed:29273634, PubMed:36912080). Functions as a transcriptional repressor by deubiquiting histone H2B at the promoters of genes critical for cellular differentiation, such as CDKN1A, thereby preventing histone H3 'Lys-4' trimethylation (H3K4) (PubMed:29274341). Specifically deubiquitinates MYC in the nucleolus, leading to prevent MYC degradation by the proteasome: acts by specifically interacting with isoform 3 of FBXW7 (FBW7gamma) in the nucleolus and counteracting ubiquitination of MYC by the SCF(FBW7) complex (PubMed:25775507). In contrast, it does not interact with isoform 1 of FBXW7 (FBW7alpha) in the nucleoplasm (PubMed:25775507). Interacts to and regulates the actions of E3 ubiquitin-protein ligase NEDD4L over substrates such as NTRK1, KCNQ2 and KCNQ3, affecting their expression an functions (PubMed:27445338). Deubiquitinates SOD2, regulates SOD2 protein stability (PubMed:21268071). Deubiquitinase activity is required to control selective autophagy activation by ubiquitinated proteins (PubMed:22622177). Promotes CEP63 stabilization through 'Lys-48'-linked deubiquitination leading to increased stability (PubMed:35989368). Acts as a SUMO ligase to promote EXOSC10 sumoylation critical for the nucleolar RNA exosome function in rRNA processing (PubMed:36912080). Binds to pre-rRNAs (PubMed:36912080)","subunit":"Interacts with isoform 3 of FBXW7; the interaction inhibits MYC degradation induced by SCF(FBW7) complex (PubMed:25775507). Interacts with NTRK1; USP36 does not deubiquitinate NTRK1 (PubMed:27445338). Interacts with NEDD4L (via domains WW1, 3 and 4); the interaction inhibits ubiquitination of, at least, NTRK1, KCNQ2 and KCNQ3 by NEDD4L (PubMed:27445338). Interacts (via C-terminus) with EXOSC10 (via C-terminus); the interaction is facilitated by the association with RNA and promotes sumoylation of EXOSC10 (PubMed:36912080)","family":"Belongs to the peptidase C19 family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["19208757","21268071","22622177","22902402","25775507","27445338","29273634","29274341","35989368","36912080"],"location":"Nucleus, nucleolus；Cytoplasm","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"泛素化/蛋白稳态；RNA加工/剪接；染色质/转录调控；翻译/核糖体；线粒体/代谢；发育/分化；注释原文：Deubiquitinase essential for the regulation of nucleolar structure and function (PubMed:19208757, PubMed:22902402, PubMed:29273634).","function_evidence":"含实验支持条目；ECO:0000269","categories":"泛素化/蛋白稳态；RNA加工/剪接；染色质/转录调控；翻译/核糖体；线粒体/代谢；发育/分化"},"USP4":{"hgnc":"HGNC:12627","symbol":"USP4","accessions":["Q13107"],"name":"Ubiquitin carboxyl-terminal hydrolase 4","length":"963","function":"Deubiquitinating enzyme that removes conjugated ubiquitin from target proteins (PubMed:16316627, PubMed:16339847, PubMed:16472766, PubMed:20595234, PubMed:22347420, PubMed:25404403, PubMed:28604766, PubMed:30514904). Deubiquitinates PDPK1 (PubMed:22347420). Deubiquitinates TRIM21 (PubMed:16316627). Deubiquitinates receptor ADORA2A which increases the amount of functional receptor at the cell surface (PubMed:16339847). Deubiquitinates HAS2 (PubMed:28604766). Deubiquitinates MAVs leading to maintain MAVS protein stability, resulting in increased production of type I interferons (IFN-I) and enhanced antiviral innate immune responses against viral infections (PubMed:39589880). Deubiquitinates RHEB in response to EGF signaling, promoting mTORC1 signaling (PubMed:30514904). May regulate mRNA splicing through deubiquitination of the U4 spliceosomal protein PRPF3 (PubMed:20595234). This may prevent its recognition by the U5 component PRPF8 thereby destabilizing interactions within the U4/U6.U5 snRNP (PubMed:20595234). May also play a role in the regulation of quality control in the ER (PubMed:16339847)","subunit":"Interacts with RB1 (both dephosphorylated and hypophosphorylated forms) (PubMed:11571652). Interacts with RBL1 and RBL2 (By similarity). Interacts with ADORA2A (via cytoplasmic C-terminus); the interaction is direct (PubMed:16339847). Interacts with SART3; recruits USP4 to its substrate PRPF3 (PubMed:20595234)","family":"Belongs to the peptidase C19 family. USP4 subfamily","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["16316627","16339847","16472766","20595234","22347420","25404403","28604766","30514904","39589880"],"location":"Cytoplasm；Nucleus","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"泛素化/蛋白稳态；RNA加工/剪接；免疫/炎症/细胞死亡；线粒体/代谢；黏附/受体/细胞表面；注释原文：Deubiquitinating enzyme that removes conjugated ubiquitin from target proteins (PubMed:16316627, PubMed:16339847, PubMed:16472766, PubMed:20595234, PubMed:22347420, PubMed:25404403, PubMed:28604766, PubMed:30514904).","function_evidence":"含实验支持条目；ECO:0000269","categories":"泛素化/蛋白稳态；RNA加工/剪接；免疫/炎症/细胞死亡；线粒体/代谢；黏附/受体/细胞表面"},"USP42":{"hgnc":"HGNC:20068","symbol":"USP42","accessions":["Q9H9J4"],"name":"Ubiquitin carboxyl-terminal hydrolase 42","length":"1324","function":"Deubiquitinating enzyme which may play an important role during spermatogenesis","subunit":"","family":"Belongs to the peptidase C19 family","domains":[],"function_pmids":[],"location":"","shared_sequence_gene_count":"1","source_snapshot":"project UniProt records20261017/18","brief":"Deubiquitinating enzyme which may play an important role during spermatogenesis"},"USP46":{"hgnc":"HGNC:20075","symbol":"USP46","accessions":["P62068"],"name":"Ubiquitin carboxyl-terminal hydrolase 46","length":"366","function":"Deubiquitinating enzyme that plays a role in behavior, possibly by regulating GABA action. May act by mediating the deubiquitination of GAD1/GAD67 (By similarity). Has almost no deubiquitinating activity by itself and requires the interaction with WDR48 to have a high activity (PubMed:19075014, PubMed:26388029). Not involved in deubiquitination of monoubiquitinated FANCD2 (PubMed:19075014)","subunit":"Interacts with WDR48 (PubMed:19075014, PubMed:26388029). Interacts with WDR20 (PubMed:20147737). Interacts with DMWD (PubMed:33844468). Component of the USP46/WDR20/WDR48 deubiquitinating complex","family":"Belongs to the peptidase C19 family. USP12/USP46 subfamily","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["19075014","26388029"],"location":"Cytoplasm","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"泛素化/蛋白稳态；线粒体/代谢；注释原文：Deubiquitinating enzyme that plays a role in behavior, possibly by regulating GABA action.","function_evidence":"含实验支持条目；含同源推断，不能当该成员实测；ECO:0000250,ECO:0000269","categories":"泛素化/蛋白稳态；线粒体/代谢"},"USP47":{"hgnc":"HGNC:20076","symbol":"USP47","accessions":["Q96K76"],"name":"Ubiquitin carboxyl-terminal hydrolase 47","length":"1375","function":"Ubiquitin-specific protease that specifically deubiquitinates monoubiquitinated DNA polymerase beta (POLB), stabilizing POLB thereby playing a role in base-excision repair (BER). Acts as a regulator of cell growth and genome integrity. May also indirectly regulate CDC25A expression at a transcriptional level","subunit":"Interacts with BTRC and FBXW11. Interacts with POLB","family":"Belongs to the peptidase C19 family","domains":[],"function_pmids":["19966869","21362556"],"location":"Cytoplasm","shared_sequence_gene_count":"1","source_snapshot":"project UniProt records20261017/18","brief":"Ubiquitin-specific protease that specifically deubiquitinates monoubiquitinated DNA polymerase beta (POLB), stabilizing POLB thereby playing a role in base-excision repair (BER). Acts as a regulator of cell growth and genome integrity. May also indirectly regulate CDC25A expression at a transcriptional level"},"USP48":{"hgnc":"HGNC:18533","symbol":"USP48","accessions":["Q86UV5"],"name":"Ubiquitin carboxyl-terminal hydrolase 48","length":"1035","function":"Deubiquitinase that recognizes and hydrolyzes the peptide bond at the C-terminal Gly of ubiquitin. Involved in the processing of polyubiquitin precursors as well as that of ubiquitinated proteins (PubMed:16214042, PubMed:34059922). Plays a role in the regulation of NF-kappa-B activation by TNF receptor superfamily via its interactions with RELA and TRAF2. May also play a regulatory role at postsynaptic sites. Plays an important role in cell cycle progression by deubiquitinating Aurora B/AURKB and thereby extending its stability (PubMed:34445214). In the context of H.pylori infection, stabilizes nuclear RELA through deubiquitination, thereby promoting the transcriptional activity of RELA to prolong TNFAIP3 de novo synthesis. Consequently, TNFAIP3 suppresses caspase activity and apoptotic cell death (PubMed:35913642). Also functions in the modulation of the ciliary and synaptic transport as well as cytoskeleton organization, which are key for photoreceptor function and homeostasis. To achieve this, stabilizes the levels of the retinal degeneration-associated proteins ARL3 and UNC119 using distinct mechanisms (PubMed:36293380). Plays a positive role in pyroptosis by stabilizing gasdermin E/GSDME through removal of its 'Lys-48'-linked ubiquitination (PubMed:36607699)","subunit":"Interacts with TRAF2 and RELA. Interacts with GPS1 (PubMed:35913642)","family":"Belongs to the peptidase C19 family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["16214042","34059922","34445214","35913642","36293380","36607699"],"location":"Cytoplasm；Nucleus；Cell projection, cilium","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"泛素化/蛋白稳态；染色质/转录调控；细胞周期/分裂；细胞骨架/纤毛；免疫/炎症/细胞死亡；线粒体/代谢；黏附/受体/细胞表面；注释原文：Deubiquitinase that recognizes and hydrolyzes the peptide bond at the C-terminal Gly of ubiquitin.","function_evidence":"含实验支持条目；ECO:0000269","categories":"泛素化/蛋白稳态；染色质/转录调控；细胞周期/分裂；细胞骨架/纤毛；免疫/炎症/细胞死亡；线粒体/代谢；黏附/受体/细胞表面"},"USP5":{"hgnc":"HGNC:12628","symbol":"USP5","accessions":["P45974"],"name":"Ubiquitin carboxyl-terminal hydrolase 5","length":"858","function":"Deubiquitinating enzyme that participates in a wide range of cellular processes by specifically cleaving isopeptide bonds between ubiquitin and substrate proteins or ubiquitin itself. Affects thereby important cellular signaling pathways such as NF-kappa-B, Wnt/beta-catenin, and cytokine production by regulating ubiquitin-dependent protein degradation. Participates in the activation of the Wnt signaling pathway by promoting FOXM1 deubiquitination and stabilization that induces the recruitment of beta-catenin to Wnt target gene promoter (PubMed:26912724). Regulates the assembly and disassembly of heat-induced stress granules by mediating the hydrolysis of unanchored ubiquitin chains (PubMed:29567855). Promotes lipopolysaccharide-induced apoptosis and inflammatory response by stabilizing the TXNIP protein (PubMed:37534934). Affects T-cell biology by stabilizing the inhibitory receptor on T-cells PDC1 (PubMed:37208329). Acts as a negative regulator of autophagy by regulating ULK1 at both protein and mRNA levels (PubMed:37607937). Acts also as a negative regulator of type I interferon production by simultaneously removing both 'Lys-48'-linked unanchored and 'Lys-63'-linked anchored polyubiquitin chains on the transcription factor IRF3 (PubMed:39761299). Modulates the stability of DNA mismatch repair protein MLH1 and counteracts the effect of the ubiquitin ligase UBR4 (PubMed:39032648). Upon activation by insulin, it gets phosphorylated through mTORC1-mediated phosphorylation to enhance YTHDF1 stability by removing 'Lys-11'-linked polyubiquitination (PubMed:39900921). May also deubiquitinate other substrates such as the calcium channel CACNA1H (By similarity)","subunit":"Homodimer (PubMed:39900921). Interacts with TRIML1","family":"Belongs to the peptidase C19 family","domains":[],"function_pmids":["19098288","26912724","29567855","37208329","37534934","39032648","39761299","39900921"],"location":"Cytoplasm; Cytoplasm, Stress granule; Nucleus","shared_sequence_gene_count":"1","source_snapshot":"project UniProt records20261017/18","brief":"Deubiquitinating enzyme that participates in a wide range of cellular processes by specifically cleaving isopeptide bonds between ubiquitin and substrate proteins or ubiquitin itself. Affects thereby important cellular signaling pathways such as NF-kappa-B, Wnt/beta-catenin, and cytokine production by regulating ubiquitin-dependent protein degradation. Participates in the activation of the Wnt signaling pathway by promoting FOXM1 deubiquitination and stabilization that induces the recruitment of beta-catenin to Wnt target gene promoter (PubMed:26912724). Regulates the assembly and disassembly of heat-induced stress granules by mediating the hydrolysis of unanchored ubiquitin chains (PubMed:29567855). Promotes lipopolysaccharide-induced apoptosis and inflammatory response by stabilizing the TXNIP protein (PubMed:37534934). Affects T-cell biology by stabilizing the inhibitory receptor on T-cells PDC1 (PubMed:37208329). Acts as a negative regulator of autophagy by regulating ULK1 at both protein and mRNA levels (PubMed:37607937). Acts also as a negative regulator of type I interferon production by simultaneously removing both 'Lys-48'-linked unanchored and 'Lys-63'-linked anchored polyubiquitin chains on the transcription factor IRF3 (PubMed:39761299). Modulates the stability of DNA mismatch repair protein MLH1 and counteracts the effect of the ubiquitin ligase UBR4 (PubMed:39032648). Upon activation by insulin, it gets phosphorylated through mTORC1-mediated phosphorylation to enhance YTHDF1 stability by removing 'Lys-11'-linked polyubiquitination (PubMed:39900921). May also deubiquitinate other substrates such as the calcium channel CACNA1H (By similarity)"},"USP7":{"hgnc":"HGNC:12630","symbol":"USP7","accessions":["Q93009"],"name":"Ubiquitin C-terminal hydrolase 7","length":"1102","function":"Hydrolase that deubiquitinates target proteins such as ARMC5, FOXO4, DEPTOR, KAT5, p53/TP53, MDM2, ERCC6, DNMT1, UHRF1, PTEN, KMT2E/MLL5 and DAXX (PubMed:11923872, PubMed:15053880, PubMed:16964248, PubMed:18716620, PubMed:25283148, PubMed:25865756, PubMed:26678539, PubMed:28655758, PubMed:33544460, PubMed:35216969). Together with DAXX, prevents MDM2 self-ubiquitination and enhances the E3 ligase activity of MDM2 towards p53/TP53, thereby promoting p53/TP53 ubiquitination and proteasomal degradation (PubMed:15053880, PubMed:16845383, PubMed:18566590, PubMed:20153724). Deubiquitinates p53/TP53, preventing degradation of p53/TP53, and enhances p53/TP53-dependent transcription regulation, cell growth repression and apoptosis (PubMed:25283148). Deubiquitinates p53/TP53 and MDM2 and strongly stabilizes p53/TP53 even in the presence of excess MDM2, and also induces p53/TP53-dependent cell growth repression and apoptosis (PubMed:11923872, PubMed:26786098). Deubiquitination of FOXO4 in presence of hydrogen peroxide is not dependent on p53/TP53 and inhibits FOXO4-induced transcriptional activity (PubMed:16964248). In association with DAXX, is involved in the deubiquitination and translocation of PTEN from the nucleus to the cytoplasm, both processes that are counteracted by PML (PubMed:18716620). Deubiquitinates KMT2E/MLL5 preventing KMT2E/MLL5 proteasomal-mediated degradation (PubMed:26678539). Involved in cell proliferation during early embryonic development. Involved in transcription-coupled nucleotide excision repair (TC-NER) in response to UV damage: recruited to DNA damage sites following interaction with KIAA1530/UVSSA and promotes deubiquitination of ERCC6, preventing UV-induced degradation of ERCC6 (PubMed:22466611, PubMed:22466612). Involved in maintenance of DNA methylation via its interaction with UHRF1 and DNMT1: acts by mediating deubiquitination of UHRF1 and DNMT1, preventing their degradation and promoting DNA methylation by DNMT1 (PubMed:21745816, PubMed:22411829). Deubiquitinates alkylation repair enzyme ALKBH3. OTUD4 recruits USP7 and USP9X to stabilize ALKBH3, thereby promoting the repair of alkylated DNA lesions (PubMed:25944111). Acts as a chromatin regulator via its association with the Polycomb group (PcG) multiprotein PRC1-like complex; may act by deubiquitinating components of the PRC1-like complex (PubMed:20601937). Able to mediate deubiquitination of histone H2B; it is however unsure whether this activity takes place in vivo (PubMed:20601937). Exhibits a preference towards 'Lys-48'-linked ubiquitin chains (PubMed:22689415). Increases regulatory T-cells (Treg) suppressive capacity by deubiquitinating and stabilizing the transcription factor FOXP3 which is crucial for Treg cell function (PubMed:23973222). Plays a role in the maintenance of the circadian clock periodicity via deubiquitination and stabilization of the CRY1 and CRY2 proteins (PubMed:27123980). Deubiquitinates REST, thereby stabilizing REST and promoting the maintenance of neural progenitor cells (PubMed:21258371). Deubiquitinates SIRT7, inhibiting SIRT7 histone deacetylase activity and regulating gluconeogenesis (PubMed:28655758). Involved in the regulation of WASH-dependent actin polymerization at the surface of endosomes and the regulation of endosomal protein recycling (PubMed:26365382). It maintains optimal WASH complex activity and precise F-actin levels via deubiquitination of TRIM27 and WASHC1 (PubMed:26365382). Mediates the deubiquitination of phosphorylated DEPTOR, promoting its stability and leading to decreased mTORC1 signaling (PubMed:35216969). Deubiquitinates H2AB1, H2BC4 and H2BC22 (By similarity)\n(Microbial infection) Contributes to the overall stabilization and trans-activation capability of the herpesvirus 1 trans-acting transcriptional protein ICP0/VMW110 during HSV-1 infection\n(Microbial infection) Upon infection with Epstein-Barr virus, the interaction with viral EBNA1 increases the association of USP7 with PML proteins, which is required for the polyubiquitylation and degradation of PML","subunit":"Monomer. Homodimer. Part of a complex with DAXX, MDM2, RASSF1 and USP7 (PubMed:18566590). Part of a complex with DAXX, MDM2 and USP7 (PubMed:16845383). Interacts with MDM2; the interaction is independent of p53/TP53. Interacts with DAXX; the interaction is direct and independent of MDM2 and p53/TP53 (PubMed:16845383). Component of a complex composed of KMT2E/MLL5 (isoform 3), OGT (isoform 1) and USP7; the complex stabilizes KMT2E/MLL5, preventing KMT2E/MLL5 ubiquitination and proteasomal-mediated degradation (PubMed:26678539). Interacts (via MATH domain) with KMT2E/MLL5 isoform 3 (PubMed:26678539). Interacts with OGT isoform 1 (PubMed:26678539). Interacts with FOXO4; the interaction is enhanced in presence of hydrogen peroxide and occurs independently of p53/TP53 (PubMed:16964248). Interacts with p53/TP53; the interaction is enhanced in response to DNA damage (PubMed:25283148). Interacts with TSPYL5; this impairs interaction with p53/TP53 (PubMed:21170034). Interacts with PTEN; the interaction is direct (PubMed:18716620). Interacts with ATXN1 and the strength of interaction is influenced by the length of the poly-Gln region in ATXN1 (PubMed:12093161). A weaker interaction seen with mutants having longer poly-Gln regions (PubMed:12093161). Interacts with KIAA1530/UVSSA (PubMed:22466611, PubMed:22466612). Interacts with ABRAXAS2; the interaction is direct (PubMed:25283148). Identified in a complex with TP53/p53 and ABRAXAS2 (PubMed:25283148). Interacts with MEX3C and antagonizes its ability to degrade mRNA (PubMed:22863774). Interacts with DNMT1 and UHRF1 (PubMed:21745816, PubMed:22411829). Interacts with FOXP3 (PubMed:23973222). Interacts (via MATH domain) with RNF220. Associated component of the Polycomb group (PcG) multiprotein PRC1-like complex (PubMed:20601937). Interacts with EPOP (By similarity). Interacts with OTUD4 and USP9X; the interaction is direct (PubMed:25944111). Interacts with CRY2 (PubMed:27123980). Interacts with REST (PubMed:21258371). Interacts with ERCC6 (PubMed:26030138). Part of a complex consisting of USP7, MAGEL2 and TRIM27; directly interacts with MAGEL2; directly interacts with TRIM27 (PubMed:26365382). Interacts with FAM170A; this interaction promotes USP7 nuclear translocation and deubiquitinating activity (By similarity)\n(Microbial infection) Isoform 1 and isoform 2 interact with herpesvirus 1 trans-acting transcriptional protein ICP0/VMW110 (PubMed:14506283, PubMed:16160161, PubMed:18590780, PubMed:9034339). Binding to ICP0/VMW110 may modulate the substrate specificity or activity of USP7 to stabilize viral proteins\n(Microbial infection) Interacts with Epstein-Barr virus EBNA1; the interaction is independent and simultaneous to EBNA1 interaction with USP7 as well as necessary for PML nuclear bodies disruption by EBNA1 (PubMed:14506283, PubMed:24216761). EBNA1, USP7 and CSNK2B form a ternary complex. EBNA1 shows a 10-fold higher affinity than p53/TP53 and can compete with it for USP7 binding (PubMed:14506283)\n(Microbial infection) Interacts with human cytomegalovirus proteins UL35 and UL35A; these interactions inhibit the ability of USP7 to form nuclear bodies\n(Microbial infection) Interacts with herpes virus 8/HHV-8 proteins vIRF-1 and vIRF-3; these interactions may disrupt TP53 signaling pathway during viral infection by decreasing the availability of USP7 for deubiquitinating and stabilizing TP53\n(Microbial infection) Interacts with herpes virus 8/HHV-8 protein vIRF-2; this interaction modulates antiviral signaling via disruption of USP7 interactions with innate immune signaling proteins TRAF3 and TRAF6 thus affecting their ubiquitination","family":"Belongs to the peptidase C19 family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["11923872","14506283","15053880","16160161","16845383","16964248","18566590","18590780","18716620","20153724","20601937","20719947","21258371","21745816","22411829","22466611","22466612","22689415","23973222","24216761","25283148","25865756","25944111","26365382","26678539","26786098","27123980","28655758","33544460","35216969"],"location":"Nucleus；Cytoplasm；Nucleus, PML body；Chromosome","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"泛素化/蛋白稳态；染色质/转录调控；DNA修复/复制；激酶/磷酸化信号；膜运输/高尔基/内吞；细胞骨架/纤毛；免疫/炎症/细胞死亡；线粒体/代谢；发育/分化；注释原文：Hydrolase that deubiquitinates target proteins such as ARMC5, FOXO4, DEPTOR, KAT5, p53/TP53, MDM2, ERCC6, DNMT1, UHRF1, PTEN, KMT2E/MLL5 and DAXX (PubMed:11923872, PubMed:15053880, PubMed:16964248, PubMed:18716620, PubMed:25283148, PubMed:25865756, PubMed:26678539, PubMed:28655758, PubMed:33544460, PubMed:35216969).","function_evidence":"含实验支持条目；含同源推断，不能当该成员实测；ECO:0000250,ECO:0000269","categories":"泛素化/蛋白稳态；染色质/转录调控；DNA修复/复制；激酶/磷酸化信号；膜运输/高尔基/内吞；细胞骨架/纤毛；免疫/炎症/细胞死亡；线粒体/代谢；发育/分化"},"USP9X":{"hgnc":"HGNC:12632","symbol":"USP9X","accessions":["Q93008"],"name":"Ubiquitin carboxyl-terminal hydrolase 9X","length":"2554","function":"Deubiquitinase involved both in the processing of ubiquitin precursors and of ubiquitinated proteins (PubMed:18254724, PubMed:19135894, PubMed:22371489, PubMed:25944111, PubMed:29626158, PubMed:30914461, PubMed:37454738). May therefore play an important regulatory role at the level of protein turnover by preventing degradation of proteins through the removal of conjugated ubiquitin (PubMed:18254724, PubMed:19135894, PubMed:22371489, PubMed:25944111, PubMed:29626158, PubMed:30914461, PubMed:37454738). Specifically hydrolyzes 'Lys-11'-, followed by 'Lys-63'-, 'Lys-48'- and 'Lys-6'-linked polyubiquitins chains (PubMed:30914461). Essential component of TGF-beta/BMP signaling cascade (PubMed:19135894). Specifically deubiquitinates monoubiquitinated SMAD4, opposing the activity of E3 ubiquitin-protein ligase TRIM33 (PubMed:19135894). Deubiquitinates alkylation repair enzyme ALKBH3 (PubMed:25944111). OTUD4 recruits USP7 and USP9X to stabilize ALKBH3, thereby promoting the repair of alkylated DNA lesions (PubMed:25944111). Deubiquitinates RNA demethylase enzyme ALKBH5, promoting its stability (PubMed:37454738). Deubiquitinates mTORC2 complex component RICTOR at 'Lys-294' by removing 'Lys-63'-linked polyubiquitin chains, stabilizing RICTOR and enhancing its binding to MTOR, thus promoting mTORC2 complex assembly (PubMed:33378666). Regulates chromosome alignment and segregation in mitosis by regulating the localization of BIRC5/survivin to mitotic centromeres (PubMed:16322459). Involved in axonal growth and neuronal cell migration (PubMed:24607389). Regulates cellular clock function by enhancing the protein stability and transcriptional activity of the core circadian protein BMAL1 via its deubiquitinating activity (PubMed:29626158). Acts as a regulator of peroxisome import by mediating deubiquitination of PEX5: specifically deubiquitinates PEX5 monoubiquitinated at 'Cys-11' following its retrotranslocation into the cytosol, resetting PEX5 for a subsequent import cycle (PubMed:22371489). Deubiquitinates PEG10 (By similarity). Inhibits the activation of the Hippo signaling pathway via deubiquitination of AMOTL2 at 'Lys-347' and 'Lys-408' which prohibits its interaction with and activation of LATS2. Loss of LATS2 activation and subsequent loss of YAP1 phosphorylation results in an increase in YAP1-driven transcription of target genes (PubMed:26598551, PubMed:34404733)","subunit":"Interacts with SMAD4, MARK4, NUAK1 and BIRC5/survivin (PubMed:16322459, PubMed:18254724, PubMed:19135894). Interacts with DCX (PubMed:24607389). Interacts with OTUD4 and USP7; the interaction is direct (PubMed:25944111)","family":"Belongs to the peptidase C19 family","domains":[],"function_pmids":["16322459","18254724","19135894","22371489","24607389","25944111","26598551","29626158","30914461","33378666","34404733","37454738"],"location":"Cytoplasm, cytosol; Cell projection, growth cone; Cytoplasm, cytoskeleton, cilium axoneme","shared_sequence_gene_count":"1","source_snapshot":"project UniProt records20261017/18","brief":"Deubiquitinase involved both in the processing of ubiquitin precursors and of ubiquitinated proteins (PubMed:18254724, PubMed:19135894, PubMed:22371489, PubMed:25944111, PubMed:29626158, PubMed:30914461, PubMed:37454738). May therefore play an important regulatory role at the level of protein turnover by preventing degradation of proteins through the removal of conjugated ubiquitin (PubMed:18254724, PubMed:19135894, PubMed:22371489, PubMed:25944111, PubMed:29626158, PubMed:30914461, PubMed:37454738). Specifically hydrolyzes 'Lys-11'-, followed by 'Lys-63'-, 'Lys-48'- and 'Lys-6'-linked polyubiquitins chains (PubMed:30914461). Essential component of TGF-beta/BMP signaling cascade (PubMed:19135894). Specifically deubiquitinates monoubiquitinated SMAD4, opposing the activity of E3 ubiquitin-protein ligase TRIM33 (PubMed:19135894). Deubiquitinates alkylation repair enzyme ALKBH3 (PubMed:25944111). OTUD4 recruits USP7 and USP9X to stabilize ALKBH3, thereby promoting the repair of alkylated DNA lesions (PubMed:25944111). Deubiquitinates RNA demethylase enzyme ALKBH5, promoting its stability (PubMed:37454738). Deubiquitinates mTORC2 complex component RICTOR at 'Lys-294' by removing 'Lys-63'-linked polyubiquitin chains, stabilizing RICTOR and enhancing its binding to MTOR, thus promoting mTORC2 complex assembly (PubMed:33378666). Regulates chromosome alignment and segregation in mitosis by regulating the localization of BIRC5/survivin to mitotic centromeres (PubMed:16322459). Involved in axonal growth and neuronal cell migration (PubMed:24607389). Regulates cellular clock function by enhancing the protein stability and transcriptional activity of the core circadian protein BMAL1 via its deubiquitinating activity (PubMed:29626158). Acts as a regulator of peroxisome import by mediating deubiquitination of PEX5: specifically deubiquitinates PEX5 monoubiquitinated at 'Cys-11' following its retrotranslocation into the cytosol, resetting PEX5 for a subsequent import cycle (PubMed:22371489). Deubiquitinates PEG10 (By similarity). Inhibits the activation of the Hippo signaling pathway via deubiquitination of AMOTL2 at 'Lys-347' and 'Lys-408' which prohibits its interaction with and activation of LATS2. Loss of LATS2 activation and subsequent loss of YAP1 phosphorylation results in an increase in YAP1-driven transcription of target genes (PubMed:26598551, PubMed:34404733)"},"USP9Y":{"hgnc":"HGNC:12633","symbol":"USP9Y","accessions":["O00507"],"name":"Ubiquitin carboxyl-terminal hydrolase 9Y","length":"2555","function":"Deubiquitinase that mediates deubiquitination of target proteins (PubMed:12895410). May stabilize target proteins that are important for male germ cell development (PubMed:12895410)","subunit":"无可用SUBUNIT段","family":"Belongs to the peptidase C19 family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["12895410"],"location":"当前记录无定位注释","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"泛素化/蛋白稳态；线粒体/代谢；发育/分化；注释原文：Deubiquitinase that mediates deubiquitination of target proteins (PubMed:12895410).","function_evidence":"含实验支持条目；ECO:0000269","categories":"泛素化/蛋白稳态；线粒体/代谢；发育/分化"},"UTP11":{"hgnc":"HGNC:24329","symbol":"UTP11","accessions":["Q9Y3A2"],"name":"Probable U3 small nucleolar RNA-associated protein 11","length":"253","function":"Part of the small subunit (SSU) processome, first precursor of the small eukaryotic ribosomal subunit. During the assembly of the SSU processome in the nucleolus, many ribosome biogenesis factors, an RNA chaperone and ribosomal proteins associate with the nascent pre-rRNA and work in concert to generate RNA folding, modifications, rearrangements and cleavage as well as targeted degradation of pre-ribosomal RNA by the RNA exosome. Involved in nucleolar processing of pre-18S ribosomal RNA","subunit":"Part of the small subunit (SSU) processome, composed of more than 70 proteins and the RNA chaperone small nucleolar RNA (snoRNA) U3","family":"Belongs to the UTP11 family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["34516797"],"location":"Nucleus, nucleolus","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"RNA加工/剪接；翻译/核糖体；注释原文：Part of the small subunit (SSU) processome, first precursor of the small eukaryotic ribosomal subunit.","function_evidence":"含实验支持条目；ECO:0000269","categories":"RNA加工/剪接；翻译/核糖体"},"UTP14A":{"hgnc":"HGNC:10665","symbol":"UTP14A","accessions":["Q9BVJ6"],"name":"U3 small nucleolar RNA-associated protein 14 homolog A","length":"771","function":"Part of the small subunit (SSU) processome, first precursor of the small eukaryotic ribosomal subunit (PubMed:34516797). During the assembly of the SSU processome in the nucleolus, many ribosome biogenesis factors, an RNA chaperone and ribosomal proteins associate with the nascent pre-rRNA and work in concert to generate RNA folding, modifications, rearrangements and cleavage as well as targeted degradation of pre-ribosomal RNA by the RNA exosome (PubMed:34516797). Ensures correct nucleolar localization of small ribosomal subunit processome member EMG1 as part of a complex with NOC4L and NOP14 (PubMed:27798105)","subunit":"Part of the small subunit (SSU) processome, composed of more than 70 proteins and the RNA chaperone small nucleolar RNA (snoRNA) U3 (PubMed:34516797). Component of a complex composed of NOC4L, NOP14 and UTP14A; the complex is required for nucleolar localization of small ribosomal subunit processome member EMG1 (PubMed:27798105). Interacts with DHX37 (PubMed:30582406)","family":"Belongs to the UTP14 family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["27798105","34516797"],"location":"Nucleus, nucleolus","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"RNA加工/剪接；翻译/核糖体；注释原文：Part of the small subunit (SSU) processome, first precursor of the small eukaryotic ribosomal subunit (PubMed:34516797).","function_evidence":"含实验支持条目；ECO:0000269","categories":"RNA加工/剪接；翻译/核糖体"},"UTP14C":{"hgnc":"HGNC:20321","symbol":"UTP14C","accessions":["Q5TAP6"],"name":"U3 small nucleolar RNA-associated protein 14 homolog C","length":"766","function":"Essential for spermatogenesis. May be required specifically for ribosome biogenesis and hence protein synthesis during male meiosis (By similarity)","subunit":"无可用SUBUNIT段","family":"Belongs to the UTP14 family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["15289605"],"location":"Nucleus, nucleolus","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"翻译/核糖体；发育/分化；注释原文：Essential for spermatogenesis.","function_evidence":"含实验支持条目；含同源推断，不能当该成员实测；ECO:0000250,ECO:0000269","categories":"翻译/核糖体；发育/分化"},"UTP20":{"hgnc":"HGNC:17897","symbol":"UTP20","accessions":["O75691"],"name":"Small subunit processome component 20 homolog","length":"2785","function":"Part of the small subunit (SSU) processome, first precursor of the small eukaryotic ribosomal subunit. During the assembly of the SSU processome in the nucleolus, many ribosome biogenesis factors, an RNA chaperone and ribosomal proteins associate with the nascent pre-rRNA and work in concert to generate RNA folding, modifications, rearrangements and cleavage as well as targeted degradation of pre-ribosomal RNA by the RNA exosome. Involved in 18S pre-rRNA processing. Associates with U3 snoRNA","subunit":"Part of the small subunit (SSU) processome, composed of more than 70 proteins and the RNA chaperone small nucleolar RNA (snoRNA) U3 (PubMed:34516797). Interacts with FBL and PPP1R26 (PubMed:16053918, PubMed:17498821)","family":"Belongs to the UTP20 family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["17498821","34516797"],"location":"Nucleus, nucleolus","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"RNA加工/剪接；翻译/核糖体；注释原文：Part of the small subunit (SSU) processome, first precursor of the small eukaryotic ribosomal subunit.","function_evidence":"含实验支持条目；ECO:0000269","categories":"RNA加工/剪接；翻译/核糖体"},"UTP23":{"hgnc":"HGNC:28224","symbol":"UTP23","accessions":["Q9BRU9"],"name":"rRNA-processing protein UTP23 homolog","length":"249","function":"Involved in rRNA-processing and ribosome biogenesis","subunit":"无可用SUBUNIT段","family":"Belongs to the UTP23/FCF1 family. UTP23 subfamily","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":[],"location":"Nucleus, nucleolus","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"翻译/核糖体；注释原文：Involved in rRNA-processing and ribosome biogenesis","function_evidence":"含同源推断，不能当该成员实测；ECO:0000250","categories":"翻译/核糖体"},"UTP25":{"hgnc":"HGNC:28440","symbol":"UTP25","accessions":["Q68CQ4"],"name":"U3 small nucleolar RNA-associated protein 25 homolog","length":"756","function":"Component of the ribosomal small subunit processome for the biogenesis of ribosomes, functions in pre-ribosomal RNA (pre-rRNA) processing (By similarity). Essential for embryonic development in part through the regulation of p53 pathway. Controls the expansion growth of digestive organs and liver (PubMed:23357851, PubMed:25007945, PubMed:27657329). Also involved in the sympathetic neuronal development (By similarity). Mediates, with CAPN3, the proteasome-independent degradation of p53/TP53 (PubMed:23357851, PubMed:27657329)","subunit":"Interacts with CAPN3; the interaction is required for CAPN3 translocation to the nucleolus","family":"Belongs to the UTP25 family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["23357851","25007945","27657329"],"location":"Nucleus, nucleolus","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"泛素化/蛋白稳态；翻译/核糖体；发育/分化；注释原文：Component of the ribosomal small subunit processome for the biogenesis of ribosomes, functions in pre-ribosomal RNA (pre-rRNA) processing (By similarity).","function_evidence":"含实验支持条目；含同源推断，不能当该成员实测；ECO:0000250,ECO:0000269","categories":"泛素化/蛋白稳态；翻译/核糖体；发育/分化"},"UTP3":{"hgnc":"HGNC:24477","symbol":"UTP3","accessions":["Q9NQZ2"],"name":"Something about silencing protein 10","length":"479","function":"Essential for gene silencing: has a role in the structure of silenced chromatin. Plays a role in the developing brain (By similarity). Part of the small subunit (SSU) processome, first precursor of the small eukaryotic ribosomal subunit. During the assembly of the SSU processome in the nucleolus, many ribosome biogenesis factors, an RNA chaperone and ribosomal proteins associate with the nascent pre-rRNA and work in concert to generate RNA folding, modifications, rearrangements and cleavage as well as targeted degradation of pre-ribosomal RNA by the RNA exosome (PubMed:34516797)","subunit":"Part of the small subunit (SSU) processome, composed of more than 70 proteins and the RNA chaperone small nucleolar RNA (snoRNA) U3","family":"Belongs to the SAS10 family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["34516797"],"location":"Nucleus, nucleolus","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"RNA加工/剪接；染色质/转录调控；翻译/核糖体；注释原文：Essential for gene silencing: has a role in the structure of silenced chromatin.","function_evidence":"含实验支持条目；含同源推断，不能当该成员实测；ECO:0000250,ECO:0000269","categories":"RNA加工/剪接；染色质/转录调控；翻译/核糖体"},"UTP4":{"hgnc":"HGNC:1983","symbol":"UTP4","accessions":["Q969X6"],"name":"U3 small nucleolar RNA-associated protein 4 homolog","length":"686","function":"Ribosome biogenesis factor. Involved in nucleolar processing of pre-18S ribosomal RNA. Part of the small subunit (SSU) processome, first precursor of the small eukaryotic ribosomal subunit. During the assembly of the SSU processome in the nucleolus, many ribosome biogenesis factors, an RNA chaperone and ribosomal proteins associate with the nascent pre-rRNA and work in concert to generate RNA folding, modifications, rearrangements and cleavage as well as targeted d Involved in SSU pre-rRNA processing at sites A', A0, 1 and 2b. Required for optimal pre-ribosomal RNA transcription by RNA polymerase (PubMed:17699751, PubMed:19732766, PubMed:34516797). May be a transcriptional regulator (PubMed:22916032)\n(Microbial infection) Acts as a positive regulator of HIVEP1 which specifically binds to the DNA sequence 5'-GGGACTTTCC-3' found in enhancer elements of numerous viral promoters such as those of HIV-1, SV40, or CMV","subunit":"Interacts with HIVEP1 (PubMed:19732766) Interacts with NOL11 (PubMed:22916032). Part of the small subunit (SSU) processome, composed of more than 70 proteins and the RNA chaperone small nucleolar RNA (snoRNA) U3 (PubMed:34516797). May be a component of the proposed t-UTP subcomplex of the ribosomal small subunit (SSU) processome containing at least UTP4, WDR43, HEATR1, UTP15, WDR75 (PubMed:17699751, PubMed:22916032, PubMed:24219289)","family":"","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["17699751","19732766","22916032","34516797"],"location":"Nucleus, nucleolus；Chromosome","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"RNA加工/剪接；染色质/转录调控；翻译/核糖体；注释原文：Ribosome biogenesis factor.","function_evidence":"含实验支持条目；ECO:0000269","categories":"RNA加工/剪接；染色质/转录调控；翻译/核糖体"},"UVRAG":{"hgnc":"HGNC:12640","symbol":"UVRAG","accessions":["Q9P2Y5"],"name":"UV radiation resistance-associated gene protein","length":"699","function":"Versatile protein that is involved in regulation of different cellular pathways implicated in membrane trafficking. Involved in regulation of the COPI-dependent retrograde transport from Golgi and the endoplasmic reticulum by associating with the NRZ complex; the function is dependent on its binding to phosphatidylinositol 3-phosphate (PtdIns(3)P) (PubMed:16799551, PubMed:18552835, PubMed:20643123, PubMed:24056303, PubMed:28306502). During autophagy acts as a regulatory subunit of the alternative PI3K complex II (PI3KC3-C2) that mediates formation of phosphatidylinositol 3-phosphate and is believed to be involved in maturation of autophagosomes and endocytosis. Activates lipid kinase activity of PIK3C3 (PubMed:16799551, PubMed:20643123, PubMed:24056303, PubMed:28306502). Involved in the regulation of degradative endocytic trafficking and cytokinesis, and in regulation of ATG9A transport from the Golgi to the autophagosome; the functions seems to implicate its association with PI3KC3-C2 (PubMed:16799551, PubMed:20643123, PubMed:24056303). Involved in maturation of autophagosomes and degradative endocytic trafficking independently of BECN1 but depending on its association with a class C Vps complex (possibly the HOPS complex); the association is also proposed to promote autophagosome recruitment and activation of Rab7 and endosome-endosome fusion events (PubMed:18552835, PubMed:28306502). Enhances class C Vps complex (possibly HOPS complex) association with a SNARE complex and promotes fusogenic SNARE complex formation during late endocytic membrane fusion (PubMed:24550300). In case of negative-strand RNA virus infection is required for efficient virus entry, promotes endocytic transport of virions and is implicated in a VAMP8-specific fusogenic SNARE complex assembly (PubMed:24550300)\nInvolved in maintaining chromosomal stability. Promotes DNA double-strand break (DSB) repair by association with DNA-dependent protein kinase complex DNA-PK and activating it in non-homologous end joining (NHEJ) (PubMed:22542840). Required for centrosome stability and proper chromosome segregation (PubMed:22542840)","subunit":"Component of the PI3K (PI3KC3/PI3K-III/class III phosphatidylinositol 3-kinase) complex II (PI3KC3-C2) in which the core composed of the catalytic subunit PIK3C3, the regulatory subunit PIK3R4 and BECN1 is associated with UVRAG; in the complex interacts directly with BECN1. PI3KC3-C2 can associate with further regulatory subunits such as RUBCN and probably SH3GLB1/Bif-1 (PubMed:16799551, PubMed:18843052, PubMed:19050071, PubMed:19270696, PubMed:20643123, PubMed:23878393, PubMed:24056303). Interacts with SH3GLB1; UVRAG bridges the interaction to BECN1 indicative for an association with the PI3K complex PI3KC3-C2 (PubMed:17891140). Interacts with RINT1. Associates with the NRZ complex under basal conditions and dissociates from it under autophagy conditions to associate with the PI3K complex; these complex associations seem to be mutually exclusive (PubMed:24056303). Interacts with VPS16; VPS11; VPS18; VPS33 (VPS33A or VPS33B) and VPS39; indicative for an association with a class C Vps tethering complex (possibly the HOPS complex) (PubMed:18552835, PubMed:25533187). Interacts with RAB7A; RAB7A competes with UVRAG for RUBCN binding (PubMed:20974968, PubMed:25533187). Interacts with STX7, VTI1B, STX8 (PubMed:24550300). Interacts with PRKDC, XRCC6 and XRCC5; indicative for an association with the DNA-dependent protein kinase complex DNA-PK. Interacts with CEP63 (PubMed:22542840). Directly interacts with FEZ1 and SCOC; the interaction with SCOC is reduced by amino acid starvation, but the complex is stabilized in the presence of FEZ1 (PubMed:22354037). Interacts with BECN1P1/BECN2 (PubMed:23954414). Interacts with SLAMF1 (PubMed:22493499). Interacts with RUBCNL/PACER; promoting targeting of UVRAG to autophagosome (PubMed:28306502). Interacts with WNK1 (PubMed:27911840)","family":"","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["18552835","20643123","22542840","24056303","28306502"],"location":"Late endosome；Lysosome；Cytoplasmic vesicle, autophagosome；Early endosome；Endoplasmic reticulum；Midbody；Chromosome, centromere","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"细胞周期/分裂；激酶/磷酸化信号；膜运输/高尔基/内吞；细胞骨架/纤毛；线粒体/代谢；注释原文：Versatile protein that is involved in regulation of different cellular pathways implicated in membrane trafficking.","function_evidence":"含实验支持条目；ECO:0000269,ECO:0000305","categories":"细胞周期/分裂；激酶/磷酸化信号；膜运输/高尔基/内吞；细胞骨架/纤毛；线粒体/代谢"},"UXT":{"hgnc":"HGNC:12641","symbol":"UXT","accessions":["Q9UBK9"],"name":"Protein UXT","length":"157","function":"Involved in gene transcription regulation (PubMed:21730289, PubMed:28106301). Acts in concert with the corepressor URI1 to regulate androgen receptor AR-mediated transcription (PubMed:11854421, PubMed:21730289). Together with URI1, associates with chromatin to the NKX3-1 promoter region (PubMed:21730289). Negatively regulates the transcriptional activity of the estrogen receptor ESR1 by inducing its translocation into the cytoplasm (PubMed:28106301). May act as nuclear chaperone that facilitates the formation of the NF-kappa-B enhanceosome and thus positively regulates NF-kappa-B transcription activity (PubMed:17620405, PubMed:21307340). Potential component of mitochondrial-associated LRPPRC, a multidomain organizer that potentially integrates mitochondria and the microtubular cytoskeleton with chromosome remodeling (PubMed:17554592). Increasing concentrations of UXT contributes to progressive aggregation of mitochondria and cell death potentially through its association with LRPPRC (PubMed:17554592). Suppresses cell transformation and it might mediate this function by interaction and inhibition of the biological activity of cell proliferation and survival stimulatory factors like MECOM (PubMed:17635584)\nPlays a role in protecting cells against TNF-induced apoptosis by preventing the recruitment of FADD and caspase 8 to the apoptotic complex I, composed of TRADD, TRAF2 and RIPK1/RIP","subunit":"Homohexamer (PubMed:16221885). Component of the PAQosome complex which is responsible for the biogenesis of several protein complexes and which consists of R2TP complex members RUVBL1, RUVBL2, RPAP3 and PIH1D1, URI complex members PFDN2, PFDN6, PDRG1, UXT and URI1 as well as ASDURF, POLR2E and DNAAF10/WDR92 (PubMed:31738558). Interacts with LRPPRC (PubMed:11827465, PubMed:17554592). Interacts with androgen receptor AR (via N-terminus) (PubMed:11854421). Interacts with estrogen receptor ESR1; the interaction relocalizes ESR1 from the nucleus to the cytoplasm (PubMed:28106301). In the nucleus, interacts specifically with RELA (via RHD domain) and forms a dynamic complex with NF-kappa-B and is recruited to the NF-kappa-B enhanceosome upon stimulation (PubMed:17620405). Interacts with MECOM (PubMed:17635584). Interacts with URI1 (PubMed:21730289)\nPart of complex I composed of TNF receptor TNFRSF1A, TRADD, TRAF2 and RIPK1 formed in response to TNF stimulation. Within the complex, interacts (via TPQE motif) with TRAF2; the interaction prevents the recruitment of FADD and CASP8/caspase 8 to complex I","family":"Belongs to the UXT family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["11827465","11854421","16221885","17554592","17620405","17635584","21307340","21730289","28106301"],"location":"Cytoplasm；Nucleus；Cytoplasm, cytoskeleton, microtubule organizing center, centrosome；Cytoplasm, cytoskeleton, spindle pole","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"染色质/转录调控；细胞骨架/纤毛；免疫/炎症/细胞死亡；线粒体/代谢；黏附/受体/细胞表面；注释原文：Involved in gene transcription regulation (PubMed:21730289, PubMed:28106301).","function_evidence":"含实验支持条目；ECO:0000269","categories":"染色质/转录调控；细胞骨架/纤毛；免疫/炎症/细胞死亡；线粒体/代谢；黏附/受体/细胞表面"},"VAMP5":{"hgnc":"HGNC:12646","symbol":"VAMP5","accessions":["O95183"],"name":"Vesicle-associated membrane protein 5","length":"116","function":"May participate in trafficking events that are associated with myogenesis, such as myoblast fusion and/or GLUT4 trafficking","subunit":"无可用SUBUNIT段","family":"Belongs to the synaptobrevin family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":[],"location":"Cell membrane；Single-pass type IV membrane protein；Endomembrane system；Golgi apparatus, trans-Golgi network membrane","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"膜运输/高尔基/内吞；注释原文：May participate in trafficking events that are associated with myogenesis, such as myoblast fusion and/or GLUT4 trafficking","function_evidence":"数据库整理/推断；按原文限定；","categories":"膜运输/高尔基/内吞"},"VAPA":{"hgnc":"HGNC:12648","symbol":"VAPA","accessions":["Q9P0L0"],"name":"Vesicle-associated membrane protein-associated protein A","length":"249","function":"Endoplasmic reticulum (ER)-anchored protein that mediates the formation of contact sites between the ER and endosomes via interaction with FFAT motif-containing proteins such as STARD3 or WDR44 (PubMed:32344433, PubMed:33124732). STARD3-VAPA interaction enables cholesterol transfer from the ER to endosomes (PubMed:33124732). Via interaction with WDR44 participates in neosynthesized protein export (PubMed:32344433). In addition, recruited to the plasma membrane through OSBPL3 binding (PubMed:25447204). The OSBPL3-VAPA complex stimulates RRAS signaling which in turn attenuates integrin beta-1 (ITGB1) activation at the cell surface (PubMed:25447204). With OSBPL3, may regulate ER morphology (PubMed:16143324). May play a role in vesicle trafficking (PubMed:11511104, PubMed:19289470)","subunit":"Homodimer; disulfide-linked (PubMed:11511104, PubMed:33124732). Heterodimer with VAPB (PubMed:11511104). Interacts with VAMP1, VAMP2, STX1A, BET1, SEC22C and with the C-terminal domain of OCLN (PubMed:10523508, PubMed:11511104, PubMed:9657962). Interacts (via MSP domain) with OSBPL1A (via FFAT motif) (PubMed:33124732). Interacts (via MSP domain) with ZFYVE27; may retain ZFYVE27 in the endoplasmic reticulum and regulate its function in cell projections formation (PubMed:19289470, PubMed:21976701). Interacts with OSBP (PubMed:20178991). Interacts (via C-terminus) with RSAD2/viperin (via C-terminus) (PubMed:21957124). Interacts with IFITM3 (PubMed:23601107). Interacts with OSBPL3 (phosphorylated form) (PubMed:16143324, PubMed:25447204). Interacts with KIF5A in a ZFYVE27-dependent manner (PubMed:21976701). Interacts (via MSP domain) with STARD3 (via phosphorylated FFAT motif); this interaction recruits VAPA to the endosome (PubMed:24105263, PubMed:33124732). Interacts with STARD3NL (via FFAT motif) (PubMed:24105263). Interacts with CERT1 (PubMed:16895911). Interacts with PLEKHA3 and SACM1L to form a ternary complex (PubMed:30659099). Interacts with VPS13A (via FFAT motif) (PubMed:30741634). Interacts with RB1CC1 (via phosphorylated FFAT motif), MIGA2 (via phosphorylated FFAT motif), RMDN3 (via phosphorylated FFAT motif), KCNB1 (via phosphorylated FFAT motif) and KCNB2 (via phosphorylated FFAT motif) (PubMed:33124732). Interacts (via MSP domain) with WDR44 (via FFAT-like motif); the interactions connect the endoplasmic reticulum (ER) with the endosomal tubule (PubMed:32344433)\n(Microbial infection) Interacts with HCV protein NS5A and NS5B (PubMed:21957124)","family":"Belongs to the VAMP-associated protein (VAP) (TC 9.B.17) family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["11511104","16143324","19289470","25447204","32344433","33124732"],"location":"Endoplasmic reticulum membrane；Single-pass type IV membrane protein；Cell membrane；Cell junction, tight junction；Nucleus membrane","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"膜运输/高尔基/内吞；黏附/受体/细胞表面；注释原文：Endoplasmic reticulum (ER)-anchored protein that mediates the formation of contact sites between the ER and endosomes via interaction with FFAT motif-containing proteins such as STARD3 or WDR44 (PubMed:32344433, PubMed:33124732).","function_evidence":"含实验支持条目；ECO:0000269","categories":"膜运输/高尔基/内吞；黏附/受体/细胞表面"},"VASH1":{"hgnc":"HGNC:19964","symbol":"VASH1","accessions":["Q7L8A9"],"name":"Tubulinyl-Tyr carboxypeptidase 1","length":"365","function":"Tyrosine carboxypeptidase that removes the C-terminal tyrosine residue of alpha-tubulin, thereby regulating microtubule dynamics and function (PubMed:29146869, PubMed:31171830, PubMed:31235910, PubMed:31235911, PubMed:31270470). Critical for spindle function and accurate chromosome segregation during mitosis since microtubule detyrosination regulates mitotic spindle length and postioning (PubMed:31171830). Acts as an angiogenesis inhibitor: inhibits migration, proliferation and network formation by endothelial cells as well as angiogenesis (PubMed:15467828, PubMed:16488400, PubMed:16707096, PubMed:19204325). This inhibitory effect is selective to endothelial cells as it does not affect the migration of smooth muscle cells or fibroblasts (PubMed:15467828, PubMed:16488400, PubMed:16707096)","subunit":"Interacts with SVBP; interaction enhances VASH1 tyrosine carboxypeptidase activity","family":"Belongs to the transglutaminase-like superfamily. Vasohibin family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["15467828","16488400","16707096","19204325","29146869","31171830","31235910","31235911","31270470"],"location":"Cytoplasm；Secreted","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"细胞周期/分裂；细胞骨架/纤毛；注释原文：Tyrosine carboxypeptidase that removes the C-terminal tyrosine residue of alpha-tubulin, thereby regulating microtubule dynamics and function (PubMed:29146869, PubMed:31171830, PubMed:31235910, PubMed:31235911, PubMed:31270470).","function_evidence":"含实验支持条目；ECO:0000269","categories":"细胞周期/分裂；细胞骨架/纤毛"},"VASN":{"hgnc":"HGNC:18517","symbol":"VASN","accessions":["Q6EMK4"],"name":"Vasorin","length":"673","function":"May act as an inhibitor of TGF-beta signaling","subunit":"Interacts with TGFB1, TGFB2 and TGFB3","family":"","domains":[],"function_pmids":["15247411"],"location":"Membrane; Secreted","shared_sequence_gene_count":"1","source_snapshot":"project UniProt records20261017/18","brief":"May act as an inhibitor of TGF-beta signaling"},"VAX1":{"hgnc":"HGNC:12660","symbol":"VAX1","accessions":["Q5SQQ9"],"name":"Ventral anterior homeobox 1","length":"334","function":"Transcription factor that may function in dorsoventral specification of the forebrain. Required for axon guidance and major tract formation in the developing forebrain. May contribute to the differentiation of the neuroretina, pigmented epithelium and optic stalk (By similarity)","subunit":"","family":"Belongs to the EMX homeobox family","domains":[],"function_pmids":[],"location":"Nucleus","shared_sequence_gene_count":"1","source_snapshot":"project UniProt records20261017/18","brief":"Transcription factor that may function in dorsoventral specification of the forebrain. Required for axon guidance and major tract formation in the developing forebrain. May contribute to the differentiation of the neuroretina, pigmented epithelium and optic stalk (By similarity)"},"VBP1":{"hgnc":"HGNC:12662","symbol":"VBP1","accessions":["P61758"],"name":"Prefoldin subunit 3","length":"197","function":"Binds specifically to cytosolic chaperonin (c-CPN) and transfers target proteins to it. Binds to nascent polypeptide chain and promotes folding in an environment in which there are many competing pathways for nonnative proteins","subunit":"Heterohexamer of two PFD-alpha type and four PFD-beta type subunits. Binds to the C-terminal part of VHL","family":"Belongs to the prefoldin subunit alpha family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["9630229"],"location":"Cytoplasm；Nucleus","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"；注释原文：Binds specifically to cytosolic chaperonin (c-CPN) and transfers target proteins to it.","function_evidence":"含实验支持条目；ECO:0000269","categories":"未归类"},"VCF1":{"hgnc":"HGNC:25918","symbol":"VCF1","accessions":["Q969W3"],"name":"Protein VCF1","length":"186","function":"未获得FUNCTION段；不等于没有已发表研究","subunit":"无可用SUBUNIT段","family":"Belongs to the VCF family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":[],"location":"当前记录无定位注释","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"本次数据库无可用FUNCTION；只可据蛋白名称/结构域提出方向，不据此称全新功能。","function_evidence":"本次数据库无FUNCTION段；不等于无研究/无功能","categories":"未归类"},"VCF2":{"hgnc":"HGNC:25085","symbol":"VCF2","accessions":["Q5XKR9"],"name":"Protein VCF2","length":"115","function":"未获得FUNCTION段；不等于没有已发表研究","subunit":"无可用SUBUNIT段","family":"Belongs to the VCF family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":[],"location":"当前记录无定位注释","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"本次数据库无可用FUNCTION；只可据蛋白名称/结构域提出方向，不据此称全新功能。","function_evidence":"本次数据库无FUNCTION段；不等于无研究/无功能","categories":"未归类"},"VCP":{"hgnc":"HGNC:12666","symbol":"VCP","accessions":["P55072"],"name":"Transitional endoplasmic reticulum ATPase","length":"806","function":"Necessary for the fragmentation of Golgi stacks during mitosis and for their reassembly after mitosis. Involved in the formation of the transitional endoplasmic reticulum (tER). The transfer of membranes from the endoplasmic reticulum to the Golgi apparatus occurs via 50-70 nm transition vesicles which derive from part-rough, part-smooth transitional elements of the endoplasmic reticulum (tER). Vesicle budding from the tER is an ATP-dependent process. The ternary complex containing UFD1, VCP and NPLOC4 binds ubiquitinated proteins and is necessary for the export of misfolded proteins from the ER to the cytoplasm, where they are degraded by the proteasome. The NPLOC4-UFD1-VCP complex regulates spindle disassembly at the end of mitosis and is necessary for the formation of a closed nuclear envelope. Regulates E3 ubiquitin-protein ligase activity of RNF19A. Component of the VCP/p97-AMFR/gp78 complex that participates in the final step of the sterol-mediated ubiquitination and endoplasmic reticulum-associated degradation (ERAD) of HMGCR. Mediates the endoplasmic reticulum-associated degradation of CHRNA3 in cortical neurons as part of the STUB1-VCP-UBXN2A complex (PubMed:26265139). Involved in endoplasmic reticulum stress-induced pre-emptive quality control, a mechanism that selectively attenuates the translocation of newly synthesized proteins into the endoplasmic reticulum and reroutes them to the cytosol for proteasomal degradation (PubMed:26565908). Involved in clearance process by mediating G3BP1 extraction from stress granules (PubMed:29804830, PubMed:34739333). Also involved in DNA damage response: recruited to double-strand breaks (DSBs) sites in a RNF8- and RNF168-dependent manner and promotes the recruitment of TP53BP1 at DNA damage sites (PubMed:22020440, PubMed:22120668). Recruited to stalled replication forks by SPRTN: may act by mediating extraction of DNA polymerase eta (POLH) to prevent excessive translesion DNA synthesis and limit the incidence of mutations induced by DNA damage (PubMed:23042605, PubMed:23042607). Together with SPRTN metalloprotease, involved in the repair of covalent DNA-protein cross-links (DPCs) during DNA synthesis (PubMed:32152270). Involved in interstrand cross-link repair in response to replication stress by mediating unloading of the ubiquitinated CMG helicase complex (By similarity). Mediates extraction of PARP1 trapped to chromatin: recognizes and binds ubiquitinated PARP1 and promotes its removal (PubMed:35013556). Required for cytoplasmic retrotranslocation of stressed/damaged mitochondrial outer-membrane proteins and their subsequent proteasomal degradation (PubMed:16186510, PubMed:21118995). Essential for the maturation of ubiquitin-containing autophagosomes and the clearance of ubiquitinated protein by autophagy (PubMed:20104022, PubMed:27753622, PubMed:38762759). Acts as a negative regulator of type I interferon production by interacting with RIGI: interaction takes place when RIGI is ubiquitinated via 'Lys-63'-linked ubiquitin on its CARD domains, leading to recruit RNF125 and promote ubiquitination and degradation of RIGI (PubMed:26471729). May play a role in the ubiquitin-dependent sorting of membrane proteins to lysosomes where they undergo degradation (PubMed:21822278). May more particularly play a role in caveolins sorting in cells (PubMed:21822278, PubMed:23335559). By controlling the steady-state expression of the IGF1R receptor, indirectly regulates the insulin-like growth factor receptor signaling pathway (PubMed:26692333)","subunit":"Homohexamer. Forms a ring-shaped particle of 12.5 nm diameter, that displays 6-fold radial symmetry. Part of a ternary complex containing STX5A, NSFL1C and VCP. NSFL1C forms a homotrimer that binds to one end of a VCP homohexamer. The complex binds to membranes enriched in phosphatidylethanolamine-containing lipids and promotes Golgi membrane fusion. Binds to a heterodimer of NPLOC4 and UFD1, binding to this heterodimer inhibits Golgi-membrane fusion (PubMed:26471729, PubMed:38762759). Interaction with VCIP135 leads to dissociation of the complex via ATP hydrolysis by VCP. Part of a ternary complex containing NPLOC4, UFD1 and VCP. Interacts with NSFL1C-like protein p37; the complex has membrane fusion activity and is required for Golgi and endoplasmic reticulum biogenesis. Interacts with SELENOS and SYVN1, as well as with DERL1 (via SHP-box motif), DERL2 and DERL3; which probably transfer misfolded proteins from the ER to VCP (PubMed:15215856, PubMed:16186509, PubMed:16186510, PubMed:16289116, PubMed:16449189, PubMed:27714797). Interacts with SVIP and forms a complex with SVIP and DERL1 (PubMed:17872946). Component of a complex required to couple retrotranslocation, ubiquitination and deglycosylation composed of NGLY1, SAKS1, AMFR, VCP and RAD23B. Part of a complex composed of STUB1/CHIP, VCP/p97, CHRNA3, and UBXN2A that modulates the ubiquitination and endoplasmic reticulum-associated degradation (ERAD) of CHRNA3 (PubMed:26265139). Within the complex UBXN2A acts as a scaffold protein required for the interaction of CHRNA3 with VCP/p97, this interaction also inhibits CHRNA3 ubiquitination by STUB1/CHIP and subsequently ERAD (PubMed:26265139). Interacts with UBXN2A (via UBX domain); the interaction is required for the interaction of CHRNA3 in the STUB1-VCP-UBXN2A complex (PubMed:26265139). Directly interacts with UBXN4 and RNF19A. Interacts with CASR. Interacts with UBE4B and YOD1. Interacts with clathrin. Interacts with RNF103. Interacts with TRIM13 and TRIM21. Component of a VCP/p97-AMFR/gp78 complex that participates in the final step of the endoplasmic reticulum-associated degradation (ERAD) of HMGCR. Interacts directly with AMFR/gp78 (via its VIM). Interacts with RHBDD1 (via C-terminal domain). Interacts with SPRTN; leading to recruitment to stalled replication forks (PubMed:23042605, PubMed:23042607). Interacts with WASHC5. Interacts with UBOX5. Interacts (via N-terminus) with UBXN7, UBXN8, and probably several other UBX domain-containing proteins (via UBX domains); the interactions are mutually exclusive with VIM-dependent interactions such as those with AMFR and SELENOS. Forms a complex with UBQLN1 and UBXN4. Interacts (via the PIM motif) with RNF31 (via the PUB domain) (PubMed:24726327). Interacts with RIGI and RNF125; interaction takes place when RIGI is ubiquitinated via 'Lys-63'-linked ubiquitin on its CARD domains, leading to recruit RNF125 and promote ubiquitination and degradation of RIGI (PubMed:26471729). Interacts with BAG6 (PubMed:21636303). Interacts with UBXN10 (PubMed:26389662). Interacts with UBXN6; the interaction with UBXN6 is direct and competitive with UFD1 (PubMed:19174149, PubMed:19275885). Forms a ternary complex with CAV1 and UBXN6 (PubMed:18656546, PubMed:19174149, PubMed:21822278). Interacts with PLAA, UBXN6 and YOD1; may form a complex involved in macroautophagy (PubMed:27753622). Interacts with ANKZF1 (PubMed:28302725). Interacts with ubiquitin-binding protein FAF1 (PubMed:26842564). Interacts with ZFAND2B (via VIM motif); the interaction is direct (PubMed:24160817, PubMed:26337389). Interacts with ZFAND1 (via its ubiquitin-like region); this interaction occurs in an arsenite-dependent manner (PubMed:29804830). Interacts with CCDC47 (By similarity). Interacts with UBAC2 (By similarity). Interacts with LMBR1L (PubMed:31073040). Interacts with ATXN3 (PubMed:30455355). Interacts with TEX264; bridging VCP to covalent DNA-protein cross-links (DPCs) (PubMed:32152270). Interacts with FBXL4 (PubMed:36896912)","family":"Belongs to the AAA ATPase family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["15456787","16168377","16186510","20104022","21118995","21822278","22020440","22120668","22607976","23042605","23042607","23335559","26265139","26471729","26565908","26692333","27753622","29804830","32152270","34739333","35013556","38762759"],"location":"Cytoplasm, cytosol；Endoplasmic reticulum；Nucleus；Cytoplasm, Stress granule","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"泛素化/蛋白稳态；染色质/转录调控；DNA修复/复制；细胞周期/分裂；膜运输/高尔基/内吞；免疫/炎症/细胞死亡；线粒体/代谢；黏附/受体/细胞表面；注释原文：Necessary for the fragmentation of Golgi stacks during mitosis and for their reassembly after mitosis.","function_evidence":"含实验支持条目；含同源推断，不能当该成员实测；ECO:0000250,ECO:0000269","categories":"泛素化/蛋白稳态；染色质/转录调控；DNA修复/复制；细胞周期/分裂；膜运输/高尔基/内吞；免疫/炎症/细胞死亡；线粒体/代谢；黏附/受体/细胞表面"},"VCPIP1":{"hgnc":"HGNC:30897","symbol":"VCPIP1","accessions":["Q96JH7"],"name":"Deubiquitinating protein VCPIP1","length":"1222","function":"Deubiquitinating enzyme involved in DNA repair and reassembly of the Golgi apparatus and the endoplasmic reticulum following mitosis (PubMed:32649882). Necessary for VCP-mediated reassembly of Golgi stacks after mitosis (By similarity). Plays a role in VCP-mediated formation of transitional endoplasmic reticulum (tER) (By similarity). Mediates dissociation of the ternary complex containing STX5A, NSFL1C and VCP (By similarity). Also involved in DNA repair following phosphorylation by ATM or ATR: acts by catalyzing deubiquitination of SPRTN, thereby promoting SPRTN recruitment to chromatin and subsequent proteolytic cleavage of covalent DNA-protein cross-links (DPCs) (PubMed:32649882). Hydrolyzes 'Lys-11'- and 'Lys-48'-linked polyubiquitin chains (PubMed:23827681)\n(Microbial infection) Regulates the duration of C.botulinum neurotoxin type A (BoNT/A) intoxication by catalyzing deubiquitination of Botulinum neurotoxin A light chain (LC), thereby preventing LC degradation by the proteasome, and accelerating botulinum neurotoxin intoxication in patients","subunit":"Binds VCP and the ternary complex containing STX5A, NSFL1C and VCP","family":"","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["23827681","28584101","32649882"],"location":"Nucleus；Cytoplasm；Endoplasmic reticulum；Golgi apparatus, Golgi stack","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"泛素化/蛋白稳态；染色质/转录调控；DNA修复/复制；细胞周期/分裂；激酶/磷酸化信号；膜运输/高尔基/内吞；注释原文：Deubiquitinating enzyme involved in DNA repair and reassembly of the Golgi apparatus and the endoplasmic reticulum following mitosis (PubMed:32649882).","function_evidence":"含实验支持条目；含同源推断，不能当该成员实测；ECO:0000250,ECO:0000269","categories":"泛素化/蛋白稳态；染色质/转录调控；DNA修复/复制；细胞周期/分裂；激酶/磷酸化信号；膜运输/高尔基/内吞"},"VCX":{"hgnc":"HGNC:12667","symbol":"VCX","accessions":["Q9H320"],"name":"Variable charge X-linked protein 1","length":"206","function":"May mediate a process in spermatogenesis or may play a role in sex ratio distortion","subunit":"","family":"Belongs to the VCX/VCY family","domains":[],"function_pmids":[],"location":"","shared_sequence_gene_count":"1","source_snapshot":"project UniProt records20261017/18","brief":"May mediate a process in spermatogenesis or may play a role in sex ratio distortion"},"VENTX":{"hgnc":"HGNC:13639","symbol":"VENTX","accessions":["O95231"],"name":"Homeobox protein VENTX","length":"258","function":"May be involved in ventralization","subunit":"无可用SUBUNIT段","family":"","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":[],"location":"Nucleus","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"；注释原文：May be involved in ventralization","function_evidence":"数据库整理/推断；按原文限定；","categories":"未归类"},"VEZF1":{"hgnc":"HGNC:12949","symbol":"VEZF1","accessions":["Q14119"],"name":"Vascular endothelial zinc finger 1","length":"521","function":"Possible transcription factor. Specifically binds to the CT/GC-rich region of the interleukin-3 promoter and mediates tax transactivation of IL-3","subunit":"Interacts with ARHGAP22","family":"Belongs to the krueppel C2H2-type zinc-finger protein family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["36657711","8035792"],"location":"Nucleus","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"染色质/转录调控；注释原文：Possible transcription factor.","function_evidence":"含实验支持条目；ECO:0000269","categories":"染色质/转录调控"},"VEZT":{"hgnc":"HGNC:18258","symbol":"VEZT","accessions":["Q9HBM0"],"name":"Vezatin","length":"779","function":"Plays a pivotal role in the establishment of adherens junctions and their maintenance in adult life. Required for morphogenesis of the preimplantation embryo, and for the implantation process\n(Microbial infection) In case of Listeria infection, promotes bacterial internalization by participating in myosin VIIa recruitment to the entry site","subunit":"Interacts with USH2A (via the cytoplasmic region); the interaction associates VEZT with the USH2 complex at the stereocilia base (By similarity). Interacts with myosin MYO7A and the cadherin-catenins complex (PubMed:11080149)","family":"Belongs to the vezatin family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["15090598"],"location":"Cell membrane；Multi-pass membrane protein；Cell projection, stereocilium membrane；Cell junction, adherens junction；Nucleus；Cytoplasmic vesicle, secretory vesicle, acrosome","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"；注释原文：Plays a pivotal role in the establishment of adherens junctions and their maintenance in adult life.","function_evidence":"含实验支持条目；含同源推断，不能当该成员实测；ECO:0000250,ECO:0000269","categories":"未归类"},"VGLL3":{"hgnc":"HGNC:24327","symbol":"VGLL3","accessions":["A8MV65"],"name":"Transcription cofactor vestigial-like protein 3","length":"326","function":"May act as a specific coactivator for the mammalian TEFs","subunit":"无可用SUBUNIT段","family":"Belongs to the vestigial family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":[],"location":"Nucleus","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"染色质/转录调控；注释原文：May act as a specific coactivator for the mammalian TEFs","function_evidence":"含同源推断，不能当该成员实测；ECO:0000250","categories":"染色质/转录调控"},"VHL":{"hgnc":"HGNC:12687","symbol":"VHL","accessions":["P40337"],"name":"von Hippel-Lindau disease tumor suppressor","length":"213","function":"Involved in the ubiquitination and subsequent proteasomal degradation via the von Hippel-Lindau ubiquitination complex (PubMed:10944113, PubMed:17981124, PubMed:19584355). Seems to act as a target recruitment subunit in the E3 ubiquitin ligase complex and recruits hydroxylated hypoxia-inducible factor (HIF) under normoxic conditions (PubMed:10944113, PubMed:17981124). Involved in transcriptional repression through interaction with HIF1A, HIF1AN and histone deacetylases (PubMed:10944113, PubMed:17981124). Ubiquitinates, in an oxygen-responsive manner, ADRB2 (PubMed:19584355). Acts as a negative regulator of mTORC1 by promoting ubiquitination and degradation of RPTOR (PubMed:34290272)","subunit":"Component of the VCB (VHL-Elongin BC-CUL2) complex; this complex acts as a ubiquitin-ligase E3 and directs proteasome-dependent degradation of targeted proteins. Interacts with CUL2; this interaction is dependent on the integrity of the trimeric VCB complex. Interacts (via the beta domain) with HIF1A (via the NTAD domain); this interaction mediates degradation of HIF1A in normoxia and, in hypoxia, prevents ubiquitination and degradation of HIF1A by mediating hypoxia-induced translocation to the nucleus, a process which requires a hypoxia-dependent regulatory signal. Interacts with ADRB2; the interaction, in normoxia, is dependent on hydroxylation of ADRB2 and the subsequent VCB-mediated ubiquitination and degradation of ADRB2. Under hypoxia, hydroxylation, interaction with VHL, ubiquitination and subsequent degradation of ADRB2 are dramatically decreased. Interacts with RNF139, USP33 and JADE1. Found in a complex composed of LIMD1, VHL, EGLN1/PHD2, ELOB and CUL2. Isoform 1 and isoform 3 interact with LIMD1 (via LIM zinc-binding 2), AJUBA (via LIM domains) and WTIP (via LIM domains). Interacts with EPAS1. Interacts with CARD9. Interacts with DCUN1D1 independently of CUL2; this interaction engages DCUN1D1 in the VCB complex and triggers CUL2 neddylation and consequently cullin ring ligase (CRL) substrates polyubiquitylation (PubMed:23401859). Interacts with ALAS1 (hydroxylated form) (PubMed:16234850). Interacts with IGFBP1 (By similarity)","family":"Belongs to the VHL family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["10944113","17981124","19584355","34290272"],"location":"Cytoplasm；Cell membrane；Peripheral membrane protein；Endoplasmic reticulum；Nucleus","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"泛素化/蛋白稳态；染色质/转录调控；注释原文：Involved in the ubiquitination and subsequent proteasomal degradation via the von Hippel-Lindau ubiquitination complex (PubMed:10944113, PubMed:17981124, PubMed:19584355).","function_evidence":"含实验支持条目；ECO:0000269","categories":"泛素化/蛋白稳态；染色质/转录调控"},"VIM":{"hgnc":"HGNC:12692","symbol":"VIM","accessions":["P08670"],"name":"Vimentin","length":"466","function":"Vimentins are class-III intermediate filaments found in various non-epithelial cells, especially mesenchymal cells. Vimentin is attached to the nucleus, endoplasmic reticulum, and mitochondria, either laterally or terminally. Plays a role in cell directional movement, orientation, cell sheet organization and Golgi complex polarization at the cell migration front (By similarity). Protects SCRIB from proteasomal degradation and facilitates its localization to intermediate filaments in a cell contact-mediated manner (By similarity). May promote axon outgrowth and motor fiber repair via DSP-mediated recruitment to outgrowth tips (By similarity)\nInvolved with LARP6 in the stabilization of type I collagen mRNAs for CO1A1 and CO1A2","subunit":"Homomer assembled from elementary dimers (PubMed:20176112). Identified in complexes that contain VIM, EZR, AHNAK, BFSP1, BFSP2, ANK2, PLEC, PRX and spectrin (By similarity). Identified in a complex containing at least DSP, JUP, VIM and CDH2; the complex is more abundant following crush injury in regenerating motor neurons and may promote axon outgrowth and motor fiber repair (By similarity). Interacts with BCAS3 (PubMed:17505058). Interacts with LGSN (By similarity). Interacts with SYNM (By similarity). Interacts (via rod region) with PLEC (via CH 1 domain) (By similarity). Interacts with PLEC isoform 1C (PubMed:24940650). Interacts with STK33 (PubMed:18811945). Interacts with LARP6 (PubMed:21746880). Interacts with RAB8B (By similarity). Interacts with TOR1A; the interaction associates TOR1A with the cytoskeleton (PubMed:16361107, PubMed:18827015). Interacts with TOR1AIP1 (PubMed:16361107). Interacts with DIAPH1 (PubMed:23325789). Interacts with EPPK1; interaction is dependent of higher-order structure of intermediate filament (PubMed:16923132). Interacts with the non-receptor tyrosine kinase SRMS; the interaction leads to phosphorylation of VIM (PubMed:29496907). Interacts with NOD2 (PubMed:27812135). Interacts (via head region) with CORO1C (By similarity). Interacts with HDGF (isoform 2) (PubMed:26845719). Interacts with PRKCE (via phorbol-ester/DAG-type 2 domain) (PubMed:18408015). Interacts with BFSP2 (By similarity). Interacts with PPL (By similarity). Interacts (via rod domain) with PKP1 (PubMed:10852826). Interacts with PKP2 (PubMed:10852826). Interacts with SCRIB (via PDZ domains); the interaction protects SCRIB from proteasomal degradation and facilitates SCRIB localization to intermediate filaments, the interaction is reduced by cell contact inhibition (PubMed:19386766)\n(Microbial infection) Interacts with HCV core protein\n(Microbial infection) Interacts with Chandipura virus glycoprotein; this interaction might facilitate the binding of the virus to the cells","family":"Belongs to the intermediate filament family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["21746880"],"location":"Cytoplasm；Cytoplasm, cytoskeleton；Nucleus matrix；Cell membrane；Cell projection, axon","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"泛素化/蛋白稳态；膜运输/高尔基/内吞；线粒体/代谢；注释原文：Vimentins are class-III intermediate filaments found in various non-epithelial cells, especially mesenchymal cells.","function_evidence":"含实验支持条目；含同源推断，不能当该成员实测；ECO:0000250,ECO:0000269","categories":"泛素化/蛋白稳态；膜运输/高尔基/内吞；线粒体/代谢"},"VIRMA":{"hgnc":"HGNC:24500","symbol":"VIRMA","accessions":["Q69YN4"],"name":"Protein virilizer homolog","length":"1812","function":"Associated component of the WMM complex, a complex that mediates N6-methyladenosine (m6A) methylation of RNAs, a modification that plays a role in the efficiency of mRNA splicing and RNA processing (PubMed:24981863, PubMed:29507755). Acts as a key regulator of m6A methylation by promoting m6A methylation of mRNAs in the 3'-UTR near the stop codon: recruits the catalytic core components METTL3 and METTL14, thereby guiding m6A methylation at specific sites (PubMed:29507755). Required for mRNA polyadenylation via its role in selective m6A methylation: m6A methylation of mRNAs in the 3'-UTR near the stop codon correlating with alternative polyadenylation (APA) (PubMed:29507755)","subunit":"Component of the WMM complex, a N6-methyltransferase complex composed of a catalytic subcomplex, named MAC, and of an associated subcomplex, named MACOM (PubMed:29507755). The MAC subcomplex is composed of METTL3 and METTL14. The MACOM subcomplex is composed of WTAP, ZC3H13, CBLL1/HAKAI, VIRMA, and, in some cases of RBM15 (RBM15 or RBM15B) (PubMed:24981863, PubMed:29507755). Interacts with WTAP (PubMed:24100041). Also a component of a MACOM-like complex, named WTAP complex, composed of WTAP, ZC3H13, CBLL1, VIRMA, RBM15, BCLAF1 and THRAP3 (PubMed:24100041). Interacts with NUDT21 and CPSF6 (PubMed:29507755)","family":"Belongs to the vir family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["24981863","29507755"],"location":"Nucleus speckle；Nucleus, nucleoplasm；Cytoplasm","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"RNA加工/剪接；注释原文：Associated component of the WMM complex, a complex that mediates N6-methyladenosine (m6A) methylation of RNAs, a modification that plays a role in the efficiency of mRNA splicing and RNA processing (PubMed:24981863, PubMed:29507755).","function_evidence":"含实验支持条目；ECO:0000269","categories":"RNA加工/剪接"},"VMP1":{"hgnc":"HGNC:29559","symbol":"VMP1","accessions":["Q96GC9"],"name":"Vacuole membrane protein 1","length":"406","function":"Phospholipid scramblase involved in lipid homeostasis and membrane dynamics processes (PubMed:33850023, PubMed:33929485). Has phospholipid scramblase activity toward cholesterol and phosphatidylserine, as well as phosphatidylethanolamine and phosphatidylcholine (PubMed:33850023, PubMed:33929485). Required for autophagosome formation: participates in early stages of autophagosome biogenesis at the endoplasmic reticulum (ER) membrane by reequilibrating the leaflets of the ER as lipids are extracted by ATG2 (ATG2A or ATG2B) to mediate autophagosome assembly (PubMed:28890335, PubMed:30093494, PubMed:30933966, PubMed:33850023, PubMed:33929485). Regulates ATP2A2 activity to control ER-isolation membrane contacts for autophagosome formation (PubMed:28890335). In addition to autophagy, involved in other processes in which phospholipid scramblase activity is required (PubMed:31526472, PubMed:33850023). Modulates ER contacts with lipid droplets, mitochondria and endosomes (PubMed:28890335). Plays an essential role in formation of cell junctions (PubMed:17724469). Upon stress such as bacterial and viral infection, promotes formation of cytoplasmic vacuoles followed by cell death (By similarity). Involved in the cytoplasmic vacuolization of acinar cells during the early stage of acute pancreatitis (By similarity)\n(Microbial infection) Host factor required for infection by all flaviviruses tested such as Zika virus and Yellow fever virus (PubMed:33338421). Probably required post-entry of the virus to facilitate the ER membrane remodeling necessary to form replication organelles (PubMed:33338421)","subunit":"Interacts with BECN1 (By similarity). Interacts with TJP1 (PubMed:17724469). Interacts with TP53INP2 (PubMed:19056683). Interacts with TMEM41B (PubMed:30093494). Interacts with ATP2A2, PLN and SLN; competes with PLN and SLN to prevent them from forming an inhibitory complex with ATP2A2 (PubMed:28890335). Interacts with ATG2A (PubMed:33850023)","family":"Belongs to the VMP1 family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["17724469","28890335","30093494","30933966","31526472","33338421","33850023","33929485"],"location":"Endoplasmic reticulum-Golgi intermediate compartment membrane；Multi-pass membrane protein；Cell membrane；Vacuole membrane；Endoplasmic reticulum membrane","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"膜运输/高尔基/内吞；线粒体/代谢；注释原文：Phospholipid scramblase involved in lipid homeostasis and membrane dynamics processes (PubMed:33850023, PubMed:33929485).","function_evidence":"含实验支持条目；含同源推断，不能当该成员实测；ECO:0000250,ECO:0000269","categories":"膜运输/高尔基/内吞；线粒体/代谢"}};
